"use strict";
// SELAH: the Douay-Rheims Psalter (Challoner, public domain), in the Vulgate numbering, in the
// same shape as a pack file. Made by tools/build-douay.js; do not edit by hand.
const DOUAY = {"selahPack":1,"id":"douay","displayName":"Douay","name":"Douay-Rheims (Challoner)","numbering":"vulgate","titlesCounted":true,"license":"public domain","language":"en","psalms":[{"n":1,"incipit":"Beatus vir qui non abiit","verses":[{"v":1,"lines":["Blessed is the man who hath not walked in the counsel of the ungodly, nor stood in the way of sinners, nor sat in the chair of pestilence:"]},{"v":2,"lines":["But his will is in the law of the Lord, and on his law he shall meditate day and night."]},{"v":3,"lines":["And he shall be like a tree which is planted near the running waters, which shall bring forth its fruit, in due season. And his leaf shall not fall off:","and all whatsoever he shall do shall prosper."]},{"v":4,"lines":["Not so the wicked, not so:","but like the dust, which the wind driveth from the face of the earth."]},{"v":5,"lines":["Therefore the wicked shall not rise again in judgment:","nor sinners in the council of the just."]},{"v":6,"lines":["For the Lord knoweth the way of the just:","and the way of the wicked shall perish."]}]},{"n":2,"incipit":"Quare fremuerunt gentes","verses":[{"v":1,"lines":["Why have the Gentiles raged, and the people devised vain things?"]},{"v":2,"lines":["The kings of the earth stood up, and the princes met together, against the Lord, and against his Christ."]},{"v":3,"lines":["Let us break their bonds asunder:","and let us cast away their yoke from us."]},{"v":4,"lines":["He that dwelleth in heaven shall laugh at them:","and the Lord shall deride them."]},{"v":5,"lines":["Then shall he speak to them in his anger, and trouble them in his rage."]},{"v":6,"lines":["But I am appointed king by him over Sion, his holy mountain, preaching his commandment."]},{"v":7,"lines":["The Lord hath said to me:","Thou art my son, this day have I begotten thee."]},{"v":8,"lines":["Ask of me, and I will give thee the Gentiles for thy inheritance, and the utmost parts of the earth for thy possession."]},{"v":9,"lines":["Thou shalt rule them with a rod of iron, and shalt break them in pieces like a potter's vessel."]},{"v":10,"lines":["And now, O ye kings, understand:","receive instruction, you that judge the earth."]},{"v":11,"lines":["Serve ye the Lord with fear:","and rejoice unto him with trembling."]},{"v":12,"lines":["Embrace discipline, lest at any time the Lord be angry, and you perish from the just way."]},{"v":13,"lines":["When his wrath shall be kindled in a short time, blessed are all they that trust in him."]}]},{"n":3,"incipit":"Domine, quid multiplicati","verses":[{"v":1,"lines":["The psalm of David when he fled from the face of his son Absalom."],"title":true},{"v":2,"lines":["Why, O Lord, are they multiplied that afflict me? Many are they who rise up against me."]},{"v":3,"lines":["Many say to my soul:","There is no salvation for him in his God."]},{"v":4,"lines":["But thou, O Lord, art my protector, my glory, and the lifter up of my head."]},{"v":5,"lines":["I have cried to the Lord with my voice:","and he hath heard me from his holy hill."]},{"v":6,"lines":["I have slept and taken my rest:","and I have risen up, because the Lord hath protected me."]},{"v":7,"lines":["I will not fear thousands of the people surrounding me:","arise, O Lord;","save me, O my God."]},{"v":8,"lines":["For thou hast struck all them who are my adversaries without cause:","thou hast broken the teeth of sinners."]},{"v":9,"lines":["Salvation is of the Lord:","and thy blessing is upon thy people."]}]},{"n":4,"incipit":"Cum invocarem","verses":[{"v":1,"lines":["Unto the end, in verses. A psalm for David."],"title":true},{"v":2,"lines":["When I called upon him, the God of my justice heard me:","when I was in distress, thou hast enlarged me. Have mercy on me:","and hear my prayer."]},{"v":3,"lines":["O ye sons of men, how long will you be dull of heart? why do you love vanity, and seek after lying?"]},{"v":4,"lines":["Know ye also that the Lord hath made his holy one wonderful:","the Lord will hear me when I shall cry unto him."]},{"v":5,"lines":["Be angry, and sin not:","the things you say in your hearts, be sorry for them upon your beds."]},{"v":6,"lines":["Offer up the sacrifice of justice, and trust in the Lord:","many say, Who sheweth us good things?"]},{"v":7,"lines":["The light of thy countenance, O Lord, is signed upon us:","thou hast given gladness in my heart."]},{"v":8,"lines":["By the fruit of their corn, their wine and oil, they are multiplied."]},{"v":9,"lines":["In peace in the selfsame I will sleep, and I will rest:"]},{"v":10,"lines":["For thou, O Lord, singularly hast settled me in hope."]}]},{"n":5,"incipit":"Verba mea auribus","verses":[{"v":1,"lines":["Unto the end, for her that obtaineth the inheritance. A psalm for David."],"title":true},{"v":2,"lines":["Give ear, O Lord, to my words, understand my cry."]},{"v":3,"lines":["Hearken to the voice of my prayer, O my King and my God."]},{"v":4,"lines":["For to thee will I pray:","O Lord, in the morning thou shalt hear my voice."]},{"v":5,"lines":["In the morning I will stand before thee, and will see:","because thou art not a God that willest iniquity."]},{"v":6,"lines":["Neither shall the wicked dwell near thee:","nor shall the unjust abide before thy eyes."]},{"v":7,"lines":["Thou hatest all the workers of iniquity:","thou wilt destroy all that speak a lie. The bloody and the deceitful man the Lord will abhor."]},{"v":8,"lines":["But as for me in the multitude of thy mercy, I will come into thy house;","I will worship towards thy holy temple, in thy fear."]},{"v":9,"lines":["Conduct me, O Lord, in thy justice:","because of my enemies, direct my way in thy sight."]},{"v":10,"lines":["For there is no truth in their mouth:","their heart is vain."]},{"v":11,"lines":["Their throat is an open sepulchre:","they dealt deceitfully with their tongues:","judge them, O God. Let them fall from their devices:","according to the multitude of their wickedness cast them out:","for they have provoked thee, O Lord."]},{"v":12,"lines":["But let all them be glad that hope in thee:","they shall rejoice for ever, and thou shalt dwell in them. And all they that love thy name shall glory in thee."]},{"v":13,"lines":["For thou wilt bless the just. O Lord, thou hast crowned us, as with a shield of thy good will."]}]},{"n":6,"incipit":"Domine, ne in furore","verses":[{"v":1,"lines":["Unto the end, in verses, a psalm for David, for the octave."],"title":true},{"v":2,"lines":["O Lord, rebuke me not in thy indignation, nor chastise me in thy wrath."]},{"v":3,"lines":["Have mercy on me, O Lord, for I am weak:","heal me, O Lord, for my bones are troubled."]},{"v":4,"lines":["And my soul is troubled exceedingly:","but thou, O Lord, how long?"]},{"v":5,"lines":["Turn to me, O Lord, and deliver my soul:","O save me for thy mercy's sake."]},{"v":6,"lines":["For there is no one in death, that is mindful of thee:","and who shall confess to thee in hell?"]},{"v":7,"lines":["I have laboured in my groanings, every night I will wash my bed:","I will water my couch with my tears."]},{"v":8,"lines":["My eye is troubled through indignation:","I have grown old amongst all my enemies."]},{"v":9,"lines":["Depart from me, all ye workers of iniquity:","for the Lord hath heard the voice of my weeping."]},{"v":10,"lines":["The Lord hath heard my supplication:","the Lord hath received my prayer."]},{"v":11,"lines":["Let all my enemies be ashamed, and be very much troubled:","let them be turned back, and be ashamed very speedily."]}]},{"n":7,"incipit":"Domine, Deus meus","verses":[{"v":1,"lines":["The psalm of David, which he sung to the Lord, for the words of Chusi, the son of Jemini."],"title":true},{"v":2,"lines":["O Lord my God, in thee have I put my trust:","save me from all them that persecute me, and deliver me."]},{"v":3,"lines":["Lest at any time he seize upon my soul like a lion, while there is no one to redeem me, nor to save."]},{"v":4,"lines":["O Lord, my God, if I have done this thing, if there be iniquity in my hands:"]},{"v":5,"lines":["If I have rendered to them that repaid me evils, let me deservedly fall empty before my enemies."]},{"v":6,"lines":["Let the enemy pursue my soul, and take it, and tread down my life, on the earth, and bring down my glory to the dust."]},{"v":7,"lines":["Rise up, O Lord, in thy anger:","and be thou exalted in the borders of my enemies. And arise, O Lord, my God, in the precept which thou hast commanded:"]},{"v":8,"lines":["And a congregation of people shall surround thee. And for their sakes return thou on high."]},{"v":9,"lines":["The Lord judgeth the people. Judge me, O Lord, according to my justice, and according to my innocence in me."]},{"v":10,"lines":["The wickedness of sinners shall be brought to nought;","and thou shalt direct the just:","the searcher of hearts and reins is God."]},{"v":11,"lines":["Just is my help from the Lord;","who saveth the upright of heart."]},{"v":12,"lines":["God is a just judge, strong and patient:","is he angry every day?"]},{"v":13,"lines":["Except you will be converted, he will brandish his sword;","he hath bent his bow, and made it ready."]},{"v":14,"lines":["And in it he hath prepared the instruments of death, he hath made ready his arrows for them that burn ."]},{"v":15,"lines":["Behold he hath been in labour with injustice:","he hath conceived sorrow, and brought forth iniquity."]},{"v":16,"lines":["He hath opened a pit and dug it:","and he is fallen into the hole he made."]},{"v":17,"lines":["His sorrow shall be turned on his own head:","and his iniquity shall come down upon his crown."]},{"v":18,"lines":["I will give glory to the Lord according to his justice:","and will sing to the name of the Lord the most high."]}]},{"n":8,"incipit":"Domine, Dominus noster","verses":[{"v":1,"lines":["Unto the end, for the presses: a psalm for David."],"title":true},{"v":2,"lines":["O Lord, our Lord, how admirable is thy name in the whole earth! For thy magnificence is elevated above the heavens."]},{"v":3,"lines":["Out of the mouth of infants and of sucklings thou hast perfected praise, because of thy enemies, that thou mayst destroy the enemy and the avenger."]},{"v":4,"lines":["For I will behold thy heavens, the works of thy fingers:","the moon and the stars which thou hast founded."]},{"v":5,"lines":["What is man, that thou art mindful of him? or the son of man, that thou visitest him?"]},{"v":6,"lines":["Thou hast made him a little less than the angels, thou hast crowned him with glory and honour:"]},{"v":7,"lines":["And hast set him over the works of thy hands."]},{"v":8,"lines":["Thou hast subjected all things under his feet, all sheep and oxen:","moreover, the beasts also of the fields."]},{"v":9,"lines":["The birds of the air, and the fishes of the sea, that pass through the paths of the sea."]},{"v":10,"lines":["O Lord our Lord, how admirable is thy name in all the earth!"]}]},{"n":9,"incipit":"Confitebor tibi · Ut quid Domine","verses":[{"v":1,"lines":["Unto the end, for the hidden things of the Son. A psalm for David."],"title":true},{"v":2,"lines":["I will give praise to thee, O Lord, with my whole heart:","I will relate all thy wonders."]},{"v":3,"lines":["I will be glad, and rejoice in thee:","I will sing to thy name, O thou most high."]},{"v":4,"lines":["When my enemy shall be turned back:","they shall be weakened, and perish before thy face."]},{"v":5,"lines":["For thou hast maintained my judgment and my cause:","thou hast sat on the throne, who judgest justice."]},{"v":6,"lines":["Thou hast rebuked the Gentiles, and the wicked one hath perished;","thou hast blotted out their name for ever and ever."]},{"v":7,"lines":["The swords of the enemy have failed unto the end:","and their cities thou hast destroyed. Their memory hath perished with a noise:"]},{"v":8,"lines":["But the Lord remaineth for ever. He hath prepared his throne in judgment:"]},{"v":9,"lines":["And he shall judge the world in equity, he shall judge the people in justice."]},{"v":10,"lines":["And the Lord is become a refuge for the poor:","a helper in due time in tribulation."]},{"v":11,"lines":["And let them trust in thee who know thy name:","for thou hast not forsaken them that seek thee, O Lord."]},{"v":12,"lines":["Sing ye to the Lord, who dwelleth in Sion:","declare his ways among the Gentiles:"]},{"v":13,"lines":["For requiring their blood, he hath remembered them:","he hath not forgotten the cry of the poor."]},{"v":14,"lines":["Have mercy on me, O Lord:","see my humiliation which I suffer from my enemies."]},{"v":15,"lines":["Thou that liftest me up from the gates of death, that I may declare all thy praises in the gates of the daughter of Sion."]},{"v":16,"lines":["I will rejoice in thy salvation:","the Gentiles have stuck fast in the destruction which they have prepared. Their foot hath been taken in the very snare which they hid."]},{"v":17,"lines":["The Lord shall be known when he executeth judgments:","the sinner hath been caught in the works of his own hands."]},{"v":18,"lines":["The wicked shall be turned into hell, all the nations that forget God."]},{"v":19,"lines":["For the poor man shall not be forgotten to the end:","the patience of the poor shall not perish for ever."]},{"v":20,"lines":["Arise, O Lord, let not man be strengthened:","let the Gentiles be judged in thy sight."]},{"v":21,"lines":["Appoint, O Lord, a lawgiver over them:","that the Gentiles may know themselves to be but men."]},{"v":22,"lines":["Why, O Lord, hast thou retired afar off? why dost thou slight us in our wants, in the time of trouble?"],"sectionStart":true},{"v":23,"lines":["Whilst the wicked man is proud, the poor is set on fire:","they are caught in the counsels which they devise."]},{"v":24,"lines":["For the sinner is praised in the desires of his soul:","and the unjust man is blessed."]},{"v":25,"lines":["The sinner hath provoked the Lord, according to the multitude of his wrath, he will not seek him:"]},{"v":26,"lines":["God is not before his eyes:","his ways are filthy at all times. Thy judgments are removed from his sight:","he shall rule over all his enemies."]},{"v":27,"lines":["For he hath said in his heart:","I shall not be moved from generation to generation, and shall be without evil."]},{"v":28,"lines":["His mouth is full of cursing, and of bitterness, and of deceit:","under his tongue are labour and sorrow."]},{"v":29,"lines":["He sitteth in ambush with the rich, in private places, that he may kill the innocent."]},{"v":30,"lines":["His eyes are upon the poor man:","He lieth in wait in secret like a lion in his den. He lieth in ambush that he may catch the poor man:","to catch the poor, whilst he draweth him to him."]},{"v":31,"lines":["In his net he will bring him down, he will crouch and fall, when he shall have power over the poor."]},{"v":32,"lines":["For he hath said in his heart:","God hath forgotten, he hath turned away his face, not to see to the end."]},{"v":33,"lines":["Arise, O Lord God, let thy hand be exalted:","forget not the poor."]},{"v":34,"lines":["Wherefore hath the wicked provoked God? for he hath said in his heart:","He will not require it."]},{"v":35,"lines":["Thou seest it, for thou considerest labour and sorrow:","that thou mayst deliver them into thy hands. To thee is the poor man left:","thou wilt be a helper to the orphan."]},{"v":36,"lines":["Break thou the arm of the sinner and of the malignant:","his sin shall be sought, and shall not be found."]},{"v":37,"lines":["The Lord shall reign to eternity, yea, for ever and ever:","ye Gentiles shall perish from his land."]},{"v":38,"lines":["The Lord hath heard the desire of the poor:","thy ear hath heard the preparation of their heart."]},{"v":39,"lines":["To judge for the fatherless and for the humble, that man may no more presume to magnify himself upon earth."]}]},{"n":10,"incipit":"In Domino confido","verses":[{"v":1,"lines":["Unto the end. A psalm to David."],"title":true},{"v":2,"lines":["In the Lord I put my trust:","how then do you say to my soul:","Get thee away from hence to the mountain, like a sparrow."]},{"v":3,"lines":["For, lo, the wicked have bent their bow:","they have prepared their arrows in the quiver, to shoot in the dark the upright of heart."]},{"v":4,"lines":["For they have destroyed the things which thou hast made:","but what has the just man done?"]},{"v":5,"lines":["The Lord is in his holy temple, the Lord's throne is in heaven. His eyes look on the poor man:","his eyelids examine the sons of men."]},{"v":6,"lines":["The Lord trieth the just and the wicked:","but he that loveth iniquity, hateth his own soul."]},{"v":7,"lines":["He shall rain snares upon sinners:","fire and brimstone, and storms of winds, shall be the portion of their cup."]},{"v":8,"lines":["For the Lord is just, and hath loved justice:","his countenance hath beheld righteousness."]}]},{"n":11,"incipit":"Salva me fac","verses":[{"v":1,"lines":["Unto the end: for the octave, a psalm for David."],"title":true},{"v":2,"lines":["Save me, O Lord, for there is now no saint:","truths are decayed from among the children of men."]},{"v":3,"lines":["They have spoken vain things, every one to his neighbour:","with deceitful lips, and with a double heart have they spoken."]},{"v":4,"lines":["May the Lord destroy all deceitful lips, and the tongue that speaketh proud things."]},{"v":5,"lines":["Who have said:","We will magnify our tongue:","our lips are our own:","who is Lord over us?"]},{"v":6,"lines":["By reason of the misery of the needy, and the groans of the poor, now will I arise, saith the Lord. I will set him in safety:","I will deal confidently in his regard."]},{"v":7,"lines":["The words of the Lord are pure words:","as silver tried by the fire, purged from the earth, refined seven times."]},{"v":8,"lines":["Thou, O Lord, wilt preserve us:","and keep us from this generation for ever."]},{"v":9,"lines":["The wicked walk round about:","according to thy highness, thou hast multiplied the children of men."]}]},{"n":12,"incipit":"Usquequo, Domine?","verses":[{"v":1,"lines":["How long, O Lord, wilt thou forget me unto the end? how long dost thou turn away thy face from me?"],"heading":"Unto the end, a psalm for David."},{"v":2,"lines":["How long shall I take counsels in my soul, sorrow in my heart all the day?"]},{"v":3,"lines":["How long shall my enemy be exalted over Me?"]},{"v":4,"lines":["Consider, and hear me, O Lord, my God. Enlighten my eyes, that I never sleep in death:"]},{"v":5,"lines":["Lest at any time my enemy say:","I have prevailed against him. They that trouble me, will rejoice when I am moved:"]},{"v":6,"lines":["But I have trusted in thy mercy. My heart shall rejoice in thy salvation:","I will sing to the Lord, who giveth me good things:","yea, I will sing to the name of the Lord, the most high."]}]},{"n":13,"incipit":"Dixit insipiens","verses":[{"v":1,"lines":["The fool hath said in his heart:","There is no God. They are corrupt, and are become abominable in their ways:","there is none that doth good, no not one."],"heading":"Unto the end, a psalm for David."},{"v":2,"lines":["The Lord hath looked down from heaven upon the children of men, to see if there be any that understand and seek God."]},{"v":3,"lines":["They are all gone aside, they are become unprofitable together:","there is none that doth good:","no not one. Their throat is an open sepulchre;","with their tongues they acted deceitfully:","the poison of asps is under their lips. Their mouth is full of cursing and bitterness;","their feet are swift to shed blood. Destruction and unhappiness in their ways;","and the way of peace they have not known:","there is no fear of God before their eyes."]},{"v":4,"lines":["Shall not all they know that work iniquity, who devour my people as they eat bread?"]},{"v":5,"lines":["They have not called upon the Lord:","there have they trembled for fear, where there was no fear."]},{"v":6,"lines":["For the Lord is in the just generation:","you have confounded the counsel of the poor man;","but the Lord is his hope."]},{"v":7,"lines":["Who shall give out of Sion the salvation of Israel? when the Lord shall have turned away the captivity of his people, Jacob shall rejoice, and Israel shall be glad."]}]},{"n":14,"incipit":"Domine, quis habitabit?","verses":[{"v":1,"lines":["Lord, who shall dwell in thy tabernacle? or who shall rest in thy holy hill?"],"heading":"A psalm for David."},{"v":2,"lines":["He that walketh without blemish, and worketh justice:"]},{"v":3,"lines":["He that speaketh truth in his heart, who hath not used deceit in his tongue:","Nor hath done evil to his neighbour:","nor taken up a reproach against his neighbours."]},{"v":4,"lines":["In his sight the malignant is brought to nothing:","but he glorifieth them that fear the Lord. He that sweareth to his neighbour, and deceiveth not;"]},{"v":5,"lines":["He that hath not put out his money to usury, nor taken bribes against the innocent:","He that doth these things, shall not be moved for ever."]}]},{"n":15,"incipit":"Conserva me, Domine","verses":[{"v":1,"lines":["Preserve me, O Lord, for I have put my trust in thee."],"heading":"The inscription of a title to David himself."},{"v":2,"lines":["I have said to the Lord, thou art my God, for thou hast no need of my goods."]},{"v":3,"lines":["To the saints, who are in his land, he hath made wonderful all my desires in them."]},{"v":4,"lines":["Their infirmities were multiplied:","afterwards they made haste. I will not gather together their meetings for blood offerings:","nor will I be mindful of their names by my lips."]},{"v":5,"lines":["The Lord is the portion of my inheritance and of my cup:","it is thou that wilt restore my inheritance to me."]},{"v":6,"lines":["The lines are fallen unto me in goodly places:","for my inheritance is goodly to me."]},{"v":7,"lines":["I will bless the Lord, who hath given me understanding:","moreover, my reins also have corrected me even till night."]},{"v":8,"lines":["I set the Lord always in my sight:","for he is at my right hand, that I be not moved."]},{"v":9,"lines":["Therefore my heart hath been glad, and my tongue hath rejoiced:","moreover, my flesh also shall rest in hope."]},{"v":10,"lines":["Because thou wilt not leave my soul in hell;","nor wilt thou give thy holy one to see corruption."]},{"v":11,"lines":["Thou hast made known to me the ways of life, thou shalt fill me with joy with thy countenance:","at thy right hand are delights even to the end."]}]},{"n":16,"incipit":"Exaudi Domine","verses":[{"v":1,"lines":["Hear, O Lord, my justice:","attend to my supplication. Give ear unto my prayer, which proceedeth not from deceitful lips."],"heading":"The prayer of David."},{"v":2,"lines":["Let my judgment come forth from thy countenance:","let thy eyes behold the things that are equitable."]},{"v":3,"lines":["Thou hast proved my heart, and visited it by night, thou hast tried me by fire:","and iniquity hath not been found in me."]},{"v":4,"lines":["That my mouth may not speak the works of men:","for the sake of the words of thy lips, I have kept hard ways."]},{"v":5,"lines":["Perfect thou my goings in thy paths:","that my footsteps be not moved."]},{"v":6,"lines":["I have cried to thee, for thou, O God, hast heard me:","O incline thy ear unto me, and hear my words."]},{"v":7,"lines":["Shew forth thy wonderful mercies;","thou who savest them that trust in thee."]},{"v":8,"lines":["From them that resist thy right hand keep me, as the apple of thy eye. Protect me under the shadow of thy wings."]},{"v":9,"lines":["From the face of the wicked who have afflicted me. My enemies have surrounded my soul:"]},{"v":10,"lines":["They have shut up their fat:","their mouth hath spoken proudly."]},{"v":11,"lines":["They have cast me forth, and now they have surrounded me:","they have set their eyes bowing down to the earth."]},{"v":12,"lines":["They have taken me, as a lion prepared for the prey;","and as a young lion dwelling in secret places."]},{"v":13,"lines":["Arise, O Lord, disappoint him and supplant him;","deliver my soul from the wicked one;","thy sword"]},{"v":14,"lines":["From the enemies of thy hand. O Lord, divide them from the few of the earth in their life:","their belly is filled from thy hidden stores. They are full of children:","and they have left to their little ones the rest of their substance."]},{"v":15,"lines":["But as for me, I will appear before thy sight in justice:","I shall be satisfied when thy glory shall appear."]}]},{"n":17,"incipit":"Diligam te, Domine","verses":[{"v":1,"lines":["Unto the end, for David, the servant of the Lord, who spoke to the Lord the words of this canticle, in the day that the Lord delivered him from the hand of all his enemies, and from the hand of Saul: and he said:"],"title":true},{"v":2,"lines":["I will love thee, O Lord, my strength:"]},{"v":3,"lines":["The Lord is my firmament, my refuge, and my deliverer. My God is my helper, and in him will I put my trust. My protector, and the horn of my salvation, and my support."]},{"v":4,"lines":["Praising, I will call upon the Lord:","and I shall be saved from my enemies."]},{"v":5,"lines":["The sorrows of death surrounded me:","and the torrents of iniquity troubled me."]},{"v":6,"lines":["The sorrows of hell encompassed me:","and the snares of death prevented me."]},{"v":7,"lines":["In my affliction I called upon the Lord, and I cried to my God:","And he heard my voice from his holy temple:","and my cry before him came into his ears."]},{"v":8,"lines":["The earth shook and trembled:","the foundations of the mountains were troubled and were moved, because he was angry with them."]},{"v":9,"lines":["There went up a smoke in his wrath:","and a fire flamed from his face:","coals were kindled by it."]},{"v":10,"lines":["He bowed the heavens, and came down, and darkness was under his feet."]},{"v":11,"lines":["And he ascended upon the cherubim, and he flew;","he flew upon the wings of the winds."]},{"v":12,"lines":["And he made darkness his covert, his pavilion round about him:","dark waters in the clouds of the air."]},{"v":13,"lines":["At the brightness that was before him the clouds passed, hail and coals of fire."]},{"v":14,"lines":["And the Lord thundered from heaven, and the Highest gave his voice:","hail and coals of fire."]},{"v":15,"lines":["And he sent forth his arrows, and he scattered them:","he multiplied lightnings, and troubled them."]},{"v":16,"lines":["Then the fountains of waters appeared, and the foundations of the world were discovered:","At thy rebuke, O Lord, at the blast of the spirit of thy wrath."]},{"v":17,"lines":["He sent from on high, and took me:","and received me out of many waters."]},{"v":18,"lines":["He delivered me from my strongest enemies, and from them that hated me:","for they were too strong for me."]},{"v":19,"lines":["They prevented me in the day of my affliction:","and the Lord became my protector."]},{"v":20,"lines":["And he brought me forth into a large place:","he saved me, because he was well pleased with me."]},{"v":21,"lines":["And the Lord will reward me according to my justice;","and will repay me according to the cleanness of my hands:"]},{"v":22,"lines":["Because I have kept the ways of the Lord;","and have not done wickedly against my God."]},{"v":23,"lines":["For till his judgments are in my sight:","and his justices I have not put away from me."]},{"v":24,"lines":["And I shall be spotless with him:","and shall keep myself from my iniquity."]},{"v":25,"lines":["And the Lord will reward me according to my justice:","and according to the cleanness of my hands before his eyes."]},{"v":26,"lines":["With the holy thou wilt be holy;","and with the innocent man thou wilt be innocent:"]},{"v":27,"lines":["And with the elect thou wilt be elect:","and with the perverse thou wilt be perverted."]},{"v":28,"lines":["For thou wilt save the humble people;","but wilt bring down the eyes of the proud."]},{"v":29,"lines":["For thou lightest my lamp, O Lord:","O my God, enlighten my darkness."]},{"v":30,"lines":["For by thee I shall be delivered from temptation;","and through my God I shall go over a wall."]},{"v":31,"lines":["As for my God, his way is undefiled:","the words of the Lord are fire-tried:","he is the protector of all that trust in him."]},{"v":32,"lines":["For who is God but the Lord? or who is God but our God?"]},{"v":33,"lines":["God, who hath girt me with strength;","and made my way blameless."]},{"v":34,"lines":["Who hath made my feet like the feet of harts:","and who setteth me upon high places."]},{"v":35,"lines":["Who teacheth my hands to war:","and thou hast made my arms like a brazen bow."]},{"v":36,"lines":["And thou hast given me the protection of thy salvation:","and thy right hand hath held me up:","And thy discipline hath corrected me unto the end:","and thy discipline, the same shall teach me."]},{"v":37,"lines":["Thou hast enlarged my steps under me;","and my feet are not weakened."]},{"v":38,"lines":["I will pursue after my enemies, and overtake them:","and I will not turn again till they are consumed."]},{"v":39,"lines":["I will break them, and they shall not be able to stand:","they shall fall under my feet."]},{"v":40,"lines":["And thou hast girded me with strength unto battle;","and hast subdued under me them that rose up against me."]},{"v":41,"lines":["And thou hast made my enemies turn their back upon me, and hast destroyed them that hated me."]},{"v":42,"lines":["They cried, but there was none to save them, to the Lord:","but he heard them not."]},{"v":43,"lines":["And I shall beat them as small as the dust before the wind;","I shall bring them to nought, like the dirt in the streets."]},{"v":44,"lines":["Thou wilt deliver me from the contradictions of the people;","thou wilt make me head of the Gentiles."]},{"v":45,"lines":["A people which I knew not, hath served me:","at the hearing of the ear they have obeyed me."]},{"v":46,"lines":["The children that are strangers have lied to me, strange children have faded away, and have halted from their paths."]},{"v":47,"lines":["The Lord liveth, and blessed be my God, and let the God of my salvation be exalted:"]},{"v":48,"lines":["O God, who avengest me, and subduest the people under me, my deliverer from my enemies."]},{"v":49,"lines":["And thou wilt lift me up above them that rise up against me:","from the unjust man thou wilt deliver me."]},{"v":50,"lines":["Therefore will I give glory to thee, O Lord, among the nations, and I will sing a psalm to thy name."]},{"v":51,"lines":["Giving great deliverance to his king, and shewing mercy to David, his anointed:","and to his seed for ever."]}]},{"n":18,"incipit":"Caeli enarrant","verses":[{"v":1,"lines":["Unto the end. A Psalm for David."],"title":true},{"v":2,"lines":["The heavens shew forth the glory of God, and the firmament declareth the work of his hands."]},{"v":3,"lines":["Day to day uttereth speech, and night to night sheweth knowledge."]},{"v":4,"lines":["There are no speeches nor languages, where their voices are not heard."]},{"v":5,"lines":["Their sound hath gone forth into all the earth:","and their words unto the ends of the world."]},{"v":6,"lines":["He hath set his tabernacle in the sun:","and he, as a bridegroom coming out of his bride chamber, Hath rejoiced as a giant to run the way:"]},{"v":7,"lines":["His going out is from the end of heaven, And his circuit even to the end thereof:","and there is no one that can hide himself from his heat."]},{"v":8,"lines":["The law of the Lord is unspotted, converting souls:","the testimony of the Lord is faithful, giving wisdom to little ones."]},{"v":9,"lines":["The justices of the Lord are right, rejoicing hearts:","the commandment of the Lord is lightsome, enlightening the eyes."]},{"v":10,"lines":["The fear of the Lord is holy, enduring for ever and ever:","the judgments of the Lord are true, justified in themselves."]},{"v":11,"lines":["More to be desired than gold and many precious stones:","and sweeter than honey and the honeycomb."]},{"v":12,"lines":["For thy servant keepeth them, and in keeping them there is a great reward."]},{"v":13,"lines":["Who can understand sins? from my secret ones cleanse me, O Lord:"]},{"v":14,"lines":["And from those of others spare thy servant. If they shall have no dominion over me, then shall I be without spot:","and I shall be cleansed from the greatest sin."]},{"v":15,"lines":["And the words of my mouth shall be such as may please:","and the meditation of my heart always in thy sight. O Lord, my helper and my Redeemer."]}]},{"n":19,"incipit":"Exaudiat te Dominus","verses":[{"v":1,"lines":["Unto the end. A psalm for David."],"title":true},{"v":2,"lines":["May the Lord hear thee in the day of tribulation:","may the name of the God of Jacob protect thee."]},{"v":3,"lines":["May he send thee help from the sanctuary:","and defend thee out of Sion."]},{"v":4,"lines":["May he be mindful of all thy sacrifices:","and may thy whole burnt offering be made fat."]},{"v":5,"lines":["May he give thee according to thy own heart;","and confirm all thy counsels."]},{"v":6,"lines":["We will rejoice in thy salvation;","and in the name of our God we shall be exalted."]},{"v":7,"lines":["The Lord fulfill all thy petitions:","now have I known that the Lord hath saved his anointed. He will hear him from his holy heaven:","the salvation of his right hand is in powers ."]},{"v":8,"lines":["Some trust in chariots, and some in horses:","but we will call upon the name of the Lord, our God."]},{"v":9,"lines":["They are bound, and have fallen:","but we are risen, and are set upright. O Lord, save the king:","and hear us in the day that we shall call upon thee."]}]},{"n":20,"incipit":"Domine, in virtute tua","verses":[{"v":1,"lines":["Unto the end. A psalm for David."],"title":true},{"v":2,"lines":["In thy strength, O Lord, the king shall joy;","and in thy salvation he shall rejoice exceedingly."]},{"v":3,"lines":["Thou hast given him his heart's desire:","and hast not withholden from him the will of his lips."]},{"v":4,"lines":["For thou hast prevented him with blessings of sweetness:","thou hast set on his head a crown of precious stones."]},{"v":5,"lines":["He asked life of thee:","and thou hast given him length of days for ever and ever."]},{"v":6,"lines":["His glory is great in thy salvation:","glory and great beauty shalt thou lay upon him."]},{"v":7,"lines":["For thou shalt give him to be a blessing for ever and ever:","thou shalt make him joyful in gladness with thy countenance."]},{"v":8,"lines":["For the king hopeth in the Lord:","and through the mercy of the most High he shall not be moved."]},{"v":9,"lines":["Let thy hand be found by all thy enemies:","let thy right hand find out all them that hate thee."]},{"v":10,"lines":["Thou shalt make them as an oven of fire, in the time of thy anger:","the Lord shall trouble them in his wrath, and fire shall devour them."]},{"v":11,"lines":["Their fruit shalt thou destroy from the earth:","and their seed from among the children of men."]},{"v":12,"lines":["For they have intended evils against thee:","they have devised counsels which they have not been able to establish."]},{"v":13,"lines":["For thou shalt make them turn their back:","in thy remnants thou shalt prepare their face."]},{"v":14,"lines":["Be thou exalted, O Lord, in thy own strength:","we will sing and praise thy power."]}]},{"n":21,"incipit":"Deus, Deus meus","verses":[{"v":1,"lines":["Unto the end, for the morning protection, a psalm for David."],"title":true},{"v":2,"lines":["O God my God, look upon me:","why hast thou forsaken me? Far from my salvation are the words of my sins."]},{"v":3,"lines":["O my God, I shall cry by day, and thou wilt not hear:","and by night, and it shall not be reputed as folly in me."]},{"v":4,"lines":["But thou dwellest in the holy place, the praise of Israel."]},{"v":5,"lines":["In thee have our fathers hoped:","they have hoped, and thou hast delivered them."]},{"v":6,"lines":["They cried to thee, and they were saved:","they trusted in thee, and were not confounded."]},{"v":7,"lines":["But I am a worm, and no man:","the reproach of men, and the outcast of the people."]},{"v":8,"lines":["All they that saw me have laughed me to scorn:","they have spoken with the lips, and wagged the head."]},{"v":9,"lines":["He hoped in the Lord, let him deliver him:","let him save him, seeing he delighteth in him."]},{"v":10,"lines":["For thou art he that hast drawn me out of the womb:","my hope from the breasts of my mother."]},{"v":11,"lines":["I was cast upon thee from the womb. From my mother's womb thou art my God,"]},{"v":12,"lines":["Depart not from me. For tribulation is very near:","for there is none to help me."]},{"v":13,"lines":["Many calves have surrounded me:","fat bulls have besieged me."]},{"v":14,"lines":["They have opened their mouths against me, as a lion ravening and roaring."]},{"v":15,"lines":["I am poured out like water;","and all my bones are scattered. My heart is become like wax melting in the midst of my bowels."]},{"v":16,"lines":["My strength is dried up like a potsherd, and my tongue hath cleaved to my jaws:","and thou hast brought me down into the dust of death."]},{"v":17,"lines":["For many dogs have encompassed me:","the council of the malignant hath besieged me. They have dug my hands and feet."]},{"v":18,"lines":["They have numbered all my bones. And they have looked and stared upon me."]},{"v":19,"lines":["They parted my garments amongst them;","and upon my vesture they cast lots."]},{"v":20,"lines":["But thou, O Lord, remove not thy help to a distance from me;","look towards my defence."]},{"v":21,"lines":["Deliver, O God, my soul from the sword:","my only one from the hand of the dog."]},{"v":22,"lines":["Save me from the lion's mouth;","and my lowness from the horns of the unicorns."]},{"v":23,"lines":["I will declare thy name to my brethren:","in the midst of the church will I praise thee."]},{"v":24,"lines":["Ye that fear the Lord, praise him:","all ye the seed of Jacob, glorify him."]},{"v":25,"lines":["Let all the seed of Israel fear him:","because he hath not slighted nor despised the supplication of the poor man. Neither hath he turned away his face from me:","and when I cried to him he heard me."]},{"v":26,"lines":["With thee is my praise in a great church:","I will pay my vows in the sight of them that fear him."]},{"v":27,"lines":["The poor shall eat and shall be filled:","and they shall praise the Lord that seek him:","their hearts shall live for ever and ever."]},{"v":28,"lines":["All the ends of the earth shall remember, and shall be converted to the Lord:","And all the kindreds of the Gentiles shall adore in his sight."]},{"v":29,"lines":["For the kingdom is the Lord's;","and he shall have dominion over the nations."]},{"v":30,"lines":["All the fat ones of the earth have eaten and have adored:","all they that go down to the earth shall fall before him."]},{"v":31,"lines":["And to him my soul shall live:","and my seed shall serve him."]},{"v":32,"lines":["There shall be declared to the Lord a generation to come:","and the heavens shall shew forth his justice to a people that shall be born, which the Lord hath made."]}]},{"n":22,"incipit":"Dominus regit me","verses":[{"v":1,"lines":["The Lord ruleth me:","and I shall want nothing."],"heading":"A psalm for David."},{"v":2,"lines":["He hath set me in a place of pasture. He hath brought me up, on the water of refreshment:"]},{"v":3,"lines":["He hath converted my soul. He hath led me on the paths of justice, for his own name's sake."]},{"v":4,"lines":["For though I should walk in the midst of the shadow of death, I will fear no evils, for thou art with me. Thy rod and thy staff, they have comforted me."]},{"v":5,"lines":["Thou hast prepared a table before me against them that afflict me. Thou hast anointed my head with oil;","and my chalice which inebriateth me, how goodly is it!"]},{"v":6,"lines":["And thy mercy will follow me all the days of my life. And that I may dwell in the house of the Lord unto length of days."]}]},{"n":23,"incipit":"Domini est terra","verses":[{"v":1,"lines":["The earth is the Lord's and the fulness thereof:","the world, and all they that dwell therein."],"heading":"On the first day of the week, a psalm for David."},{"v":2,"lines":["For he hath founded it upon the seas;","and hath prepared it upon the rivers."]},{"v":3,"lines":["Who shall ascend into the mountain of the Lord:","or who shall stand in his holy place?"]},{"v":4,"lines":["The innocent in hands, and clean of heart, who hath not taken his soul in vain, nor sworn deceitfully to his neighbour."]},{"v":5,"lines":["He shall receive a blessing from the Lord, and mercy from God his Saviour."]},{"v":6,"lines":["This is the generation of them that seek him, of them that seek the face of the God of Jacob."]},{"v":7,"lines":["Lift up your gates, O ye princes, and be ye lifted up, O eternal gates:","and the King of Glory shall enter in."]},{"v":8,"lines":["Who is this King of Glory? the Lord who is strong and mighty:","the Lord mighty in battle."]},{"v":9,"lines":["Lift up your gates, O ye princes, and be ye lifted up, O eternal gates:","and the King of Glory shall enter in."]},{"v":10,"lines":["Who is this King of Glory? the Lord of hosts, he is the King of Glory."]}]},{"n":24,"incipit":"Ad te, Domine, levavi","verses":[{"v":1,"lines":["To thee, O Lord, have I lifted up my soul."],"heading":"Unto the end, a psalm for David."},{"v":2,"lines":["In thee, O my God, I put my trust;","let me not be ashamed."]},{"v":3,"lines":["Neither let my enemies laugh at me:","for none of them that wait on thee shall be confounded."]},{"v":4,"lines":["Let all them be confounded that act unjust things without cause. Shew, O Lord, thy ways to me, and teach me thy paths."]},{"v":5,"lines":["Direct me in thy truth, and teach me;","for thou art God my Saviour;","and on thee have I waited all the day long."]},{"v":6,"lines":["Remember, O Lord, thy bowels of compassion;","and thy mercies that are from the beginning of the world."]},{"v":7,"lines":["The sins of my youth and my ignorances do not remember. According to thy mercy remember thou me:","for thy goodness' sake, O Lord."]},{"v":8,"lines":["The Lord is sweet and righteous:","therefore he will give a law to sinners in the way."]},{"v":9,"lines":["He will guide the mild in judgment:","he will teach the meek his ways."]},{"v":10,"lines":["All the ways of the Lord are mercy and truth, to them that seek after his covenant and his testimonies."]},{"v":11,"lines":["For thy name's sake, O Lord, thou wilt pardon my sin:","for it is great."]},{"v":12,"lines":["Who is the man that feareth the Lord? He hath appointed him a law in the way he hath chosen."]},{"v":13,"lines":["His soul shall dwell in good things:","and his seed shall inherit the land."]},{"v":14,"lines":["The Lord is a firmament to them that fear him:","and his covenant shall be made manifest to them."]},{"v":15,"lines":["My eyes are ever towards the Lord:","for he shall pluck my feet out of the snare."]},{"v":16,"lines":["Look thou upon me, and have mercy on me;","for I am alone and poor."]},{"v":17,"lines":["The troubles of my heart are multiplied:","deliver me from my necessities."]},{"v":18,"lines":["See my abjection and my labour;","and forgive me all my sins."]},{"v":19,"lines":["Consider my enemies for they are multiplied, and have hated me with an unjust hatred."]},{"v":20,"lines":["Keep thou my soul, and deliver me:","I shall not be ashamed, for I have hoped in thee."]},{"v":21,"lines":["The innocent and the upright have adhered to me:","because I have waited on thee."]},{"v":22,"lines":["Deliver Israel, O God, from all his tribulations."]}]},{"n":25,"incipit":"Judica me, Domine","verses":[{"v":1,"lines":["Judge me, O Lord, for I have walked in my innocence:","and I have put my trust in the Lord, and shall not be weakened."],"heading":"Unto the end, a psalm for David."},{"v":2,"lines":["Prove me, O Lord, and try me;","burn my reins and my heart."]},{"v":3,"lines":["For thy mercy is before my eyes;","and I am well pleased with thy truth."]},{"v":4,"lines":["I have not sat with the council of vanity:","neither will I go in with the doers of unjust things."]},{"v":5,"lines":["I have hated the assembly of the malignant;","and with the wicked I will not sit."]},{"v":6,"lines":["I will wash my hands among the innocent;","and will compass thy altar, O Lord:"]},{"v":7,"lines":["That I may hear the voice of thy praise:","and tell of all thy wondrous works."]},{"v":8,"lines":["I have loved, O Lord, the beauty of thy house;","and the place where thy glory dwelleth."]},{"v":9,"lines":["Take not away my soul, O God, with the wicked:","nor my life with bloody men:"]},{"v":10,"lines":["In whose hands are iniquities:","their right hand is filled with gifts."]},{"v":11,"lines":["But as for me, I have walked in my innocence:","redeem me, and have mercy on me."]},{"v":12,"lines":["My foot hath stood in the direct way:","in the churches I will bless thee, O Lord."]}]},{"n":26,"incipit":"Dominus illuminatio","verses":[{"v":1,"lines":["The Lord is my light and my salvation, whom shall I fear? The Lord is the protector of my life:","of whom shall I be afraid?"],"heading":"The psalm of David before he was anointed."},{"v":2,"lines":["Whilst the wicked draw near against me, to eat my flesh. My enemies that trouble me, have themselves been weakened, and have fallen."]},{"v":3,"lines":["If armies in camp should stand together against me, my heart shall not fear. If a battle should rise up against me, in this will I be confident."]},{"v":4,"lines":["One thing I have asked of the Lord, this will I seek after;","that I may dwell in the house of the Lord all the days of my life. That I may see the delight of the Lord, and may visit his temple."]},{"v":5,"lines":["For he hath hidden me in his tabernacle;","in the day of evils, he hath protected me in the secret place of his tabernacle."]},{"v":6,"lines":["He hath exalted me upon a rock:","and now he hath lifted up my head above my enemies. I have gone round, and have offered up in his tabernacle a sacrifice of jubilation:","I will sing, and recite a psalm to the Lord."]},{"v":7,"lines":["Hear, O Lord, my voice, with which I have cried to thee:","have mercy on me and hear me."]},{"v":8,"lines":["My heart hath said to thee:","My face hath sought thee:","thy face, O Lord, will I still seek."]},{"v":9,"lines":["Turn not away thy face from me;","decline not in thy wrath from thy servant. Be thou my helper, forsake me not;","do not thou despise me, O God my Saviour."]},{"v":10,"lines":["For my father and my mother have left me:","but the Lord hath taken me up."]},{"v":11,"lines":["Set me, O Lord, a law in thy way, and guide me in the right path, because of my enemies."]},{"v":12,"lines":["Deliver me not over to the will of them that trouble me;","for unjust witnesses have risen up against me;","and iniquity hath lied to itself."]},{"v":13,"lines":["I believe to see the good things of the Lord in the land of the living."]},{"v":14,"lines":["Expect the Lord, do manfully, and let thy heart take courage, and wait thou for the Lord."]}]},{"n":27,"incipit":"Ad te Domine","verses":[{"v":1,"lines":["Unto thee will I cry, O Lord:","O my God, be not thou silent to me:","lest thou be silent to me, I become like them that go down into the pit."],"heading":"A psalm for David himself."},{"v":2,"lines":["Hear, O Lord, the voice of my supplication, when I pray to thee;","when I lift up my hands to thy holy temple."]},{"v":3,"lines":["Draw me not away together with the wicked;","and with the workers of iniquity destroy me not:","Who speak peace with their neighbour, but evils are in their hearts."]},{"v":4,"lines":["Give them according to their works, and according to the wickedness of their inventions. According to the works of their hands give thou to them:","render to them their reward."]},{"v":5,"lines":["Because they have not understood the works of the Lord, and the operations of his hands:","thou shalt destroy them, and shalt not build them up."]},{"v":6,"lines":["Blessed be the Lord, for he hath heard the voice of my supplication."]},{"v":7,"lines":["The Lord is my helper and my protector:","in him hath my heart confided, and I have been helped. And my flesh hath flourished again, and with my will I will give praise to him."]},{"v":8,"lines":["The Lord is the strength of his people, and the protector of the salvation of his anointed."]},{"v":9,"lines":["Save, O Lord, thy people, and bless thy inheritance:","and rule them and exalt them for ever."]}]},{"n":28,"incipit":"Afferte Domino","verses":[{"v":1,"lines":["Bring to the Lord, O ye children of God:","bring to the Lord the offspring of rams."],"heading":"A psalm for David, at the finishing of the tabernacle."},{"v":2,"lines":["Bring to the Lord glory and honour:","bring to the Lord glory to his name:","adore ye the Lord in his holy court."]},{"v":3,"lines":["The voice of the Lord is upon the waters;","the God of majesty hath thundered, The Lord is upon many waters."]},{"v":4,"lines":["The voice of the Lord is in power;","the voice of the Lord in magnificence."]},{"v":5,"lines":["The voice of the Lord breaketh the cedars:","yea, the Lord shall break the cedars of Libanus."]},{"v":6,"lines":["And shall reduce them to pieces, as a calf of Libanus, and as the beloved son of unicorns."]},{"v":7,"lines":["The voice of the Lord divideth the flame of fire:"]},{"v":8,"lines":["The voice of the Lord shaketh the desert:","and the Lord shall shake the desert of Cades."]},{"v":9,"lines":["The voice of the Lord prepareth the stags:","and he will discover the thick woods:","and in his temple all shall speak his glory."]},{"v":10,"lines":["The Lord maketh the flood to dwell:","and the Lord shall sit king for ever. The Lord will give strength to his people:","the Lord will bless his people with peace."]}]},{"n":29,"incipit":"Exaltabo te, Domine","verses":[{"v":1,"lines":["A psalm of a canticle, at the dedication of David's house."],"title":true},{"v":2,"lines":["I will extol thee, O Lord, for thou hast upheld me:","and hast not made my enemies to rejoice over me."]},{"v":3,"lines":["O Lord my God, I have cried to thee, and thou hast healed me."]},{"v":4,"lines":["Thou hast brought forth, O Lord, my soul from hell:","thou hast saved me from them that go down into the pit."]},{"v":5,"lines":["Sing to the Lord, O ye his saints:","and give praise to the memory of his holiness."]},{"v":6,"lines":["For wrath is in his indignation;","and life in his good will. In the evening weeping shall have place, and in the morning gladness."]},{"v":7,"lines":["And in my abundance I said:","I shall never be moved."]},{"v":8,"lines":["O Lord, in thy favour, thou gavest strength to my beauty. Thou turnedst away thy face from me, and I became troubled."]},{"v":9,"lines":["To thee, O Lord, will I cry:","and I will make supplication to my God."]},{"v":10,"lines":["What profit is there in my blood, whilst I go down to corruption? Shall dust confess to thee, or declare thy truth?"]},{"v":11,"lines":["The Lord hath heard, and hath had mercy on me:","the Lord became my helper."]},{"v":12,"lines":["Thou hast turned for me my mourning into joy:","thou hast cut my sackcloth, and hast compassed me with gladness:"]},{"v":13,"lines":["To the end that my glory may sing to thee, and I may not regret:","O Lord my God, I will give praise to thee for ever."]}]},{"n":30,"incipit":"In te, Domine, speravi","verses":[{"v":1,"lines":["Unto the end, a psalm for David, in an ecstasy."],"title":true},{"v":2,"lines":["In thee, O Lord, have I hoped, let me never be confounded:","deliver me in thy justice."]},{"v":3,"lines":["Bow down thy ear to me:","make haste to deliver me. Be thou unto me a God, a protector, and a house of refuge, to save me."]},{"v":4,"lines":["For thou art my strength and my refuge;","and for thy name's sake thou wilt lead me, and nourish me."]},{"v":5,"lines":["Thou wilt bring me out of this snare, which they have hidden for me:","for thou art my protector."]},{"v":6,"lines":["Into thy hands I commend my spirit:","thou hast redeemed me, O Lord, the God of truth."]},{"v":7,"lines":["Thou hast hated them that regard vanities, to no purpose. But I have hoped in the Lord:"]},{"v":8,"lines":["I will be glad and rejoice in thy mercy. For thou hast regarded my humility, thou hast saved my soul out of distresses."]},{"v":9,"lines":["And thou hast not shut me up in the hands of the enemy:","thou hast set my feet in a spacious place."]},{"v":10,"lines":["Have mercy on me, O Lord, for I am afflicted:","my eye is troubled with wrath, my soul, and my belly:"]},{"v":11,"lines":["For my life is wasted with grief:","and my years in sighs. My strength is weakened through poverty and my bones are disturbed."]},{"v":12,"lines":["I am become a reproach among all my enemies, and very much to my neighbours;","and a fear to my acquaintance. They that saw me without fled from me."]},{"v":13,"lines":["I am forgotten as one dead from the heart. I am become as a vessel that is destroyed."]},{"v":14,"lines":["For I have heard the blame of many that dwell round about. While they assembled together against me, they consulted to take away my life."]},{"v":15,"lines":["But I have put my trust in thee, O Lord:","I said:","Thou art my God."]},{"v":16,"lines":["My lots are in thy hands. Deliver me out of the hands of my enemies;","and from them that persecute me."]},{"v":17,"lines":["Make thy face to shine upon thy servant;","save me in thy mercy."]},{"v":18,"lines":["Let me not be confounded, O Lord, for I have called upon thee. Let the wicked be ashamed, and be brought down to hell."]},{"v":19,"lines":["Let deceitful lips be made dumb. Which speak iniquity against the just, with pride and abuse."]},{"v":20,"lines":["O how great is the multitude of thy sweetness, O Lord, which thou hast hidden for them that fear thee! Which thou hast wrought for them that hope in thee, in the sight of the sons of men."]},{"v":21,"lines":["Thou shalt hide them in the secret of thy face, from the disturbance of men. Thou shalt protect them in thy tabernacle from the contradiction of tongues."]},{"v":22,"lines":["Blessed be the Lord, for he hath shewn his wonderful mercy to me in a fortified city."]},{"v":23,"lines":["But I said in the excess of my mind:","I am cast away from before thy eyes. Therefore thou hast heard the voice of my prayer, when I cried to thee."]},{"v":24,"lines":["O love the Lord, all ye his saints:","for the Lord will require truth, and will repay them abundantly that act proudly."]},{"v":25,"lines":["Do ye manfully, and let your heart be strengthened, all ye that hope in the Lord."]}]},{"n":31,"incipit":"Beati quorum","verses":[{"v":1,"lines":["Blessed are they whose iniquities are forgiven, and whose sins are covered."],"heading":"To David himself, understanding."},{"v":2,"lines":["Blessed is the man to whom the Lord hath not imputed sin, and in whose spirit there is no guile."]},{"v":3,"lines":["Because I was silent my bones grew old;","whilst I cried out all the day long."]},{"v":4,"lines":["For day and night thy hand was heavy upon me:","I am turned in my anguish, whilst the thorn is fastened."]},{"v":5,"lines":["I have acknowledged my sin to thee, and my injustice I have not concealed. I said I will confess against myself my injustice to the Lord:","and thou hast forgiven the wickedness of my sin."]},{"v":6,"lines":["For this shall every one that is holy pray to thee in a seasonable time. And yet in a flood of many waters, they shall not come nigh unto him."]},{"v":7,"lines":["Thou art my refuge from the trouble which hath encompassed me:","my joy, deliver me from them that surround me."]},{"v":8,"lines":["I will give thee understanding, and I will instruct thee in this way, in which thou shalt go:","I will fix my eyes upon thee."]},{"v":9,"lines":["Do not become like the horse and the mule, who have no understanding. With bit and bridle bind fast their jaws, who come not near unto thee."]},{"v":10,"lines":["Many are the scourges of the sinner, but mercy shall encompass him that hopeth in the Lord."]},{"v":11,"lines":["Be glad in the Lord, and rejoice, ye just, and glory, all ye right of heart."]}]},{"n":32,"incipit":"Exultate, justi","verses":[{"v":1,"lines":["Rejoice in the Lord, O ye just:","praise becometh the upright."],"heading":"A psalm for David."},{"v":2,"lines":["Give praise to the Lord on the harp;","sing to him with the psaltery, the instrument of ten strings."]},{"v":3,"lines":["Sing to him a new canticle, sing well unto him with a loud noise."]},{"v":4,"lines":["For the word of the Lord is right, and all his works are done with faithfulness."]},{"v":5,"lines":["He loveth mercy and judgment;","the earth is full of the mercy of the Lord."]},{"v":6,"lines":["By the word of the Lord the heavens were established;","and all the power of them by the spirit of his mouth:"]},{"v":7,"lines":["Gathering together the waters of the sea, as in a vessel;","laying up the depths in storehouses."]},{"v":8,"lines":["Let all the earth fear the Lord, and let all the inhabitants of the world be in awe of him."]},{"v":9,"lines":["For he spoke and they were made:","he commanded and they were created."]},{"v":10,"lines":["The Lord bringeth to naught the counsels of nations;","and he rejecteth the devices of people, and casteth away the counsels of princes."]},{"v":11,"lines":["But the counsel of the Lord standeth for ever:","the thoughts of his heart to all generations."]},{"v":12,"lines":["Blessed is the nation whose God is the Lord:","the people whom he hath chosen for his inheritance."]},{"v":13,"lines":["The Lord hath looked from heaven:","he hath beheld all the sons of men."]},{"v":14,"lines":["From his habitation which he hath prepared, he hath looked upon all that dwell on the earth."]},{"v":15,"lines":["He who hath made the hearts of every one of them:","who understandeth all their works."]},{"v":16,"lines":["The king is not saved by a great army:","nor shall the giant be saved by his own great strength."]},{"v":17,"lines":["Vain is the horse for safety:","neither shall he be saved by the abundance of his strength."]},{"v":18,"lines":["Behold the eyes of the Lord are on them that fear him:","and on them that hope in his mercy."]},{"v":19,"lines":["To deliver their souls from death;","and feed them in famine."]},{"v":20,"lines":["Our soul waiteth for the Lord:","for he is our helper and protector."]},{"v":21,"lines":["For in him our heart shall rejoice:","and in his holy name we have trusted."]},{"v":22,"lines":["Let thy mercy, O Lord, be upon us, as we have hoped in thee."]}]},{"n":33,"incipit":"Benedicam Dominum","verses":[{"v":1,"lines":["For David, when he changed his countenance before Achimelech, who dismissed him, and he went his way."],"title":true},{"v":2,"lines":["I will bless the Lord at all times, his praise shall be always in my mouth."]},{"v":3,"lines":["In the Lord shall my soul be praised:","let the meek hear and rejoice."]},{"v":4,"lines":["O magnify the Lord with me;","and let us extol his name together."]},{"v":5,"lines":["I sought the Lord, and he heard me;","and he delivered me from all my troubles."]},{"v":6,"lines":["Come ye to him and be enlightened:","and your faces shall not be confounded."]},{"v":7,"lines":["This poor man cried, and the Lord heard him:","and saved him out of all his troubles."]},{"v":8,"lines":["The angel of the Lord shall encamp round about them that fear him:","and shall deliver them."]},{"v":9,"lines":["O taste, and see that the Lord is sweet:","blessed is the man that hopeth in him."]},{"v":10,"lines":["Fear the Lord, all ye his saints:","for there is no want to them that fear him."]},{"v":11,"lines":["The rich have wanted, and have suffered hunger:","but they that seek the Lord shall not be deprived of any good."]},{"v":12,"lines":["Come, children, hearken to me:","I will teach you the fear of the Lord."]},{"v":13,"lines":["Who is the man that desireth life:","who loveth to see good days?"]},{"v":14,"lines":["Keep thy tongue from evil, and thy lips from speaking guile."]},{"v":15,"lines":["Turn away from evil and do good:","seek after peace and pursue it."]},{"v":16,"lines":["The eyes of the Lord are upon the just:","and his ears unto their prayers."]},{"v":17,"lines":["But the countenance of the Lord is against them that do evil things:","to cut off the remembrance of them from the earth."]},{"v":18,"lines":["The just cried, and the Lord heard them:","and delivered them out of all their troubles."]},{"v":19,"lines":["The Lord is nigh unto them that are of a contrite heart:","and he will save the humble of spirit."]},{"v":20,"lines":["Many are the afflictions of the just;","but out of them all will the Lord deliver them."]},{"v":21,"lines":["The Lord keepeth all their bones, not one of them shall be broken."]},{"v":22,"lines":["The death of the wicked is very evil:","and they that hate the just shall be guilty."]},{"v":23,"lines":["The Lord will redeem the souls of his servants:","and none of them that trust in him shall offend."]}]},{"n":34,"incipit":"Judica, Domine","verses":[{"v":1,"lines":["Judge thou, O Lord, them that wrong me:","overthrow them that fight against me."],"heading":"For David himself."},{"v":2,"lines":["Take hold of arms and shield:","and rise up to help me."]},{"v":3,"lines":["Bring out the sword, and shut up the way against them that persecute me:","say to my soul:","I am thy salvation."]},{"v":4,"lines":["Let them be confounded and ashamed that seek after my soul. Let them be turned back and be confounded that devise against me."]},{"v":5,"lines":["Let them become as dust before the wind:","and let the angel of the Lord straiten them."]},{"v":6,"lines":["Let their way become dark and slippery;","and let the angel of the Lord pursue them."]},{"v":7,"lines":["For without cause they have hidden their net for me unto destruction:","without cause they have upbraided my soul."]},{"v":8,"lines":["Let the snare which he knoweth not come upon him:","and let the net which he hath hidden catch him:","and into that very snare let them fall."]},{"v":9,"lines":["But my soul shall rejoice in the Lord;","and shall be delighted in his salvation."]},{"v":10,"lines":["All my bones shall say:","Lord, who is like to thee? Who deliverest the poor from the hand of them that are stronger than he;","the needy and the poor from them that strip him."]},{"v":11,"lines":["Unjust witnesses rising up have asked me things I knew not."]},{"v":12,"lines":["They repaid me evil for good:","to the depriving me of my soul."]},{"v":13,"lines":["But as for me, when they were troublesome to me, I was clothed with haircloth. I humbled my soul with fasting;","and my prayer shall be turned into my bosom."]},{"v":14,"lines":["As a neighbour and as an own brother, so did I please:","as one mourning and sorrowful so was I humbled."]},{"v":15,"lines":["But they rejoiced against me, and came together:","scourges were gathered together upon me, and I knew not."]},{"v":16,"lines":["They were separated, and repented not:","they tempted me, they scoffed at me with scorn:","they gnashed upon me with their teeth."]},{"v":17,"lines":["Lord, when wilt thou look upon me? rescue thou my soul from their malice:","my only one from the lions."]},{"v":18,"lines":["I will give thanks to thee in a great church;","I will praise thee in a strong people."]},{"v":19,"lines":["Let not them that are my enemies wrongfully rejoice over me:","who have hated me without cause, and wink with the eyes."]},{"v":20,"lines":["For they spoke indeed peaceably to me;","and speaking in the anger of the earth they devised guile."]},{"v":21,"lines":["And they opened their mouth wide against me;","they said:","Well done, well done, our eyes have seen it."]},{"v":22,"lines":["Thou hast seen, O Lord, be not thou silent:","O Lord, depart not from me."]},{"v":23,"lines":["Arise, and be attentive to my judgment:","to my cause, my God, and my Lord."]},{"v":24,"lines":["Judge me, O Lord my God according to thy justice, and let them not rejoice over me."]},{"v":25,"lines":["Let them not say in their hearts:","It is well, it is well, to our mind:","neither let them say:","We have swallowed him up."]},{"v":26,"lines":["Let them blush:","and be ashamed together, who rejoice at my evils. Let them be clothed with confusion and shame, who speak great things against me."]},{"v":27,"lines":["Let them rejoice and be glad, who are well pleased with my justice, and let them say always:","The Lord be magnified, who delights in the peace of his servant."]},{"v":28,"lines":["And my tongue shall meditate thy justice, thy praise all the day long."]}]},{"n":35,"incipit":"Dixit injustus","verses":[{"v":1,"lines":["Unto the end, for the servant of God, David himself."],"title":true},{"v":2,"lines":["The unjust hath said within himself, that he would sin:","there is no fear of God before his eyes."]},{"v":3,"lines":["For in his sight he hath done deceitfully, that his iniquity may be found unto hatred."]},{"v":4,"lines":["The words of his mouth are iniquity and guile:","he would not understand that he might do well."]},{"v":5,"lines":["He hath devised iniquity on his bed, he hath set himself on every way that is not good:","but evil he hath not hated."]},{"v":6,"lines":["O Lord, thy mercy is in heaven, and thy truth reacheth even to the clouds."]},{"v":7,"lines":["Thy justice is as the mountains of God, thy judgments are a great deep. Men and beasts thou wilt preserve, O Lord:"]},{"v":8,"lines":["O how hast thou multiplied thy mercy, O God! But the children of men shall put their trust under the covert of thy wings."]},{"v":9,"lines":["They shall be inebriated with the plenty of thy house;","and thou shalt make them drink of the torrent of thy pleasure."]},{"v":10,"lines":["For with thee is the fountain of life;","and in thy light we shall see light."]},{"v":11,"lines":["Extend thy mercy to them that know thee, and thy justice to them that are right in heart."]},{"v":12,"lines":["Let not the foot of pride come to me, and let not the hand of the sinner move me."]},{"v":13,"lines":["There the workers of iniquity are fallen, they are cast out, and could not stand."]}]},{"n":36,"incipit":"Noli aemulari","verses":[{"v":1,"lines":["Be not emulous of evildoers;","nor envy them that work iniquity."]},{"v":2,"lines":["For they shall shortly wither away as grass, and as the green herbs shall quickly fall."]},{"v":3,"lines":["Trust in the Lord, and do good, and dwell in the land, and thou shalt be fed with its riches."]},{"v":4,"lines":["Delight in the Lord, and he will give thee the requests of thy heart."]},{"v":5,"lines":["Commit thy way to the Lord, and trust in him, and he will do it."]},{"v":6,"lines":["And he will bring forth thy justice as the light, and thy judgment as the noonday."]},{"v":7,"lines":["Be subject to the Lord and pray to him. Envy not the man who prospereth in his way;","the man who doth unjust things."]},{"v":8,"lines":["Cease from anger, and leave rage;","have no emulation to do evil."]},{"v":9,"lines":["For the evildoers shall be cut off:","but they that wait upon the Lord shall inherit the land."]},{"v":10,"lines":["For yet a little while, and the wicked shall not be:","and thou shalt seek his place, and shalt not find it."]},{"v":11,"lines":["But the meek shall inherit the land, and shall delight in abundance of peace."]},{"v":12,"lines":["The sinner shall watch the just man:","and shall gnash upon him with his teeth."]},{"v":13,"lines":["But the Lord shall laugh at him:","for he foreseeth that his day shall come."]},{"v":14,"lines":["The wicked have drawn out the sword:","they have bent their bow. To cast down the poor and needy, to kill the upright of heart."]},{"v":15,"lines":["Let their sword enter into their own hearts, and let their bow be broken."]},{"v":16,"lines":["Better is a little to the just, than the great riches of the wicked."]},{"v":17,"lines":["For the arms of the wicked shall be broken in pieces;","but the Lord strengtheneth the just."]},{"v":18,"lines":["The Lord knoweth the days of undefiled;","and their inheritance shall be for ever."]},{"v":19,"lines":["They shall not be confounded in the evil time;","and in the days of famine they shall be filled:"]},{"v":20,"lines":["Because the wicked shall perish. And the enemies of the Lord, presently after they shall be honoured and exalted, shall come to nothing and vanish like smoke."]},{"v":21,"lines":["The sinner shall borrow, and not pay again;","but the just sheweth mercy and shall give."]},{"v":22,"lines":["For such as bless him shall inherit the land:","but such as curse him shall perish."]},{"v":23,"lines":["With the Lord shall the steps of a man be directed, and he shall like well his way."]},{"v":24,"lines":["When he shall fall he shall not be bruised, for the Lord putteth his hand under him."]},{"v":25,"lines":["I have been young and now am old;","and I have not seen the just forsaken, nor his seed seeking bread."]},{"v":26,"lines":["He sheweth mercy, and lendeth all the day long;","and his seed shall be in blessing."]},{"v":27,"lines":["Decline from evil and do good, and dwell for ever and ever."]},{"v":28,"lines":["For the Lord loveth judgment, and will not forsake his saints:","they shall be preserved for ever. The unjust shall be punished, and the seed of the wicked shall perish."]},{"v":29,"lines":["But the just shall inherit the land, and shall dwell therein for evermore."]},{"v":30,"lines":["The mouth of the just shall meditate wisdom:","and his tongue shall speak judgment."]},{"v":31,"lines":["The law of his God is in his heart, and his steps shall not be supplanted."]},{"v":32,"lines":["The wicked watcheth the just man, and seeketh to put him to death,"]},{"v":33,"lines":["But the Lord will not leave him in his hands;","nor condemn him when he shall be judged."]},{"v":34,"lines":["Expect the Lord and keep his way:","and he will exalt thee to inherit the land:","when the sinners shall perish thou shalt see."]},{"v":35,"lines":["I have seen the wicked highly exalted, and lifted up like the cedars of Libanus."]},{"v":36,"lines":["And I passed by, and lo, he was not:","and I sought him and his place was not found."]},{"v":37,"lines":["Keep innocence, and behold justice:","for there are remnants for the peaceable man."]},{"v":38,"lines":["But the unjust shall be destroyed together:","the remnants of the wicked shall perish."]},{"v":39,"lines":["But the salvation of the just is from the Lord, and he is their protector in the time of trouble."]},{"v":40,"lines":["And the Lord will help them and deliver them:","and he will rescue them from the wicked, and save them because they have hoped in him."]}]},{"n":37,"incipit":"Domine, ne in furore","verses":[{"v":1,"lines":["A psalm for David, for a remembrance of the sabbath."],"title":true},{"v":2,"lines":["Rebuke me not, O Lord, in thy indignation;","nor chastise me in thy wrath."]},{"v":3,"lines":["For thy arrows are fastened in me:","and thy hand hath been strong upon me."]},{"v":4,"lines":["There is no health in my flesh, because of thy wrath:","there is no peace for my bones, because of my sins."]},{"v":5,"lines":["For my iniquities are gone over my head:","and as a heavy burden are become heavy upon me."]},{"v":6,"lines":["My sores are putrified and corrupted, because of my foolishness."]},{"v":7,"lines":["I am become miserable, and am bowed down even to the end:","I walked sorrowful all the day long."]},{"v":8,"lines":["For my loins are filled with illusions;","and there is no health in my flesh."]},{"v":9,"lines":["I am afflicted and humbled exceedingly:","I roared with the groaning of my heart."]},{"v":10,"lines":["Lord, all my desire is before thee, and my groaning is not hidden from thee."]},{"v":11,"lines":["My heart is troubled, my strength hath left me, and the light of my eyes itself is not with me."]},{"v":12,"lines":["My friends and my neighbours have drawn near, and stood against me. And they that were near me stood afar off:"]},{"v":13,"lines":["And they that sought my soul used violence. And they that sought evils to me spoke vain things, and studied deceits all the day long."]},{"v":14,"lines":["But I, as a deaf man, heard not:","and as a dumb man not opening his mouth."]},{"v":15,"lines":["And I became as a man that heareth not:","and that hath no reproofs in his mouth."]},{"v":16,"lines":["For in thee, O Lord, have I hoped:","thou wilt hear me, O Lord my God."]},{"v":17,"lines":["For I said:","Lest at any time my enemies rejoice over me:","and whilst my feet are moved, they speak great things against me."]},{"v":18,"lines":["For I am ready for scourges:","and my sorrow is continually before me."]},{"v":19,"lines":["For I will declare my iniquity:","and I will think for my sin."]},{"v":20,"lines":["But my enemies live, and are stronger than I:","and they that hate me wrongfully are multiplied."]},{"v":21,"lines":["They that render evil for good, have detracted me, because I followed goodness."]},{"v":22,"lines":["Forsake me not, O Lord my God:","do not thou depart from me."]},{"v":23,"lines":["Attend unto my help, O Lord, the God of my salvation."]}]},{"n":38,"incipit":"Dixi, custodiam","verses":[{"v":1,"lines":["Unto the end, for Idithun himself, a canticle of David."],"title":true},{"v":2,"lines":["I said:","I will take heed to my ways:","that I sin not with my tongue. I have set guard to my mouth, when the sinner stood against me."]},{"v":3,"lines":["I was dumb, and was humbled, and kept silence from good things:","and my sorrow was renewed."]},{"v":4,"lines":["My heart grew hot within me:","and in my meditation a fire shall flame out."]},{"v":5,"lines":["I spoke with my tongue:","O Lord, make me know my end. And what is the number of my days:","that I may know what is wanting to me."]},{"v":6,"lines":["Behold thou hast made my days measurable, and my substance is as nothing before thee. And indeed all things are vanity:","every man living."]},{"v":7,"lines":["Surely man passeth as an image:","yea, and he is disquieted in vain. He storeth up:","and he knoweth not for whom he shall gather these things."]},{"v":8,"lines":["And now what is my hope? is it not the Lord? and my substance is with thee."]},{"v":9,"lines":["Deliver thou me from all my iniquities:","thou hast made me a reproach to the fool."]},{"v":10,"lines":["I was dumb, and I opened not my mouth, because thou hast done it."]},{"v":11,"lines":["Remove thy scourges from me. The strength of thy hand hath made me faint in rebukes:"]},{"v":12,"lines":["Thou hast corrected man for iniquity. And thou hast made his soul to waste away like a spider:","surely in vain is any man disquieted."]},{"v":13,"lines":["Hear my prayer, O Lord, and my supplication:","give ear to my tears. Be not silent:","for I am a stranger with thee, and a sojourner as all my fathers were."]},{"v":14,"lines":["O forgive me, that I may be refreshed, before I go hence, and be no more."]}]},{"n":39,"incipit":"Expectans, expectavi","verses":[{"v":1,"lines":["Unto the end, a psalm for David himself."],"title":true},{"v":2,"lines":["With expectation I have waited for the Lord, and he was attentive to me."]},{"v":3,"lines":["And he heard my prayers, and brought me out of the pit of misery and the mire of dregs. And he set my feet upon a rock, and directed my steps."]},{"v":4,"lines":["And he put a new canticle into my mouth, a song to our God. Many shall see, and shall fear:","and they shall hope in the Lord."]},{"v":5,"lines":["Blessed is the man whose trust is in the name of the Lord;","and who hath not had regard to vanities, and lying follies."]},{"v":6,"lines":["Thou hast multiplied thy wonderful works, O Lord my God:","and in thy thoughts there is no one like to thee. I have declared and I have spoken they are multiplied above number."]},{"v":7,"lines":["Sacrifice and oblation thou didst not desire;","but thou hast pierced ears for me. Burnt offering and sin offering thou didst not require:"]},{"v":8,"lines":["Then said I, Behold I come. In the head of the book it is written of me"]},{"v":9,"lines":["That I should do thy will:","O my God, I have desired it, and thy law in the midst of my heart."]},{"v":10,"lines":["I have declared thy justice in a great church, lo, I will not restrain my lips:","O Lord, thou knowest it."]},{"v":11,"lines":["I have not hid thy justice within my heart:","I have declared thy truth and thy salvation. I have not concealed thy mercy and thy truth from a great council."]},{"v":12,"lines":["Withhold not thou, O Lord, thy tender mercies from me:","thy mercy and thy truth have always upheld me."]},{"v":13,"lines":["For evils without number have surrounded me;","my iniquities have overtaken me, and I was not able to see. They are multiplied above the hairs of my head:","and my heart hath forsaken me."]},{"v":14,"lines":["Be pleased, O Lord, to deliver me:","look down, O Lord, to help me."]},{"v":15,"lines":["Let them be confounded and ashamed together, that seek after my soul to take it away. Let them be turned backward and be ashamed that desire evils to me."]},{"v":16,"lines":["Let them immediately bear their confusion, that say to me:","Tis well , tis well."]},{"v":17,"lines":["Let all that seek thee rejoice and be glad in thee:","and let such as love thy salvation say always:","The Lord be magnified."]},{"v":18,"lines":["But I am a beggar and poor:","the Lord is careful for me. Thou art my helper and my protector:","O my God, be not slack."]}]},{"n":40,"incipit":"Beatus qui intelligit","verses":[{"v":1,"lines":["Unto the end, a psalm for David himself."],"title":true},{"v":2,"lines":["Blessed is he that understandeth concerning the needy and the poor:","the Lord will deliver him in the evil day."]},{"v":3,"lines":["The Lord preserve him and give him life, and make him blessed upon the earth:","and deliver him not up to the will of his enemies."]},{"v":4,"lines":["The Lord help him on his bed of sorrow:","thou hast turned all his couch in his sickness."]},{"v":5,"lines":["I said:","O Lord, be thou merciful to me:","heal my soul, for I have sinned against thee."]},{"v":6,"lines":["My enemies have spoken evils against me:","when shall he die and his name perish?"]},{"v":7,"lines":["And if he came in to see me, he spoke vain things:","his heart gathered together iniquity to itself. He went out and spoke to the same purpose."]},{"v":8,"lines":["All my enemies whispered together against me:","they devised evils to me."]},{"v":9,"lines":["They determined against me an unjust word:","shall he that sleepeth rise again no more?"]},{"v":10,"lines":["For even the man of peace, in whom I trusted, who ate my bread, hath greatly supplanted me."]},{"v":11,"lines":["But thou, O Lord, have mercy on me, and raise me up again:","and I will requite them."]},{"v":12,"lines":["By this I know, that thou hast had a good will for me:","because my enemy shall not rejoice over me."]},{"v":13,"lines":["But thou hast upheld me by reason of my innocence:","and hast established me in thy sight for ever."]},{"v":14,"lines":["Blessed be the Lord the God of Israel from eternity to eternity. So be it. So be it."]}]},{"n":41,"incipit":"Quemadmodum","verses":[{"v":1,"lines":["Unto the end, understanding for the sons of Core."],"title":true},{"v":2,"lines":["As the hart panteth after the fountains of water;","so my soul panteth after thee, O God."]},{"v":3,"lines":["My soul hath thirsted after the strong living God;","when shall I come and appear before the face of God?"]},{"v":4,"lines":["My tears have been my bread day and night, whilst it is said to me daily:","Where is thy God?"]},{"v":5,"lines":["These things I remembered, and poured out my soul in me:","for I shall go over into the place of the wonderful tabernacle, even to the house of God:","With the voice of joy and praise;","the noise of one feasting."]},{"v":6,"lines":["Why art thou sad, O my soul? and why dost thou trouble me? Hope in God, for I will still give praise to him:","the salvation of my countenance,"]},{"v":7,"lines":["And my God. My soul is troubled within myself:","therefore will I remember thee from the land of Jordan and Hermoniim, from the little hill."]},{"v":8,"lines":["Deep calleth on deep, at the noise of thy flood-gates. All thy heights and thy billows have passed over me."]},{"v":9,"lines":["In the daytime the Lord hath commanded his mercy;","and a canticle to him in the night. With me is prayer to the God of my life."]},{"v":10,"lines":["I will say to God:","Thou art my support. Why hast thou forgotten me? and why go I mourning, whilst my enemy afflicteth me?"]},{"v":11,"lines":["Whilst my bones are broken, my enemies who trouble me have reproached me;","Whilst they say to me day by day:","Where is thy God?"]},{"v":12,"lines":["Why art thou cast down, O my soul? and why dost thou disquiet me? Hope thou in God, for I will still give praise to him:","the salvation of my countenance, and my God."]}]},{"n":42,"incipit":"Judica me, Deus","verses":[{"v":1,"lines":["Judge me, O God, and distinguish my cause from the nation that is not holy:","deliver me from the unjust and deceitful man."],"heading":"A psalm for David."},{"v":2,"lines":["For thou art God my strength:","why hast thou cast me off? and why do I go sorrowful whilst the enemy afflicteth me?"]},{"v":3,"lines":["Send forth thy light and thy truth:","they have conducted me, and brought me unto thy holy hill, and into thy tabernacles."]},{"v":4,"lines":["And I will go in to the altar of God:","to God who giveth joy to my youth."]},{"v":5,"lines":["To thee, O God my God, I will give praise upon the harp:","why art thou sad, O my soul? and why dost thou disquiet me?"]},{"v":6,"lines":["Hope in God, for I will still give praise to him:","the salvation of my countenance, and my God."]}]},{"n":43,"incipit":"Deus, auribus","verses":[{"v":1,"lines":["Unto the end, for the sons of Core, to give understanding."],"title":true},{"v":2,"lines":["We have heard, O God, with our ears:","our fathers have declared to us, The work thou hast wrought in their days, and in the days of old."]},{"v":3,"lines":["Thy hand destroyed the Gentiles, and thou plantedst them:","thou didst afflict the people and cast them out."]},{"v":4,"lines":["For they got not the possession of the land by their own sword:","neither did their own arm save them. But thy right hand and thy arm, and the light of thy countenance:","because thou wast pleased with them."]},{"v":5,"lines":["Thou art thyself my king and my God, who commandest the saving of Jacob."]},{"v":6,"lines":["Through thee we will push down our enemies with the horn:","and through thy name we will despise them that rise up against us."]},{"v":7,"lines":["For I will not trust in my bow:","neither shall my sword save me."]},{"v":8,"lines":["But thou hast saved us from them that afflict us:","and hast put them to shame that hate us."]},{"v":9,"lines":["In God shall we glory all the day long:","and in thy name we will give praise for ever."]},{"v":10,"lines":["But now thou hast cast us off, and put us to shame:","and thou, O God, wilt not go out with our armies."]},{"v":11,"lines":["Thou hast made us turn our back to our enemies:","and they that hated us plundered for themselves."]},{"v":12,"lines":["Thou hast given us up like sheep to be eaten:","thou hast scattered us among the nations."]},{"v":13,"lines":["Thou hast sold thy people for no price:","and there was no reckoning in the exchange of them."]},{"v":14,"lines":["Thou hast made us a reproach to our neighbours, a scoff and derision to them that are round about us."]},{"v":15,"lines":["Thou hast made us a byword among the Gentiles:","a shaking of the head among the people."]},{"v":16,"lines":["All the day long my shame is before me:","and the confusion of my face hath covered me,"]},{"v":17,"lines":["At the voice of him that reproacheth and detracteth me:","at the face of the enemy and persecutor."]},{"v":18,"lines":["All these things have come upon us, yet we have not forgotten thee:","and we have not done wickedly in thy covenant."]},{"v":19,"lines":["And our heart hath not turned back:","neither hast thou turned aside our steps from thy way."]},{"v":20,"lines":["For thou hast humbled us in the place of affliction:","and the shadow of death hath covered us."]},{"v":21,"lines":["If we have forgotten the name of our God, and if we have spread forth our hands to a strange god:"]},{"v":22,"lines":["Shall not God search out these things:","for he knoweth the secrets of the heart. Because for thy sake we are killed all the day long:","we are counted as sheep for the slaughter."]},{"v":23,"lines":["Arise, why sleepest thou, O Lord? arise, and cast us not off to the end."]},{"v":24,"lines":["Why turnest thou thy face away? and forgettest our want and our trouble?"]},{"v":25,"lines":["For our soul is humbled down to the dust:","our belly cleaveth to the earth."]},{"v":26,"lines":["Arise, O Lord, help us and redeem us for thy name's sake."]}]},{"n":44,"incipit":"Eructavit cor meum","verses":[{"v":1,"lines":["Unto the end, for them that shall be changed, for the sons of Core, for understanding. A canticle for the Beloved."],"title":true},{"v":2,"lines":["My heart hath uttered a good word:","I speak my works to the king:","My tongue is the pen of a scrivener that writeth swiftly."]},{"v":3,"lines":["Thou art beautiful above the sons of men:","grace is poured abroad in thy lips;","therefore hath God blessed thee for ever."]},{"v":4,"lines":["Gird thy sword upon thy thigh, O thou most mighty."]},{"v":5,"lines":["With thy comeliness and thy beauty set out, proceed prosperously, and reign. Because of truth and meekness and justice:","and thy right hand shall conduct thee wonderfully."]},{"v":6,"lines":["Thy arrows are sharp:","under thee shall people fall, into the hearts of the king's enemies."]},{"v":7,"lines":["Thy throne, O God, is for ever and ever:","the sceptre of thy kingdom is a sceptre of uprightness."]},{"v":8,"lines":["Thou hast loved justice, and hated iniquity:","therefore God, thy God, hath anointed thee with the oil of gladness above thy fellows."]},{"v":9,"lines":["Myrrh and stacte and cassia perfume thy garments, from the ivory houses:","out of which"]},{"v":10,"lines":["The daughters of kings have delighted thee in thy glory. The queen stood on thy right hand, in gilded clothing;","surrounded with variety."]},{"v":11,"lines":["Hearken, O daughter, and see, and incline thy ear:","and forget thy people and thy father's house."]},{"v":12,"lines":["And the king shall greatly desire thy beauty;","for he is the Lord thy God, and him they shall adore."]},{"v":13,"lines":["And the daughters of Tyre with gifts, yea, all the rich among the people, shall entreat thy countenance."]},{"v":14,"lines":["All the glory of the king's daughter is within in golden borders,"]},{"v":15,"lines":["Clothed round about with varieties. After her shall virgins be brought to the king:","her neighbours shall be brought to thee."]},{"v":16,"lines":["They shall be brought with gladness and rejoicing:","they shall be brought into the temple of the king."]},{"v":17,"lines":["Instead of thy fathers, sons are born to thee:","thou shalt make them princes over all the earth."]},{"v":18,"lines":["They shall remember thy name throughout all generations. Therefore shall people praise thee for ever;","yea, for ever and ever."]}]},{"n":45,"incipit":"Deus noster refugium","verses":[{"v":1,"lines":["Unto the end, for the sons of Core, for the hidden."],"title":true},{"v":2,"lines":["Our God is our refuge and strength:","a helper in troubles, which have found us exceedingly."]},{"v":3,"lines":["Therefore we will not fear, when the earth shall be troubled;","and the mountains shall be removed into the heart of the sea."]},{"v":4,"lines":["Their waters roared and were troubled:","the mountains were troubled with his strength."]},{"v":5,"lines":["The stream of the river maketh the city of God joyful:","the most High hath sanctified his own tabernacle."]},{"v":6,"lines":["God is in the midst thereof, it shall not be moved:","God will help it in the morning early."]},{"v":7,"lines":["Nations were troubled, and kingdoms were bowed down:","he uttered his voice, the earth trembled."]},{"v":8,"lines":["The Lord of armies is with us:","the God of Jacob is our protector."]},{"v":9,"lines":["Come and behold ye the works of the Lord:","what wonders he hath done upon earth,"]},{"v":10,"lines":["Making wars to cease even to the end of the earth. He shall destroy the bow, and break the weapons:","and the shield he shall burn in the fire."]},{"v":11,"lines":["Be still and see that I am God;","I will be exalted among the nations, and I will be exalted in the earth."]},{"v":12,"lines":["The Lord of armies is with us:","the God of Jacob is our protector."]}]},{"n":46,"incipit":"Omnes gentes, plaudite","verses":[{"v":1,"lines":["Unto the end, for the sons of Core."],"title":true},{"v":2,"lines":["O clap your hands, all ye nations:","shout unto God with the voice of joy,"]},{"v":3,"lines":["For the Lord is high, terrible:","a great king over all the earth."]},{"v":4,"lines":["He hath subdued the people under us;","and the nations under our feet."]},{"v":5,"lines":["He hath chosen for us his inheritance the beauty of Jacob which he hath loved."]},{"v":6,"lines":["God is ascended with jubilee, and the Lord with the sound of trumpet."]},{"v":7,"lines":["Sing praises to our God, sing ye:","sing praises to our king, sing ye."]},{"v":8,"lines":["For God is the king of all the earth:","sing ye wisely."]},{"v":9,"lines":["God shall reign over the nations:","God sitteth on his holy throne."]},{"v":10,"lines":["The princes of the people are gathered together, with the God of Abraham:","for the strong gods of the earth are exceedingly exalted."]}]},{"n":47,"incipit":"Magnus Dominus","verses":[{"v":1,"lines":["A psalm of a canticle, for the sons of Core, on the second day of the week."],"title":true},{"v":2,"lines":["Great is the Lord, and exceedingly to be praised in the city of our God, in his holy mountain."]},{"v":3,"lines":["With the joy of the whole earth is mount Sion founded, on the sides of the north, the city of the great king."]},{"v":4,"lines":["In her houses shall God be known, when he shall protect her."]},{"v":5,"lines":["For behold the kings of the earth assembled themselves:","they gathered together."]},{"v":6,"lines":["So they saw, and they wondered, they were troubled, they were moved:"]},{"v":7,"lines":["Trembling took hold of them. There were pains as of a woman in labour."]},{"v":8,"lines":["With a vehement wind thou shalt break in pieces the ships of Tharsis."]},{"v":9,"lines":["As we have heard, so have we seen, in the city of the Lord of hosts, in the city of our God:","God hath founded it for ever."]},{"v":10,"lines":["We have received thy mercy, O God, in the midst of thy temple."]},{"v":11,"lines":["According to thy name, O God, so also is thy praise unto the ends of the earth:","thy right hand is full of justice."]},{"v":12,"lines":["Let mount Sion rejoice, and the daughters of Juda be glad;","because of thy judgments, O Lord."]},{"v":13,"lines":["Surround Sion, and encompass her:","tell ye in her towers."]},{"v":14,"lines":["Set your hearts on her strength;","and distribute her houses, that ye may relate it in another generation."]},{"v":15,"lines":["For this is God, our God unto eternity, and for ever and ever:","he shall rule us for evermore."]}]},{"n":48,"incipit":"Audite haec, omnes","verses":[{"v":1,"lines":["Unto the end, a psalm for the sons of Core."],"title":true},{"v":2,"lines":["Hear these things, all ye nations:","give ear, all ye inhabitants of the world."]},{"v":3,"lines":["All you that are earthborn, and you sons of men:","both rich and poor together."]},{"v":4,"lines":["My mouth shall speak wisdom:","and the meditation of my heart understanding."]},{"v":5,"lines":["I will incline my ear to a parable;","I will open my proposition on the psaltery."]},{"v":6,"lines":["Why shall I fear in the evil day? the iniquity of my heel shall encompass me."]},{"v":7,"lines":["They that trust in their own strength, and glory in the multitude of their riches,"]},{"v":8,"lines":["No brother can redeem, nor shall man redeem:","he shall not give to God his ransom,"]},{"v":9,"lines":["Nor the price of the redemption of his soul:","and shall labour for ever,"]},{"v":10,"lines":["And shall still live unto the end."]},{"v":11,"lines":["He shall not see destruction, when he shall see the wise dying:","the senseless and the fool shall perish together:","And they shall leave their riches to strangers:"]},{"v":12,"lines":["And their sepulchres shall be their houses for ever. Their dwelling places to all generations:","they have called their lands by their names."]},{"v":13,"lines":["And man when he was in honour did not understand;","he is compared to senseless beasts, and is become like to them."]},{"v":14,"lines":["This way of theirs is a stumblingblock to them:","and afterwards they shall delight in their mouth."]},{"v":15,"lines":["They are laid in hell like sheep:","death shall feed upon them. And the just shall have dominion over them in the morning;","and their help shall decay in hell from their glory."]},{"v":16,"lines":["But God will redeem my soul from the hand of hell, when he shall receive me."]},{"v":17,"lines":["Be not thou afraid, when a man shall be made rich, and when the glory of his house shall be increased."]},{"v":18,"lines":["For when he shall die he shall take nothing away;","nor shall his glory descend with him."]},{"v":19,"lines":["For in his lifetime his soul will be blessed:","and he will praise thee when thou shalt do well to him."]},{"v":20,"lines":["He shall go in to the generations of his fathers:","and he shall never see light."]},{"v":21,"lines":["Man when he was in honour did not understand:","he hath been compared to senseless beasts, and made like to them."]}]},{"n":49,"incipit":"Deus deorum","verses":[{"v":1,"lines":["The God of gods, the Lord hath spoken:","and he hath called the earth. From the rising of the sun, to the going down thereof:"],"heading":"A psalm for Asaph."},{"v":2,"lines":["Out of Sion the loveliness of his beauty."]},{"v":3,"lines":["God shall come manifestly:","our God shall come, and shall not keep silence. A fire shall burn before him:","and a mighty tempest shall be round about him."]},{"v":4,"lines":["He shall call heaven from above, and the earth, to judge his people."]},{"v":5,"lines":["Gather ye together his saints to him:","who set his covenant before sacrifices."]},{"v":6,"lines":["And the heavens shall declare his justice:","for God is judge."]},{"v":7,"lines":["Hear, O my people, and I will speak:","O Israel, and I will testify to thee:","I am God, thy God."]},{"v":8,"lines":["I will not reprove thee for thy sacrifices:","and thy burnt offerings are always in my sight."]},{"v":9,"lines":["I will not take calves out of thy house:","nor he-goats out of thy flocks."]},{"v":10,"lines":["For all the beasts of the woods are mine:","the cattle on the hills, and the oxen."]},{"v":11,"lines":["I know all the fowls of the air:","and with me is the beauty of the field."]},{"v":12,"lines":["If I should be hungry, I would not tell thee:","for the world is mine, and the fulness thereof."]},{"v":13,"lines":["Shall I eat the flesh of bullocks? or shall I drink the blood of goats?"]},{"v":14,"lines":["Offer to God the sacrifice of praise:","and pay thy vows to the most High."]},{"v":15,"lines":["And call upon me in the day of trouble:","I will deliver thee, and thou shalt glorify me."]},{"v":16,"lines":["But to the sinner God hath said:","Why dost thou declare my justices, and take my covenant in thy mouth?"]},{"v":17,"lines":["Seeing thou hast hated discipline:","and hast cast my words behind thee."]},{"v":18,"lines":["If thou didst see a thief thou didst run with him:","and with adulterers thou hast been a partaker."]},{"v":19,"lines":["Thy mouth hath abounded with evil, and thy tongue framed deceits."]},{"v":20,"lines":["Sitting thou didst speak against thy brother, and didst lay a scandal against thy mother's son:"]},{"v":21,"lines":["These things hast thou done, and I was silent. Thou thoughtest unjustly that I should be like to thee:","but I will reprove thee, and set before thy face."]},{"v":22,"lines":["Understand these things, you that forget God;","lest he snatch you away, and there be none to deliver you."]},{"v":23,"lines":["The sacrifice of praise shall glorify me:","and there is the way by which I will shew him the salvation of God."]}]},{"n":50,"incipit":"Miserere mei, Deus","verses":[{"v":1,"lines":["Unto the end, a psalm of David,"],"title":true},{"v":2,"lines":["When Nathan the prophet came to him, after he had sinned with Bethsabee."],"title":true},{"v":3,"lines":["Have mercy on me, O God, according to thy great mercy. And according to the multitude of thy tender mercies blot out my iniquity."]},{"v":4,"lines":["Wash me yet more from my iniquity, and cleanse me from my sin."]},{"v":5,"lines":["For I know my iniquity, and my sin is always before me."]},{"v":6,"lines":["To thee only have I sinned, and have done evil before thee:","that thou mayst be justified in thy words, and mayst overcome when thou art judged."]},{"v":7,"lines":["For behold I was conceived in iniquities;","and in sins did my mother conceive me."]},{"v":8,"lines":["For behold thou hast loved truth:","the uncertain and hidden things of thy wisdom thou hast made manifest to me."]},{"v":9,"lines":["Thou shalt sprinkle me with hyssop, and I shall be cleansed:","thou shalt wash me, and I shall be made whiter than snow."]},{"v":10,"lines":["To my hearing thou shalt give joy and gladness:","and the bones that have been humbled shall rejoice."]},{"v":11,"lines":["Turn away thy face from my sins, and blot out all my iniquities."]},{"v":12,"lines":["Create a clean heart in me, O God:","and renew a right spirit within my bowels."]},{"v":13,"lines":["Cast me not away from thy face;","and take not thy holy spirit from me."]},{"v":14,"lines":["Restore unto me the joy of thy salvation, and strengthen me with a perfect spirit."]},{"v":15,"lines":["I will teach the unjust thy ways:","and the wicked shall be converted to thee."]},{"v":16,"lines":["Deliver me from blood, O God, thou God of my salvation:","and my tongue shall extol thy justice."]},{"v":17,"lines":["O Lord, thou wilt open my lips:","and my mouth shall declare thy praise."]},{"v":18,"lines":["For if thou hadst desired sacrifice, I would indeed have given it:","with burnt offerings thou wilt not be delighted."]},{"v":19,"lines":["A sacrifice to God is an afflicted spirit:","a contrite and humbled heart, O God, thou wilt not despise."]},{"v":20,"lines":["Deal favourably, O Lord, in thy good will with Sion;","that the walls of Jerusalem may be built up."]},{"v":21,"lines":["Then shalt thou accept the sacrifice of justice, oblations and whole burnt offerings:","then shall they lay calves upon thy altar."]}]},{"n":51,"incipit":"Quid gloriaris?","verses":[{"v":1,"lines":["Unto the end, understanding for David,"],"title":true},{"v":2,"lines":["When Doeg the Edomite came and told Saul: David went to the house of Achimelech."],"title":true},{"v":3,"lines":["Why dost thou glory in malice, thou that art mighty in iniquity?"]},{"v":4,"lines":["All the day long thy tongue hath devised injustice:","as a sharp razor, thou hast wrought deceit."]},{"v":5,"lines":["Thou hast loved malice more than goodness:","and iniquity rather than to speak righteousness."]},{"v":6,"lines":["Thou hast loved all the words of ruin, O deceitful tongue."]},{"v":7,"lines":["Therefore will God destroy thee for ever:","he will pluck thee out, and remove thee from thy dwelling place:","and thy root out of the land of the living."]},{"v":8,"lines":["The just shall see and fear, and shall laugh at him, and say:"]},{"v":9,"lines":["Behold the man that made not God his helper:","But trusted in the abundance of his riches:","and prevailed in his vanity."]},{"v":10,"lines":["But I, as a fruitful olive tree in the house of God, have hoped in the mercy of God for ever, yea for ever and ever."]},{"v":11,"lines":["I will praise thee for ever, because thou hast done it:","and I will wait on thy name, for it is good in the sight of thy saints."]}]},{"n":52,"incipit":"Dixit insipiens","verses":[{"v":1,"lines":["The fool said in his heart:","There is no God."],"heading":"Unto the end, for Maeleth, understandings to David."},{"v":2,"lines":["They are corrupted, and become abominable in iniquities:","there is none that doth good."]},{"v":3,"lines":["God looked down from heaven on the children of men:","to see if there were any that did understand, or did seek God."]},{"v":4,"lines":["All have gone aside, they are become unprofitable together, there is none that doth good, no not one."]},{"v":5,"lines":["Shall not all the workers of iniquity know, who eat up my people as they eat bread?"]},{"v":6,"lines":["They have not called upon God:","there have they trembled for fear, where there was no fear. For God hath scattered the bones of them that please men:","they have been confounded, because God hath despised them."]},{"v":7,"lines":["Who will give out of Sion the salvation of Israel? when God shall bring back the captivity of his people, Jacob shall rejoice, and Israel shall be glad."]}]},{"n":53,"incipit":"Deus, in nomine","verses":[{"v":1,"lines":["Unto the end, in verses, understanding for David."],"title":true},{"v":2,"lines":["When the en of Ziph had come and said to Saul: Is not David hidden with us?"],"title":true},{"v":3,"lines":["Save me, O God, by thy name, and judge me in thy strength."]},{"v":4,"lines":["O God, hear my prayer:","give ear to the words of my mouth."]},{"v":5,"lines":["For strangers have risen up against me;","and the mighty have sought after my soul:","and they have not set God before their eyes."]},{"v":6,"lines":["For behold God is my helper:","and the Lord is the protector of my soul."]},{"v":7,"lines":["Turn back the evils upon my enemies;","and cut them off in thy truth."]},{"v":8,"lines":["I will freely sacrifice to thee, and will give praise, O God, to thy name:","because it is good:"]},{"v":9,"lines":["For thou hast delivered me out of all trouble:","and my eye hath looked down upon my enemies."]}]},{"n":54,"incipit":"Exaudi, Deus","verses":[{"v":1,"lines":["Unto the end, in verses, understanding for David."],"title":true},{"v":2,"lines":["Hear, O God, my prayer, and despise not my supplication:"]},{"v":3,"lines":["Be attentive to me and hear me. I am grieved in my exercise;","and am troubled,"]},{"v":4,"lines":["At the voice of the enemy, and at the tribulation of the sinner. For they have cast iniquities upon me:","and in wrath they were troublesome to me."]},{"v":5,"lines":["My heart is troubled within me:","and the fear of death is fallen upon me."]},{"v":6,"lines":["Fear and trembling are come upon me:","and darkness hath covered me."]},{"v":7,"lines":["And I said:","Who will give me wings like a dove, and I will fly and be at rest?"]},{"v":8,"lines":["Lo, I have gone far off flying away;","and I abode in the wilderness."]},{"v":9,"lines":["I waited for him that hath saved me from pusillanimity of spirit, and a storm."]},{"v":10,"lines":["Cast down, O Lord, and divide their tongues;","for I have seen iniquity and contradiction in the city."]},{"v":11,"lines":["Day and night shall iniquity surround it upon its walls:","and in the midst thereof are labour,"]},{"v":12,"lines":["And injustice. And usury and deceit have not departed from its streets."]},{"v":13,"lines":["For if my enemy had reviled me, I would verily have borne with it. And if he that hated me had spoken great things against me, I would perhaps have hidden myself from him."]},{"v":14,"lines":["But thou a man of one mind, my guide, and my familiar,"]},{"v":15,"lines":["Who didst take sweetmeats together with me:","in the house of God we walked with consent."]},{"v":16,"lines":["Let death come upon them, and let them go down alive into hell. For there is wickedness in their dwellings:","in the midst of them."]},{"v":17,"lines":["But I have cried to God:","and the Lord will save me."]},{"v":18,"lines":["Evening and morning, and at noon I will speak and declare:","and he shall hear my voice."]},{"v":19,"lines":["He shall redeem my soul in peace from them that draw near to me:","for among many they were with me."]},{"v":20,"lines":["God shall hear, and the Eternal shall humble them. For there is no change with them, and they have not feared God:"]},{"v":21,"lines":["He hath stretched forth his hand to repay. They have defiled his covenant,"]},{"v":22,"lines":["They are divided by the wrath of his countenance, and his heart hath drawn near. His words are smoother than oil, and the same are darts."]},{"v":23,"lines":["Cast thy care upon the Lord, and he shall sustain thee:","he shall not suffer the just to waver for ever."]},{"v":24,"lines":["But thou, O God, shalt bring them down into the pit of destruction. Bloody and deceitful men shall not live out half their days;","but I will trust in thee, O Lord."]}]},{"n":55,"incipit":"Miserere mei, Deus","verses":[{"v":1,"lines":["Unto the end, for a people that is removed at a distance form the sanctuary: for David, for an inscription of a title (or pillar) when the Philistines held him in Geth."],"title":true},{"v":2,"lines":["Have mercy on me, O God, for man hath trodden me under foot;","all the day long he hath afflicted me fighting against me."]},{"v":3,"lines":["My enemies have trodden on me all the day long;","for they are many that make war against me."]},{"v":4,"lines":["From the height of the day I shall fear:","but I will trust in thee."]},{"v":5,"lines":["In God I will praise my words, in God I have put my trust:","I will not fear what flesh can do against me."]},{"v":6,"lines":["All the day long they detested my words:","all their thoughts were against me unto evil."]},{"v":7,"lines":["They will dwell and hide themselves:","they will watch my heel. As they have waited for my soul,"]},{"v":8,"lines":["For nothing shalt thou save them:","in thy anger thou shalt break the people in pieces. O God,"]},{"v":9,"lines":["I have declared to thee my life:","thou hast set my tears in thy sight, As also in thy promise."]},{"v":10,"lines":["Then shall my enemies be turned back. In what day soever I shall call upon thee, behold I know thou art my God."]},{"v":11,"lines":["In God will I praise the word, in the Lord will I praise his speech. In God have I hoped, I will not fear what man can do to me."]},{"v":12,"lines":["In me, O God, are vows to thee, which I will pay, praises to thee:"]},{"v":13,"lines":["Because thou hast delivered my soul from death, my feet from falling:","that I may please in the sight of God, in the light of the living."]}]},{"n":56,"incipit":"Miserere mei, Deus","verses":[{"v":1,"lines":["Unto the end, destroy not, for David, for an inscription of a title, when he fled from Saul into the cave."],"title":true},{"v":2,"lines":["Have mercy on me, O God, have mercy on me:","for my soul trusteth in thee. And in the shadow of thy wings will I hope, until iniquity pass away."]},{"v":3,"lines":["I will cry to God the most high;","to God who hath done good to me."]},{"v":4,"lines":["He hath sent from heaven and delivered me:","he hath made them a reproach that trod upon me. God hath sent his mercy and his truth,"]},{"v":5,"lines":["And he hath delivered my soul from the midst of the young lions. I slept troubled. The sons of men, whose teeth are weapons and arrows, and their tongue a sharp sword."]},{"v":6,"lines":["Be thou exalted, O God, above the heavens, and thy glory above all the earth."]},{"v":7,"lines":["They prepared a snare for my feet;","and they bowed down my soul. They dug a pit before my face, and they are fallen into it."]},{"v":8,"lines":["My heart is ready, O God, my heart is ready:","I will sing, and rehearse a psalm."]},{"v":9,"lines":["Arise, O my glory, arise psaltery and harp:","I will arise early."]},{"v":10,"lines":["I will give praise to thee, O Lord, among the people:","I will sing a psalm to thee among the nations."]},{"v":11,"lines":["For thy mercy is magnified even to the heavens:","and thy truth unto the clouds."]},{"v":12,"lines":["Be thou exalted, O God, above the heavens:","and thy glory above all the earth."]}]},{"n":57,"incipit":"Si vere utique","verses":[{"v":1,"lines":["Unto the end, destroy not, for David, for an inscription of a title."],"title":true},{"v":2,"lines":["If in very deed you speak justice:","judge right things, ye sons of men."]},{"v":3,"lines":["For in your heart you work iniquity:","your hands forge injustice in the earth."]},{"v":4,"lines":["The wicked are alienated from the womb;","they have gone astray from the womb:","they have spoken false things."]},{"v":5,"lines":["Their madness is according to the likeness of a serpent:","like the deaf asp that stoppeth her ears:"]},{"v":6,"lines":["Which will not hear the voice of the charmers;","nor of the wizard that charmeth wisely."]},{"v":7,"lines":["God shall break in pieces their teeth in their mouth:","the Lord shall break the grinders of the lions."]},{"v":8,"lines":["They shall come to nothing, like water running down;","he hath bent his bow till they be weakened."]},{"v":9,"lines":["Like wax that melteth they shall be taken away:","fire hath fallen on them, and they shall not see the sun."]},{"v":10,"lines":["Before your thorns could know the brier;","he swalloweth them up, as alive, in his wrath."]},{"v":11,"lines":["The just shall rejoice when he shall see the revenge:","he shall wash his hands in the blood of the sinner."]},{"v":12,"lines":["And man shall say:","If indeed there be fruit to the just:","there is indeed a God that judgeth them on the earth."]}]},{"n":58,"incipit":"Eripe me de inimicis","verses":[{"v":1,"lines":["Unto the end, destroy not, for David for an inscription of a title, when Saul sent and watched his house to kill him."],"title":true},{"v":2,"lines":["Deliver me from my enemies, O my God;","and defend me from them that rise up against me."]},{"v":3,"lines":["Deliver me from them that work iniquity, and save me from bloody men."]},{"v":4,"lines":["For behold they have caught my soul:","the mighty have rushed in upon me:"]},{"v":5,"lines":["Neither is it my iniquity, nor my sin, O Lord:","without iniquity have I run, and directed my steps."]},{"v":6,"lines":["Rise up thou to meet me, and behold:","even thou, O Lord, the God of hosts, the God of Israel. Attend to visit all the nations:","have no mercy on all them that work iniquity."]},{"v":7,"lines":["They shall return at evening, and shall suffer hunger like dogs:","and shall go round about the city."]},{"v":8,"lines":["Behold they shall speak with their mouth, and a sword is in their lips:","for who, say they, hath heard us?"]},{"v":9,"lines":["But thou, O Lord, shalt laugh at them:","thou shalt bring all the nations to nothing."]},{"v":10,"lines":["I will keep my strength to thee:","for thou art my protector:"]},{"v":11,"lines":["My God, his mercy shall prevent me."]},{"v":12,"lines":["God shall let me see over my enemies:","slay them not, lest at any time my people forget. Scatter them by thy power;","and bring them down, O Lord, my protector:"]},{"v":13,"lines":["For the sin of their mouth, and the word of their lips:","and let them be taken in their pride. And for their cursing and lying they shall be talked of,"]},{"v":14,"lines":["When they are consumed:","when they are consumed by thy wrath, and they shall be no more. And they shall know that God will rule Jacob, and all the ends of the earth."]},{"v":15,"lines":["They shall return at evening and shall suffer hunger like dogs:","and shall go round about the city."]},{"v":16,"lines":["They shall be scattered abroad to eat, and shall murmur if they be not filled."]},{"v":17,"lines":["But I will sing thy strength:","and will extol thy mercy in the morning. For thou art become my support, and my refuge, in the day of my trouble."]},{"v":18,"lines":["Unto thee, O my helper, will I sing, for thou art God my defence:","my God my mercy."]}]},{"n":59,"incipit":"Deus, repulisti nos","verses":[{"v":1,"lines":["Unto the end, for them that shall be changed, for the inscription of a title, to David himself, for doctrine,"],"title":true},{"v":2,"lines":["When he set fire to Mesopotamia of Syria and Sobal: and Joab returned and slew of Edom, in the vale of the saltpits, twelve thousand men."],"title":true},{"v":3,"lines":["O God, thou hast cast us off, and hast destroyed us;","thou hast been angry, and hast had mercy on us."]},{"v":4,"lines":["Thou hast moved the earth, and hast troubled it:","heal thou the breaches thereof, for it has been moved."]},{"v":5,"lines":["Thou hast shewn thy people hard things;","thou hast made us drink wine of sorrow."]},{"v":6,"lines":["Thou hast given a warning to them that fear thee:","that they may flee from before the bow:","That thy beloved may be delivered."]},{"v":7,"lines":["Save me with thy right hand, and hear me."]},{"v":8,"lines":["God hath spoken in his holy place:","I will rejoice, and I will divide Sichem;","and will mete out the vale of tabernacles."]},{"v":9,"lines":["Galaad is mine, and Manasses is mine:","and Ephraim is the strength of my head. Juda is my king:"]},{"v":10,"lines":["Moab is the pot of my hope. Into Edom will I stretch out my shoe:","to me the foreigners are made subject."]},{"v":11,"lines":["Who will bring me into the strong city? who will lead me into Edom?"]},{"v":12,"lines":["Wilt not thou, O God, who hast cast us off? and wilt not thou, O God, go out with our armies?"]},{"v":13,"lines":["Give us help from trouble:","for vain is the salvation of man."]},{"v":14,"lines":["Through God we shall do mightily:","and he shall bring to nothing them that afflict us."]}]},{"n":60,"incipit":"Exaudi, Deus","verses":[{"v":1,"lines":["Unto the end, in hymns, for David."],"title":true},{"v":2,"lines":["Hear, O God, my supplication:","be attentive to my prayer."]},{"v":3,"lines":["To thee have I cried from the ends of the earth:","when my heart was in anguish, thou hast exalted me on a rock. Thou hast conducted me;"]},{"v":4,"lines":["For thou hast been my hope;","a tower of strength against the face of the enemy."]},{"v":5,"lines":["In thy tabernacle I shall dwell for ever:","I shall be protected under the covert of thy wings."]},{"v":6,"lines":["For thou, my God, hast heard my prayer:","thou hast given an inheritance to them that fear thy name."]},{"v":7,"lines":["Thou wilt add days to the days of the king:","his years even to generation and generation."]},{"v":8,"lines":["He abideth for ever in the sight of God:","his mercy and truth who shall search?"]},{"v":9,"lines":["So will I sing a psalm to thy name for ever and ever:","that I may pay my vows from day to day."]}]},{"n":61,"incipit":"Nonne Deo","verses":[{"v":1,"lines":["Unto the end, for Idithun, a psalm of David."],"title":true},{"v":2,"lines":["Shall not my soul be subject to God? for from him is my salvation."]},{"v":3,"lines":["For he is my God and my saviour:","he is my protector, I shall be moved no more."]},{"v":4,"lines":["How long do you rush in upon a man? you all kill, as if you were thrusting down a leaning wall, and a tottering fence."]},{"v":5,"lines":["But they have thought to cast away my price;","I ran in thirst:","they blessed with their mouth, but cursed with their heart."]},{"v":6,"lines":["But be thou, O my soul, subject to God:","for from him is my patience."]},{"v":7,"lines":["For he is my God and my saviour:","he is my helper, I shall not be moved."]},{"v":8,"lines":["In God is my salvation and my glory:","he is the God of my help, and my hope is in God."]},{"v":9,"lines":["Trust in him, all ye congregation of people:","pour out your hearts before him. God is our helper for ever."]},{"v":10,"lines":["But vain are the sons of men, the sons of men are liars in the balances:","that by vanity they may together deceive."]},{"v":11,"lines":["Trust not in iniquity, and cover not robberies:","if riches abound, set not your heart upon them."]},{"v":12,"lines":["God hath spoken once, these two things have I heard, that power belongeth to God,"]},{"v":13,"lines":["And mercy to thee, O Lord;","for thou wilt render to every man according to his works."]}]},{"n":62,"incipit":"Deus, Deus meus","verses":[{"v":1,"lines":["A psalm of David while he was in the desert of Edom."],"title":true},{"v":2,"lines":["O God, my God, to thee do I watch at break of day. For thee my soul hath thirsted;","for thee my flesh, O how many ways!"]},{"v":3,"lines":["In a desert land, and where there is no way, and no water:","so in the sanctuary have I come before thee, to see thy power and thy glory."]},{"v":4,"lines":["For thy mercy is better than lives:","thee my lips shall praise."]},{"v":5,"lines":["Thus will I bless thee all my life long:","and in thy name I will lift up my hands."]},{"v":6,"lines":["Let my soul be filled as with marrow and fatness:","and my mouth shall praise thee with joyful lips."]},{"v":7,"lines":["If I have remembered thee upon my bed, I will meditate on thee in the morning:"]},{"v":8,"lines":["Because thou hast been my helper. And I will rejoice under the covert of thy wings:"]},{"v":9,"lines":["My soul hath stuck close to thee:","thy right hand hath received me."]},{"v":10,"lines":["But they have sought my soul in vain, they shall go into the lower parts of the earth:"]},{"v":11,"lines":["They shall be delivered into the hands of the sword, they shall be the portions of foxes."]},{"v":12,"lines":["But the king shall rejoice in God, all they shall be praised that swear by him:","because the mouth is stopped of them that speak wicked things."]}]},{"n":63,"incipit":"Exaudi, Deus","verses":[{"v":1,"lines":["Unto the end, a psalm for David."],"title":true},{"v":2,"lines":["Hear O God, my prayer, when I make supplication to thee:","deliver my soul from the fear of the enemy."]},{"v":3,"lines":["Thou hast protected me from the assembly of the malignant;","from the multitude of the workers of iniquity."]},{"v":4,"lines":["For they have whetted their tongues like a sword;","they have bent their bow a bitter thing,"]},{"v":5,"lines":["To shoot in secret the undefiled."]},{"v":6,"lines":["They will shoot at him on a sudden, and will not fear:","they are resolute in wickedness. They have talked of hiding snares;","they have said:","Who shall see them?"]},{"v":7,"lines":["They have searched after iniquities:","they have failed in their search. Man shall come to a deep heart:"]},{"v":8,"lines":["And God shall be exalted. The arrows of children are their wounds:"]},{"v":9,"lines":["And their tongues against them are made weak. All that saw them were troubled;"]},{"v":10,"lines":["And every man was afraid. And they declared the works of God, and understood his doings."]},{"v":11,"lines":["The just shall rejoice in the Lord, and shall hope in him:","and all the upright in heart shall be praised."]}]},{"n":64,"incipit":"Te decet hymnus","verses":[{"v":1,"lines":["To the end, a psalm of David. The canticle of Jeremias and Ezechiel to the people of the captivity, when they began to go out."],"title":true},{"v":2,"lines":["A hymn, O God, becometh thee in Sion:","and a vow shall be paid to thee in Jerusalem."]},{"v":3,"lines":["O hear my prayer:","all flesh shall come to thee."]},{"v":4,"lines":["The words of the wicked have prevailed over us:","and thou wilt pardon our transgressions."]},{"v":5,"lines":["Blessed is he whom thou hast chosen and taken to thee:","he shall dwell in thy courts. We shall be filled with the good things of thy house;","holy is thy temple,"]},{"v":6,"lines":["Wonderful in justice. Hear us, O God our saviour, who art the hope of all the ends of the earth, and in the sea afar off."]},{"v":7,"lines":["Thou who preparest the mountains by thy strength, being girded with power:"]},{"v":8,"lines":["Who troublest the depth of the sea, the noise of its waves. The Gentiles shall be troubled,"]},{"v":9,"lines":["And they that dwell in the uttermost borders shall be afraid at thy signs:","thou shalt make the outgoings of the morning and of the evening to be joyful."]},{"v":10,"lines":["Thou hast visited the earth, and hast plentifully watered it;","thou hast many ways enriched it. The river of God is filled with water, thou hast prepared their food:","for so is its preparation."]},{"v":11,"lines":["Fill up plentifully the streams thereof, multiply its fruits;","it shall spring up and rejoice in its showers."]},{"v":12,"lines":["Thou shalt bless the crown of the year of thy goodness:","and thy fields shall be filled with plenty."]},{"v":13,"lines":["The beautiful places of the wilderness shall grow fat:","and the hills shall be girded about with joy,"]},{"v":14,"lines":["The rams of the flock are clothed, and the vales shall abound with corn:","they shall shout, yea they shall sing a hymn."]}]},{"n":65,"incipit":"Jubilate Deo","verses":[{"v":1,"lines":["Shout with joy to God, all the earth,"],"heading":"Unto the end, a canticle of a psalm of the resurrection."},{"v":2,"lines":["Sing ye a psalm to his name;","give glory to his praise."]},{"v":3,"lines":["Say unto God, How terrible are thy works, O Lord! in the multitude of thy strength thy enemies shall lie to thee."]},{"v":4,"lines":["Let all the earth adore thee, and sing to thee:","let it sing a psalm to thy name."]},{"v":5,"lines":["Come and see the works of God;","who is terrible in his counsels over the sons of men."]},{"v":6,"lines":["Who turneth the sea into dry land, in the river they shall pass on foot:","there shall we rejoice in him."]},{"v":7,"lines":["Who by his power ruleth for ever:","his eyes behold the nations;","let not them that provoke him be exalted in themselves."]},{"v":8,"lines":["O bless our God, ye Gentiles:","and make the voice of his praise to be heard."]},{"v":9,"lines":["Who hath set my soul to live:","and hath not suffered my feet to be moved:"]},{"v":10,"lines":["For thou, O God, hast proved us:","thou hast tried us by fire, as silver is tried."]},{"v":11,"lines":["Thou hast brought us into a net, thou hast laid afflictions on our back:"]},{"v":12,"lines":["Thou hast set men over our heads. We have passed through fire and water, and thou hast brought us out into a refreshment."]},{"v":13,"lines":["I will go into thy house with burnt offerings:","I will pay thee my vows,"]},{"v":14,"lines":["Which my lips have uttered, And my mouth hath spoken, when I was in trouble."]},{"v":15,"lines":["I will offer up to thee holocausts full of marrow, with burnt offerings of rams:","I will offer to thee bullocks with goats."]},{"v":16,"lines":["Come and hear, all ye that fear God, and I will tell you what great things he hath done for my soul."]},{"v":17,"lines":["I cried to him with my mouth:","and I extolled him with my tongue."]},{"v":18,"lines":["If I have looked at iniquity in my heart, the Lord will not hear me."]},{"v":19,"lines":["Therefore hath God heard me, and hath attended to the voice of my supplication."]},{"v":20,"lines":["Blessed be God, who hath not turned away my prayer, nor his mercy from me."]}]},{"n":66,"incipit":"Deus misereatur","verses":[{"v":1,"lines":["Unto the end, in hymns, a psalm of a canticle for David."],"title":true},{"v":2,"lines":["May God have mercy on us, and bless us:","may he cause the light of his countenance to shine upon us, and may he have mercy on us."]},{"v":3,"lines":["That we may know thy way upon earth:","thy salvation in all nations."]},{"v":4,"lines":["Let people confess to thee, O God:","let all people give praise to thee."]},{"v":5,"lines":["Let the nations be glad and rejoice:","for thou judgest the people with justice, and directest the nations upon earth."]},{"v":6,"lines":["Let the people, O God, confess to thee:","let all the people give praise to thee:"]},{"v":7,"lines":["The earth hath yielded her fruit. May God, our God bless us,"]},{"v":8,"lines":["May God bless us:","and all the ends of the earth fear him."]}]},{"n":67,"incipit":"Exsurgat Deus","verses":[{"v":1,"lines":["Unto the end, a psalm of a canticle for David himself."],"title":true},{"v":2,"lines":["Let God arise, and let his enemies be scattered:","and let them that hate him flee from before his face."]},{"v":3,"lines":["As smoke vanisheth, so let them vanish away:","as wax melteth before the fire, so let the wicked perish at the presence of God."]},{"v":4,"lines":["And let the just feast, and rejoice before God:","and be delighted with gladness."]},{"v":5,"lines":["Sing ye to God, sing a psalm to his name, make a way for him who ascendeth upon the west:","the Lord is his name. Rejoice ye before him:","but the wicked shall be troubled at his presence,"]},{"v":6,"lines":["Who is the father of orphans, and the judge of widows. God in his holy place:"]},{"v":7,"lines":["God who maketh men of one manner to dwell in a house:","Who bringeth out them that were bound in strength;","in like manner them that provoke, that dwell in sepulchres."]},{"v":8,"lines":["O God, when thou didst go forth in the sight of thy people, when thou didst pass through the desert:"]},{"v":9,"lines":["The earth was moved, and the heavens dropped at the presence of the God of Sina, at the presence of the God of Israel."]},{"v":10,"lines":["Thou shalt set aside for thy inheritance a free rain, O God:","and it was weakened, but thou hast made it perfect."]},{"v":11,"lines":["In it shall thy animals dwell;","in thy sweetness, O God, thou hast provided for the poor."]},{"v":12,"lines":["The Lord shall give the word to them that preach good tidings with great power."]},{"v":13,"lines":["The king of powers is of the beloved, of the beloved;","and the beauty of the house shall divide spoils."]},{"v":14,"lines":["If you sleep among the midst of lots, you shall be as the wings of a dove covered with silver, and the hinder parts of her back with the paleness of gold."]},{"v":15,"lines":["When he that is in heaven appointeth kings over her, they shall be whited with snow in Selmon."]},{"v":16,"lines":["The mountain of God is a fat mountain. A curdled mountain, a fat mountain."]},{"v":17,"lines":["Why suspect, ye curdled mountains? A mountain in which God is well pleased to dwell:","for there the Lord shall dwell unto the end."]},{"v":18,"lines":["The chariot of God is attended by ten thousands;","thousands of them that rejoice:","the Lord is among them in Sina, in the holy place."]},{"v":19,"lines":["Thou hast ascended on high, thou hast led captivity captive;","thou hast received gifts in men. Yea for those also that do not believe, the dwelling of the Lord God."]},{"v":20,"lines":["Blessed be the Lord day by day:","the God of our salvation will make our journey prosperous to us."]},{"v":21,"lines":["Our God is the God of salvation:","and of the Lord, of the Lord are the issues from death."]},{"v":22,"lines":["But God shall break the heads of his enemies:","the hairy crown of them that walk on in their sins."]},{"v":23,"lines":["The Lord said:","I will turn them from Basan, I will turn them into the depth of the sea:"]},{"v":24,"lines":["That thy foot may be dipped in the blood of thy enemies;","the tongue of thy dogs be red with the same."]},{"v":25,"lines":["They have seen thy goings, O God, the goings of my God:","of my king who is in his sanctuary."]},{"v":26,"lines":["Princes went before joined with singers, in the midst of young damsels playing on timbrels."]},{"v":27,"lines":["In the churches bless ye God the Lord, from the fountains of Israel."]},{"v":28,"lines":["There is Benjamin a youth, in ecstasy of mind. The princes of Juda are their leaders:","the princes of Zabulon, the princes of Nephthali."]},{"v":29,"lines":["Command thy strength , O God:","confirm, O God, what thou hast wrought in us."]},{"v":30,"lines":["From thy temple in Jerusalem, kings shall offer presents to thee."]},{"v":31,"lines":["Rebuke the wild beasts of the reeds, the congregation of bulls with the kine of the people;","who seek to exclude them who are tried with silver. Scatter thou the nations that delight in wars:"]},{"v":32,"lines":["Ambassadors shall come out of Egypt:","Ethiopia shall soon stretch out her hands to God."]},{"v":33,"lines":["Sing to God, ye kingdoms of the earth:","sing ye to the Lord:","Sing ye to God,"]},{"v":34,"lines":["Who mounteth above the heaven of heavens, to the east. Behold he will give to his voice the voice of power:"]},{"v":35,"lines":["Give ye glory to God for Israel, his magnificence, and his power is in the clouds."]},{"v":36,"lines":["God is wonderful in his saints:","the God of Israel is he who will give power and strength to his people. Blessed be God."]}]},{"n":68,"incipit":"Salvum me fac","verses":[{"v":1,"lines":["Unto the end, for them that shall be changed; for David."],"title":true},{"v":2,"lines":["Save me, O God:","for the waters are come in even unto my soul."]},{"v":3,"lines":["I stick fast in the mire of the deep and there is no sure standing. I am come into the depth of the sea, and a tempest hath overwhelmed me."]},{"v":4,"lines":["I have laboured with crying;","my jaws are become hoarse, my eyes have failed, whilst I hope in my God."]},{"v":5,"lines":["They are multiplied above the hairs of my head, who hate me without cause. My enemies are grown strong who have wrongfully persecuted me:","then did I pay that which I took not away."]},{"v":6,"lines":["O God, thou knowest my foolishness;","and my offences are not hidden from thee:"]},{"v":7,"lines":["Let not them be ashamed for me, who look for thee, O Lord, the Lord of hosts. Let them not be confounded on my account, who seek thee, O God of Israel."]},{"v":8,"lines":["Because for thy sake I have borne reproach;","shame hath covered my face."]},{"v":9,"lines":["I am become a stranger to my brethren, and an alien to the sons of my mother."]},{"v":10,"lines":["For the zeal of thy house hath eaten me up:","and the reproaches of them that reproached thee are fallen upon me."]},{"v":11,"lines":["And I covered my soul in fasting:","and it was made a reproach to me."]},{"v":12,"lines":["And I made haircloth my garment:","and I became a byword to them."]},{"v":13,"lines":["They that sat in the gate spoke against me:","and they that drank wine made me their song."]},{"v":14,"lines":["But as for me, my prayer is to thee, O Lord;","for the time of thy good pleasure, O God. In the multitude of thy mercy hear me, in the truth of thy salvation."]},{"v":15,"lines":["Draw me out of the mire, that I may not stick fast:","deliver me from them that hate me, and out of the deep waters."]},{"v":16,"lines":["Let not the tempest of water drown me, nor the deep swallow me up:","and let not the pit shut her mouth upon me."]},{"v":17,"lines":["Hear me, O Lord, for thy mercy is kind;","look upon me according to the multitude of thy tender mercies."]},{"v":18,"lines":["And turn not away thy face from thy servant:","for I am in trouble, hear me speedily."]},{"v":19,"lines":["Attend to my soul, and deliver it:","save me because of my enemies."]},{"v":20,"lines":["Thou knowest my reproach, and my confusion, and my shame."]},{"v":21,"lines":["In thy sight are all they that afflict me;","my heart hath expected reproach and misery. And I looked for one that would grieve together with me, but there was none:","and for one that would comfort me, and I found none."]},{"v":22,"lines":["And they gave me gall for my food, and in my thirst they gave me vinegar to drink."]},{"v":23,"lines":["Let their table become as a snare before them, and a recompense, and a stumblingblock."]},{"v":24,"lines":["Let their eyes be darkened that they see not;","and their back bend thou down always."]},{"v":25,"lines":["Pour out thy indignation upon them:","and let thy wrathful anger take hold of them."]},{"v":26,"lines":["Let their habitation be made desolate:","and let there be none to dwell in their tabernacles."]},{"v":27,"lines":["Because they have persecuted him whom thou hast smitten;","and they have added to the grief of my wounds."]},{"v":28,"lines":["Add thou iniquity upon their iniquity:","and let them not come into thy justice."]},{"v":29,"lines":["Let them be blotted out of the book of the living;","and with the just let them not be written."]},{"v":30,"lines":["But I am poor and sorrowful:","thy salvation, O God, hath set me up."]},{"v":31,"lines":["I will praise the name of God with a canticle:","and I will magnify him with praise."]},{"v":32,"lines":["And it shall please God better than a young calf, that bringeth forth horns and hoofs."]},{"v":33,"lines":["Let the poor see and rejoice:","seek ye God, and your soul shall live."]},{"v":34,"lines":["For the Lord hath heard the poor:","and hath not despised his prisoners."]},{"v":35,"lines":["Let the heavens and the earth praise him;","the sea, and every thing that creepeth therein."]},{"v":36,"lines":["For God will save Sion, and the cities of Juda shall be built up. And they shall dwell there, and acquire it by inheritance."]},{"v":37,"lines":["And the seed of his servants shall possess it;","and they that love his name shall dwell therein."]}]},{"n":69,"incipit":"Deus, in adjutorium","verses":[{"v":1,"lines":["Unto the end, a psalm for David, to bring to remembrance that the Lord saved him."],"title":true},{"v":2,"lines":["O God, come to my assistance;","O Lord, make haste to help me."]},{"v":3,"lines":["Let them be confounded and ashamed that seek my soul:"]},{"v":4,"lines":["Let them be turned backward, and blush for shame that desire evils to me:","Let them be presently turned away blushing for shame that say to me:","Tis well, tis well ."]},{"v":5,"lines":["Let all that seek thee rejoice and be glad in thee;","and let such as love thy salvation say always:","The Lord be magnified."]},{"v":6,"lines":["But I am needy and poor;","O God, help me. Thou art my helper and my deliverer:","O lord, make no delay."]}]},{"n":70,"incipit":"In te, Domine, speravi","verses":[{"v":1,"lines":["In thee, O Lord, I have hoped, let me never be put to confusion:"],"heading":"A psalm for David. Of the sons of Jonadab, and the former captives."},{"v":2,"lines":["Deliver me in thy justice, and rescue me. Incline thy ear unto me, and save me."]},{"v":3,"lines":["Be thou unto me a God, a protector, and a place of strength:","that thou mayst make me safe. For thou art my firmament and my refuge."]},{"v":4,"lines":["Deliver me, O my God, out of the hand of the sinner, and out of the hand of the transgressor of the law and of the unjust."]},{"v":5,"lines":["For thou art my patience, O Lord:","my hope, O Lord, from my youth."]},{"v":6,"lines":["By thee have I been confirmed from the womb:","from my mother's womb thou art my protector. Of thee shall I continually sing:"]},{"v":7,"lines":["I am become unto many as a wonder, but thou art a strong helper."]},{"v":8,"lines":["Let my mouth be filled with praise, that I may sing thy glory;","thy greatness all the day long."]},{"v":9,"lines":["Cast me not off in the time of old age:","when my strength shall fail, do not thou forsake me."]},{"v":10,"lines":["For my enemies have spoken against me;","and they that watched my soul have consulted together,"]},{"v":11,"lines":["Saying:","God hath forsaken him:","pursue and take him, for there is none to deliver him."]},{"v":12,"lines":["O God, be not thou far from me:","O my God, make haste to my help."]},{"v":13,"lines":["Let them be confounded and come to nothing that detract my soul;","let them be covered with confusion and shame that seek my hurt."]},{"v":14,"lines":["But I will always hope;","and will add to all thy praise."]},{"v":15,"lines":["My mouth shall shew forth thy justice;","thy salvation all the day long. Because I have not known learning,"]},{"v":16,"lines":["I will enter into the powers of the Lord:","O Lord, I will be mindful of thy justice alone."]},{"v":17,"lines":["Thou hast taught me, O God, from my youth:","and till now I will declare thy wonderful works."]},{"v":18,"lines":["And unto old age and grey hairs:","O God, forsake me not, Until I shew forth thy arm to all the generation that is to come:","Thy power,"]},{"v":19,"lines":["And thy justice, O God, even to the highest great things thou hast done:","O God, who is like to thee?"]},{"v":20,"lines":["How great troubles hast thou shewn me, many and grievous:","and turning thou hast brought me to life, and hast brought me back again from the depths of the earth:"]},{"v":21,"lines":["Thou hast multiplied thy magnificence;","and turning to me thou hast comforted me."]},{"v":22,"lines":["For I will also confess to thee thy truth with the instruments of psaltery:","O God, I will sing to thee with the harp, thou holy one of Israel."]},{"v":23,"lines":["My lips shall greatly rejoice, when I shall sing to thee;","and my soul which thou hast redeemed."]},{"v":24,"lines":["Yea and my tongue shall meditate on thy justice all the day;","when they shall be confounded and put to shame that seek evils to me."]}]},{"n":71,"incipit":"Deus, judicium","verses":[{"v":1,"lines":["A psalm on Solomon."],"title":true},{"v":2,"lines":["Give to the king thy judgment, O God, and to the king's son thy justice:","To judge thy people with justice, and thy poor with judgment."]},{"v":3,"lines":["Let the mountains receive peace for the people:","and the hills justice."]},{"v":4,"lines":["He shall judge the poor of the people, and he shall save the children of the poor:","and he shall humble the oppressor."]},{"v":5,"lines":["And he shall continue with the sun and before the moon, throughout all generations."]},{"v":6,"lines":["He shall come down like rain upon the fleece;","and as showers falling gently upon the earth."]},{"v":7,"lines":["In his days shall justice spring up, and abundance of peace, till the moon be taken away."]},{"v":8,"lines":["And he shall rule from sea to sea, and from the river unto the ends of the earth."]},{"v":9,"lines":["Before him the Ethiopians shall fall down:","and his enemies shall lick the ground."]},{"v":10,"lines":["The kings of Tharsis and the islands shall offer presents:","the kings of the Arabians and of Saba shall bring gifts:"]},{"v":11,"lines":["And all kings of the earth shall adore him:","all nations shall serve him."]},{"v":12,"lines":["For he shall deliver the poor from the mighty:","and the needy that had no helper."]},{"v":13,"lines":["He shall spare the poor and needy:","and he shall save the souls of the poor."]},{"v":14,"lines":["He shall redeem their souls from usuries and iniquity:","and their names shall be honourable in his sight."]},{"v":15,"lines":["And he shall live, and to him shall be given of the gold of Arabia, for him they shall always adore:","they shall bless him all the day."]},{"v":16,"lines":["And there shall be a firmament on the earth on the tops of mountains, above Libanus shall the fruit thereof be exalted:","and they of the city shall flourish like the grass of the earth."]},{"v":17,"lines":["Let his name be blessed for evermore:","his name continueth before the sun. And in him shall all the tribes of the earth be blessed:","all nations shall magnify him."]},{"v":18,"lines":["Blessed be the Lord, the God of Israel, who alone doth wonderful things."]},{"v":19,"lines":["And blessed be the name of his majesty for ever:","and the whole earth shall be filled with his majesty. So be it. So be it."]},{"v":20,"lines":["The praises of David, the son of Jesse, are ended."]}]},{"n":72,"incipit":"Quam bonus Israel!","verses":[{"v":1,"lines":["How good is God to Israel, to them that are of a right heart!"],"heading":"A psalm for Asaph."},{"v":2,"lines":["But my feet were almost moved;","my steps had well nigh slipped."]},{"v":3,"lines":["Because I had a zeal on occasion of the wicked, seeing the prosperity of sinners."]},{"v":4,"lines":["For there is no regard to their death, nor is there strength in their stripes."]},{"v":5,"lines":["They are not in the labour of men:","neither shall they be scourged like other men."]},{"v":6,"lines":["Therefore pride hath held them fast:","they are covered with their iniquity and their wickedness."]},{"v":7,"lines":["Their iniquity hath come forth, as it were from fatness:","they have passed into the affection of the heart."]},{"v":8,"lines":["They have thought and spoken wickedness:","they have spoken iniquity on high."]},{"v":9,"lines":["They have set their mouth against heaven:","and their tongue hath passed through the earth."]},{"v":10,"lines":["Therefore will my people return here and full days shall be found in them."]},{"v":11,"lines":["And they said:","How doth God know? and is there knowledge in the most High?"]},{"v":12,"lines":["Behold these are sinners;","and yet, abounding in the world they have obtained riches."]},{"v":13,"lines":["And I said:","Then have I in vain justified my heart, and washed my hands among the innocent."]},{"v":14,"lines":["And I have been scourged all the day;","and my chastisement hath been in the mornings."]},{"v":15,"lines":["If I said:","I will speak thus;","behold I should condemn the generation of thy children."]},{"v":16,"lines":["I studied that I might know this thing, it is a labour in my sight:"]},{"v":17,"lines":["Until I go into the sanctuary of God, and understand concerning their last ends."]},{"v":18,"lines":["But indeed for deceits thou hast put it to them:","when they were lifted up thou hast cast them down."]},{"v":19,"lines":["How are they brought to desolation? they have suddenly ceased to be:","they have perished by reason of their iniquity."]},{"v":20,"lines":["As the dream of them that awake, O Lord;","so in thy city thou shalt bring their image to nothing."]},{"v":21,"lines":["For my heart hath been inflamed, and my reins have been changed:"]},{"v":22,"lines":["And I am brought to nothing, and I knew not."]},{"v":23,"lines":["I am become as a beast before thee:","and I am always with thee."]},{"v":24,"lines":["Thou hast held me by my right hand;","and by thy will thou hast conducted me, and with thy glory thou hast received me."]},{"v":25,"lines":["For what have I in heaven? and besides thee what do I desire upon earth?"]},{"v":26,"lines":["For thee my flesh and my heart hath fainted away:","thou art the God of my heart, and the God that is my portion for ever."]},{"v":27,"lines":["For behold they that go far from thee shall perish:","thou hast destroyed all them that are disloyal to thee."]},{"v":28,"lines":["But it is good for me to adhere to my God, to put my hope in the Lord God:","That I may declare all thy praises, in the gates of the daughter of Sion."]}]},{"n":73,"incipit":"Ut quid, Deus?","verses":[{"v":1,"lines":["O God, why hast thou cast us off unto the end:","why is thy wrath enkindled against the sheep of thy pasture?"],"heading":"Understanding for Asaph."},{"v":2,"lines":["Remember thy congregation, which thou hast possessed from the beginning. The sceptre of thy inheritance which thou hast redeemed:","mount Sion in which thou hast dwelt."]},{"v":3,"lines":["Lift up thy hands against their pride unto the end;","see what things the enemy hath done wickedly in the sanctuary."]},{"v":4,"lines":["And they that hate thee have made their boasts, in the midst of thy solemnity. They have set up their ensigns for signs,"]},{"v":5,"lines":["And they knew not both in the going out and on the highest top. As with axes in a wood of trees,"]},{"v":6,"lines":["They have cut down at once the gates thereof, with axe and hatchet they have brought it down."]},{"v":7,"lines":["They have set fire to thy sanctuary:","they have defiled the dwelling place of thy name on the earth."]},{"v":8,"lines":["They said in their heart, the whole kindred of them together:","Let us abolish all the festival days of God from the land."]},{"v":9,"lines":["Our signs we have not seen, there is now no prophet:","and he will know us no more."]},{"v":10,"lines":["How long, O God, shall the enemy reproach:","is the adversary to provoke thy name for ever?"]},{"v":11,"lines":["Why dost thou turn away thy hand:","and thy right hand out of the midst of thy bosom for ever?"]},{"v":12,"lines":["But God is our king before ages:","he hath wrought salvation in the midst of the earth."]},{"v":13,"lines":["Thou by thy strength didst make the sea firm:","thou didst crush the heads of the dragons in the waters."]},{"v":14,"lines":["Thou hast broken the heads of the dragon:","thou hast given him to be meat for the people of the Ethiopians."]},{"v":15,"lines":["Thou hast broken up the fountains and the torrents:","thou hast dried up the Ethan rivers."]},{"v":16,"lines":["Thine is the day, and thine is the night:","thou hast made the morning light and the sun."]},{"v":17,"lines":["Thou hast made all the borders of the earth:","the summer and the spring were formed by thee."]},{"v":18,"lines":["Remember this, the enemy hath reproached the Lord:","and a foolish people hath provoked thy name."]},{"v":19,"lines":["Deliver not up to beasts the souls that confess to thee:","and forget not to the end the souls of thy poor."]},{"v":20,"lines":["Have regard to thy covenant:","for they that are the obscure of the earth have been filled with dwellings of iniquity."]},{"v":21,"lines":["Let not the humble be turned away with confusion:","the poor and needy shall praise thy name."]},{"v":22,"lines":["Arise, O God, judge thy own cause:","remember thy reproaches with which the foolish man hath reproached thee all the day."]},{"v":23,"lines":["Forget not the voices of thy enemies:","the pride of them that hate thee ascendeth continually."]}]},{"n":74,"incipit":"Confitebimur tibi","verses":[{"v":1,"lines":["Unto the end, corrupt not, a psalm of a canticle for Asaph."],"title":true},{"v":2,"lines":["We will praise thee, O God:","we will praise, and we will call upon thy name. We will relate thy wondrous works:"]},{"v":3,"lines":["When I shall take a time, I will judge justices."]},{"v":4,"lines":["The earth is melted, and all that dwell therein:","I have established the pillars thereof."]},{"v":5,"lines":["I said to the wicked:","Do not act wickedly:","and to the sinners:","Lift not up the horn."]},{"v":6,"lines":["Lift not up your horn on high:","speak not iniquity against God."]},{"v":7,"lines":["For neither from the east, nor from the west, nor from the desert hills:"]},{"v":8,"lines":["For God is the judge. One he putteth down, and another he lifteth up:"]},{"v":9,"lines":["For in the hand of the Lord there is a cup of strong wine full of mixture. And he hath poured it out from this to that:","but the dregs thereof are not emptied:","all the sinners of the earth shall drink."]},{"v":10,"lines":["But I will declare for ever:","I will sing to the God of Jacob."]},{"v":11,"lines":["And I will break all the horns of sinners:","but the horns of the just shall be exalted."]}]},{"n":75,"incipit":"Notus in Judaea","verses":[{"v":1,"lines":["Unto the end, in praises, a psalm for Asaph: a canticle to the Assyrians."],"title":true},{"v":2,"lines":["In Judea God is known:","his name is great in Israel."]},{"v":3,"lines":["And his place is in peace:","and his abode in Sion:"]},{"v":4,"lines":["There hath he broken the powers of bows, the shield, the sword, and the battle."]},{"v":5,"lines":["Thou enlightenest wonderfully from the everlasting hills."]},{"v":6,"lines":["All the foolish of heart were troubled. They have slept their sleep;","and all the men of riches have found nothing in their hands."]},{"v":7,"lines":["At thy rebuke, O God of Jacob, they have all slumbered that mounted on horseback."]},{"v":8,"lines":["Thou art terrible, and who shall resist thee? from that time thy wrath."]},{"v":9,"lines":["Thou hast caused judgment to be heard from heaven:","the earth trembled and was still,"]},{"v":10,"lines":["When God arose in judgment, to save all the meek of the earth."]},{"v":11,"lines":["For the thought of man shall give praise to thee:","and the remainders of the thought shall keep holiday to thee."]},{"v":12,"lines":["Vow ye, and pay to the Lord your God:","all you that are round about him bring presents. To him that is terrible,"]},{"v":13,"lines":["Even to him who taketh away the spirit of princes:","to the terrible with the kings of the earth."]}]},{"n":76,"incipit":"Voce mea ad Dominum","verses":[{"v":1,"lines":["Unto the end, for Idithun, a psalm of Asaph."],"title":true},{"v":2,"lines":["I cried to the Lord with my voice;","to God with my voice, and he gave ear to me."]},{"v":3,"lines":["In the day of my trouble I sought God, with my hands lifted up to him in the night, and I was not deceived. My soul refused to be comforted:"]},{"v":4,"lines":["I remembered God, and was delighted, and was exercised, and my spirit swooned away."]},{"v":5,"lines":["My eyes prevented the watches:","I was troubled, and I spoke not."]},{"v":6,"lines":["I thought upon the days of old:","and I had in my mind the eternal years."]},{"v":7,"lines":["And I meditated in the night with my own heart:","and I was exercised and I swept my spirit."]},{"v":8,"lines":["Will God then cast off for ever? or will he never be more favourable again?"]},{"v":9,"lines":["Or will he cut off his mercy for ever, from generation to generation?"]},{"v":10,"lines":["Or will God forget to shew mercy? or will he in his anger shut up his mercies?"]},{"v":11,"lines":["And I said, Now have I begun:","this is the change of the right hand of the most High."]},{"v":12,"lines":["I remembered the works of the Lord:","for I will be mindful of thy wonders from the beginning."]},{"v":13,"lines":["And I will meditate on all thy works:","and will be employed in thy inventions."]},{"v":14,"lines":["Thy way, O God, is in the holy place:","who is the great God like our God?"]},{"v":15,"lines":["Thou art the God that dost wonders. Thou hast made thy power known among the nations:"]},{"v":16,"lines":["With thy arm thou hast redeemed thy people the children of Jacob and of Joseph."]},{"v":17,"lines":["The waters saw thee, O God, the waters saw thee:","and they were afraid, and the depths were troubled."]},{"v":18,"lines":["Great was the noise of the waters:","the clouds sent out a sound. For thy arrows pass:"]},{"v":19,"lines":["The voice of thy thunder in a wheel. Thy lightnings enlightened the world:","the earth shook and trembled."]},{"v":20,"lines":["Thy way is in the sea, and thy paths in many waters:","and thy footsteps shall not be known."]},{"v":21,"lines":["Thou hast conducted thy people like sheep, by the hand of Moses and Aaron."]}]},{"n":77,"incipit":"Attendite, popule","verses":[{"v":1,"lines":["Attend, O my people, to my law:","incline your ears to the words of my mouth."],"heading":"Understanding for Asaph."},{"v":2,"lines":["I will open my mouth in parables:","I will utter propositions from the beginning."]},{"v":3,"lines":["How great things have we heard and known, and our fathers have told us."]},{"v":4,"lines":["They have not been hidden from their children, in another generation. Declaring the praises of the Lord, and his powers, and his wonders which he hath done."]},{"v":5,"lines":["And he set up a testimony in Jacob:","and made a law in Israel. How great things he commanded our fathers, that they should make the same known to their children:"]},{"v":6,"lines":["That another generation might know them. The children that should be born and should rise up, and declare them to their children."]},{"v":7,"lines":["That they may put their hope in God and may not forget the works of God:","and may seek his commandments."]},{"v":8,"lines":["That they may not become like their fathers, a perverse and exasperating generation. A generation that set not their heart aright:","and whose spirit was not faithful to God."]},{"v":9,"lines":["The sons of Ephraim who bend and shoot with the bow:","they have turned back in the day of battle."]},{"v":10,"lines":["They kept not the covenant of God:","and in his law they would not walk."]},{"v":11,"lines":["And they forgot his benefits, and his wonders that he had shewn them."]},{"v":12,"lines":["Wonderful things did he do in the sight of their fathers, in the land of Egypt, in the field of Tanis."]},{"v":13,"lines":["He divided the sea and brought them through:","and he made the waters to stand as in a vessel."]},{"v":14,"lines":["And he conducted them with a cloud by day:","and all the night with a light of fire."]},{"v":15,"lines":["He struck the rock in the wilderness:","and gave them to drink, as out of the great deep."]},{"v":16,"lines":["He brought forth water out of the rock:","and made streams run down as rivers."]},{"v":17,"lines":["And they added yet more sin against him:","they provoked the most High to wrath in the place without water."]},{"v":18,"lines":["And they tempted God in their hearts, by asking meat for their desires."]},{"v":19,"lines":["And they spoke ill of God:","they said:","Can God furnish a table in the wilderness?"]},{"v":20,"lines":["Because he struck the rock, and the waters gushed out, and the streams overflowed. Can he also give bread, or provide a table for his people?"]},{"v":21,"lines":["Therefore the Lord heard, and was angry:","and a fire was kindled against Jacob, and wrath came up against Israel."]},{"v":22,"lines":["Because they believed not in God:","and trusted not in his salvation."]},{"v":23,"lines":["And he had commanded the clouds from above, and had opened the doors of heaven."]},{"v":24,"lines":["And had rained down manna upon them to eat, and had given them the bread of heaven."]},{"v":25,"lines":["Man ate the bread of angels:","he sent them provisions in abundance."]},{"v":26,"lines":["He removed the south wind from heaven:","and by his power brought in the southwest wind."]},{"v":27,"lines":["And he rained upon them flesh as dust:","and feathered fowls like as the sand of the sea."]},{"v":28,"lines":["And they fell in the midst of their camp, round about their pavilions."]},{"v":29,"lines":["So they did eat, and were filled exceedingly, and he gave them their desire:"]},{"v":30,"lines":["They were not defrauded of that which they craved. As yet their meat was in their mouth:"]},{"v":31,"lines":["And the wrath of God came upon them. And he slew the fat ones amongst them, and brought down the chosen men of Israel."]},{"v":32,"lines":["In all these things they sinned still:","and they believed not for his wondrous works."]},{"v":33,"lines":["And their days were consumed in vanity, and their years in haste."]},{"v":34,"lines":["When he slew them, then they sought him:","and they returned, and came to him early in the morning."]},{"v":35,"lines":["And they remembered that God was their helper:","and the most high God their redeemer."]},{"v":36,"lines":["And they loved him with their mouth:","and with their tongue they lied unto him:"]},{"v":37,"lines":["But their heart was not right with him:","nor were they counted faithful in his covenant."]},{"v":38,"lines":["But he is merciful, and will forgive their sins:","and will not destroy them. And many a time did he turn away his anger:","and did not kindle all his wrath."]},{"v":39,"lines":["And he remembered that they are flesh:","a wind that goeth and returneth not."]},{"v":40,"lines":["How often did they provoke him in the desert:","and move him to wrath in the place without water?"]},{"v":41,"lines":["And they turned back and tempted God:","and grieved the holy one of Israel."]},{"v":42,"lines":["They remembered not his hand, in the day that he redeemed them from the hand of him that afflicted them:"]},{"v":43,"lines":["How he wrought his signs in Egypt, and his wonders in the field of Tanis."]},{"v":44,"lines":["And he turned their rivers into blood, and their showers that they might not drink."]},{"v":45,"lines":["He sent amongst them divers sores of flies, which devoured them:","and frogs which destroyed them."]},{"v":46,"lines":["And he gave up their fruits to the blast, and their labours to the locust."]},{"v":47,"lines":["And he destroyed their vineyards with hail, and their mulberry trees with hoarfrost."]},{"v":48,"lines":["And he gave up their cattle to the hail, and their stock to the fire."]},{"v":49,"lines":["And he sent upon them the wrath of his indignation:","indignation and wrath and trouble, which he sent by evil angels."]},{"v":50,"lines":["He made a way for a path to his anger:","he spared not their souls from death, and their cattle he shut up in death."]},{"v":51,"lines":["And he killed all the firstborn in the land of Egypt:","the firstfruits of all their labour in the tabernacles of Cham."]},{"v":52,"lines":["And he took away his own people as sheep:","and guided them in the wilderness like a flock."]},{"v":53,"lines":["And he brought them out in hope and they feared not:","and the sea overwhelmed their enemies."]},{"v":54,"lines":["And he brought them into the mountain of his sanctuary:","the mountain which his right hand had purchased. And he cast out the Gentiles before them:","and by lot divided to them their land by a line of distribution."]},{"v":55,"lines":["And he made the tribes of Israel to dwell in their tabernacles."]},{"v":56,"lines":["Yet they tempted, and provoked the most high God:","and they kept not his testimonies."]},{"v":57,"lines":["And they turned away, and kept not the covenant:","even like their fathers they were turned aside as a crooked bow."]},{"v":58,"lines":["They provoked him to anger on their hills:","and moved him to jealousy with their graven things."]},{"v":59,"lines":["God heard, and despised them, and he reduced Israel exceedingly as it were to nothing."]},{"v":60,"lines":["And he put away the tabernacle of Silo, his tabernacle where he dwelt among men."]},{"v":61,"lines":["And he delivered their strength into captivity:","and their beauty into the hands of the enemy."]},{"v":62,"lines":["And he shut up his people under the sword:","and he despised his inheritance."]},{"v":63,"lines":["Fire consumed their young men:","and their maidens were not lamented."]},{"v":64,"lines":["Their priests fell by the sword:","and their widows did not mourn."]},{"v":65,"lines":["And the Lord was awaked as one out of sleep, and like a mighty man that hath been surfeited with wine."]},{"v":66,"lines":["And he smote his enemies on the hinder parts:","he put them to an everlasting reproach."]},{"v":67,"lines":["And he rejected the tabernacle of Joseph:","and chose not the tribe of Ephraim:"]},{"v":68,"lines":["But he chose the tribe of Juda, mount Sion which he loved."]},{"v":69,"lines":["And he built his sanctuary as of unicorns, in the land which he founded for ever."]},{"v":70,"lines":["And he chose his servant David, and took him from the flocks of sheep:","he brought him from following the ewes great with young,"]},{"v":71,"lines":["To feed Jacob his servant and Israel his inheritance."]},{"v":72,"lines":["And he fed them in the innocence of his heart:","and conducted them by the skillfulness of his hands."]}]},{"n":78,"incipit":"Deus, venerunt","verses":[{"v":1,"lines":["O God, the heathens are come into thy inheritance, they have defiled thy holy temple:","they have made Jerusalem as a place to keep fruit."],"heading":"A psalm for Asaph."},{"v":2,"lines":["They have given the dead bodies of thy servants to be meat for the fowls of the air:","the flesh of thy saints for the beasts of the earth."]},{"v":3,"lines":["They have poured out their blood as water, round about Jerusalem and there was none to bury them."]},{"v":4,"lines":["We are become a reproach to our neighbours:","a scorn and derision to them that are round about us."]},{"v":5,"lines":["How long, O Lord, wilt thou be angry for ever:","shall thy zeal be kindled like a fire?"]},{"v":6,"lines":["Pour out thy wrath upon the nations that have not known thee:","and upon the kingdoms that have not called upon thy name."]},{"v":7,"lines":["Because they have devoured Jacob;","and have laid waste his place."]},{"v":8,"lines":["Remember not our former iniquities:","let thy mercies speedily prevent us, for we are become exceeding poor."]},{"v":9,"lines":["Help us, O God, our saviour:","and for the glory of thy name, O Lord, deliver us:","and forgive us our sins for thy name's sake:"]},{"v":10,"lines":["Lest they should say among the Gentiles:","Where is their God? And let him be made known among the nations before our eyes, By the revenging the blood of thy servants, which hath been shed:"]},{"v":11,"lines":["Let the sighing of the prisoners come in before thee. According to the greatness of thy arm, take possession of the children of them that have been put to death."]},{"v":12,"lines":["And render to our neighbours sevenfold in their bosom:","the reproach wherewith they have reproached thee, O Lord."]},{"v":13,"lines":["But we thy people, and the sheep of thy pasture, will give thanks to thee for ever. We will shew forth thy praise, unto generation and generation."]}]},{"n":79,"incipit":"Qui regis Israel","verses":[{"v":1,"lines":["Unto the end, for them that shall be changed, a testimony for Asaph, a psalm."],"title":true},{"v":2,"lines":["Give ear, O thou that rulest Israel:","thou that leadest Joseph like a sheep. Thou that sittest upon the cherubims, shine forth"]},{"v":3,"lines":["Before Ephraim, Benjamin, and Manasses. Stir up thy might, and come to save us."]},{"v":4,"lines":["Convert us, O God:","and shew us thy face, and we shall be saved."]},{"v":5,"lines":["O Lord God of hosts, how long wilt thou be angry against the prayer of thy servant?"]},{"v":6,"lines":["How long wilt thou feed us with the bread of tears:","and give us for our drink tears in measure?"]},{"v":7,"lines":["Thou hast made us to be a contradiction to our neighbours:","and our enemies have scoffed at us."]},{"v":8,"lines":["O God of hosts, convert us:","and shew thy face, and we shall be saved."]},{"v":9,"lines":["Thou hast brought a vineyard out of Egypt:","thou hast cast out the Gentiles and planted it."]},{"v":10,"lines":["Thou wast the guide of its journey in its sight:","thou plantedst the roots thereof, and it filled the land."]},{"v":11,"lines":["The shadow of it covered the hills:","and the branches thereof the cedars of God."]},{"v":12,"lines":["It stretched forth its branches unto the sea, and its boughs unto the river."]},{"v":13,"lines":["Why hast thou broken down the hedge thereof, so that all they who pass by the way do pluck it?"]},{"v":14,"lines":["The boar out of the wood hath laid it waste:","and a singular wild beast hath devoured it."]},{"v":15,"lines":["Turn again, O God of hosts, look down from heaven, and see, and visit this vineyard:"]},{"v":16,"lines":["And perfect the same which thy right hand hath planted:","and upon the son of man whom thou hast confirmed for thyself."]},{"v":17,"lines":["Things set on fire and dug down shall perish at the rebuke of thy countenance."]},{"v":18,"lines":["Let thy hand be upon the man of thy right hand:","and upon the son of man whom thou hast confirmed for thyself."]},{"v":19,"lines":["And we depart not from thee, thou shalt quicken us:","and we will call upon thy name."]},{"v":20,"lines":["O Lord God of hosts, convert us and shew thy face, and we shall be saved."]}]},{"n":80,"incipit":"Exsultate Deo","verses":[{"v":1,"lines":["Unto the end, for the winepresses, a psalm for Asaph himself."],"title":true},{"v":2,"lines":["Rejoice to God our helper:","sing aloud to the God of Jacob."]},{"v":3,"lines":["Take a psalm, and bring hither the timbrel:","the pleasant psaltery with the harp."]},{"v":4,"lines":["Blow up the trumpet on the new moon, on the noted day of your solemnity."]},{"v":5,"lines":["For it is a commandment in Israel, and a judgment to the God of Jacob."]},{"v":6,"lines":["He ordained it for a testimony in Joseph, when he came out of the land of Egypt:","he heard a tongue which he knew not."]},{"v":7,"lines":["He removed his back from the burdens:","his hands had served in baskets."]},{"v":8,"lines":["Thou calledst upon me in affliction, and I delivered thee:","I heard thee in the secret place of tempest:","I proved thee at the waters of contradiction."]},{"v":9,"lines":["Hear, O my people, and I will testify to thee:","O Israel, if thou wilt hearken to me,"]},{"v":10,"lines":["There shall be no new god in thee:","neither shalt thou adore a strange god."]},{"v":11,"lines":["For I am the Lord thy God, who brought thee out of the land of Egypt:","open thy mouth wide, and I will fill it."]},{"v":12,"lines":["But my people heard not my voice:","and Israel hearkened not to me."]},{"v":13,"lines":["So I let them go according to the desires of their heart:","they shall walk in their own inventions."]},{"v":14,"lines":["If my people had heard me:","if Israel had walked in my ways:"]},{"v":15,"lines":["I should soon have humbled their enemies, and laid my hand on them that troubled them."]},{"v":16,"lines":["The enemies of the Lord have lied to him:","and their time shall be for ever."]},{"v":17,"lines":["And he fed them with the fat of wheat, and filled them with honey out of the rock."]}]},{"n":81,"incipit":"Deus stetit","verses":[{"v":1,"lines":["God hath stood in the congregation of gods:","and being in the midst of them he judgeth gods."],"heading":"A psalm for Asaph."},{"v":2,"lines":["How long will you judge unjustly:","and accept the persons of the wicked?"]},{"v":3,"lines":["Judge for the needy and fatherless:","do justice to the humble and the poor."]},{"v":4,"lines":["Rescue the poor;","and deliver the needy out of the hand of the sinner."]},{"v":5,"lines":["They have not known nor understood:","they walk on in darkness:","all the foundations of the earth shall be moved."]},{"v":6,"lines":["I have said:","You are gods and all of you the sons of the most High."]},{"v":7,"lines":["But you like men shall die:","and shall fall like one of the princes."]},{"v":8,"lines":["Arise, O God, judge thou the earth:","for thou shalt inherit among all the nations."]}]},{"n":82,"incipit":"Deus, quis similis?","verses":[{"v":1,"lines":["A canticle of a psalm for Asaph."],"title":true},{"v":2,"lines":["O God, who shall be like to thee? hold not thy peace, neither be thou still, O God."]},{"v":3,"lines":["For lo, thy enemies have made a noise:","and they that hate thee have lifted up the head."]},{"v":4,"lines":["They have taken a malicious counsel against thy people, and have consulted against thy saints."]},{"v":5,"lines":["They have said:","Come and let us destroy them, so that they be not a nation:","and let the name of Israel be remembered no more."]},{"v":6,"lines":["For they have contrived with one consent:","they have made a covenant together against thee,"]},{"v":7,"lines":["The tabernacles of the Edomites, and the Ismahelites:","Moab, and the Agarens,"]},{"v":8,"lines":["Gebal, and Ammon and Amalec:","the Philistines, with the inhabitants of Tyre."]},{"v":9,"lines":["Yea, and the Assyrian also is joined with them:","they are come to the aid of the sons of Lot."]},{"v":10,"lines":["Do to them as thou didst to Madian and to Sisara:","as to Jabin at the brook of Cisson."]},{"v":11,"lines":["Who perished at Endor:","and became as dung for the earth."]},{"v":12,"lines":["Make their princes like Oreb, and Zeb, and Zebee, and Salmana. All their princes,"]},{"v":13,"lines":["Who have said:","Let us possess the sanctuary of God for an inheritance."]},{"v":14,"lines":["O my God, make them like a wheel;","and as stubble before the wind."]},{"v":15,"lines":["As fire which burneth the wood:","and as a flame burning mountains:"]},{"v":16,"lines":["So shalt thou pursue them with thy tempest:","and shalt trouble them in thy wrath."]},{"v":17,"lines":["Fill their faces with shame;","and they shall seek thy name, O Lord."]},{"v":18,"lines":["Let them be ashamed and troubled for ever and ever:","and let them be confounded and perish."]},{"v":19,"lines":["And let them know that the Lord is thy name:","thou alone art the most High over all the earth."]}]},{"n":83,"incipit":"Quam dilecta!","verses":[{"v":1,"lines":["Unto the end, for the winepresses, a psalm for the sons of Core."],"title":true},{"v":2,"lines":["How lovely are thy tabernacles, O Lord of hosts!"]},{"v":3,"lines":["My soul longeth and fainteth for the courts of the Lord. My heart and my flesh have rejoiced in the living God."]},{"v":4,"lines":["For the sparrow hath found herself a house, and the turtle a nest for herself where she may lay her young ones:","Thy altars, O Lord of hosts, my king and my God."]},{"v":5,"lines":["Blessed are they that dwell in thy house, O Lord:","they shall praise thee for ever and ever."]},{"v":6,"lines":["Blessed is the man whose help is from thee:","in his heart he hath disposed to ascend by steps,"]},{"v":7,"lines":["In the vale of tears, in the place which he hath set."]},{"v":8,"lines":["For the lawgiver shall give a blessing, they shall go from virtue to virtue:","the God of gods shall be seen in Sion."]},{"v":9,"lines":["O Lord God of hosts, hear my prayer:","give ear, O God of Jacob."]},{"v":10,"lines":["Behold, O God our protector:","and look on the face of thy Christ."]},{"v":11,"lines":["For better is one day in thy courts above thousands. I have chosen to be an abject in the house of my God, rather than to dwell in the tabernacles of sinners."]},{"v":12,"lines":["For God loveth mercy and truth:","the Lord will give grace and glory."]},{"v":13,"lines":["He will not deprive of good things them that walk in innocence:","O Lord of hosts, blessed is the man that trusteth in thee."]}]},{"n":84,"incipit":"Benedixisti, Domine","verses":[{"v":1,"lines":["Unto the end, for the sons of Core, a psalm."],"title":true},{"v":2,"lines":["Lord, thou hast blessed thy land:","thou hast turned away the captivity of Jacob."]},{"v":3,"lines":["Thou hast forgiven the iniquity of thy people:","thou hast covered all their sins."]},{"v":4,"lines":["Thou hast mitigated all thy anger:","thou hast turned away from the wrath of thy indignation."]},{"v":5,"lines":["Convert us, O God our saviour:","and turn off thy anger from us."]},{"v":6,"lines":["Wilt thou be angry with us for ever:","or wilt thou extend thy wrath from generation to generation?"]},{"v":7,"lines":["Thou wilt turn, O God, and bring us to life:","and thy people shall rejoice in thee."]},{"v":8,"lines":["Shew us, O Lord, thy mercy;","and grant us thy salvation."]},{"v":9,"lines":["I will hear what the Lord God will speak in me:","for he will speak peace unto his people:","And unto his saints:","and unto them that are converted to the heart."]},{"v":10,"lines":["Surely his salvation is near to them that fear him:","that glory may dwell in our land."]},{"v":11,"lines":["Mercy and truth have met each other:","justice and peace have kissed."]},{"v":12,"lines":["Truth is sprung out of the earth:","and justice hath looked down from heaven."]},{"v":13,"lines":["For the Lord will give goodness:","and our earth shall yield her fruit."]},{"v":14,"lines":["Justice shall walk before him:","and shall set his steps in the way."]}]},{"n":85,"incipit":"Inclina, Domine","verses":[{"v":1,"lines":["Incline thy ear, O Lord, and hear me:","for I am needy and poor."],"heading":"A prayer for David himself."},{"v":2,"lines":["Preserve my soul, for I am holy:","save thy servant, O my God, that trusteth in thee."]},{"v":3,"lines":["Have mercy on me, O Lord, for I have cried to thee all the day."]},{"v":4,"lines":["Give joy to the soul of thy servant, for to thee, O Lord, I have lifted up my soul."]},{"v":5,"lines":["For thou, O Lord, art sweet and mild:","and plenteous in mercy to all that call upon thee."]},{"v":6,"lines":["Give ear, O Lord, to my prayer:","and attend to the voice of my petition."]},{"v":7,"lines":["I have called upon thee in the day of my trouble:","because thou hast heard me."]},{"v":8,"lines":["There is none among the gods like unto thee, O Lord:","and there is none according to thy works."]},{"v":9,"lines":["All the nations thou hast made shall come and adore before thee, O Lord:","and they shall glorify thy name."]},{"v":10,"lines":["For thou art great and dost wonderful things:","thou art God alone."]},{"v":11,"lines":["Conduct me, O Lord, in thy way, and I will walk in thy truth:","let my heart rejoice that it may fear thy name."]},{"v":12,"lines":["I will praise thee, O Lord my God, with my whole heart, and I will glorify thy name for ever:"]},{"v":13,"lines":["For thy mercy is great towards me:","and thou hast delivered my soul out of the lower hell."]},{"v":14,"lines":["O God, the wicked are risen up against me, and the assembly of the mighty have sought my soul:","and they have not set thee before their eyes."]},{"v":15,"lines":["And thou, O Lord, art a God of compassion, and merciful, patient, and of much mercy, and true."]},{"v":16,"lines":["O look upon me, and have mercy on me:","give thy command to thy servant, and save the son of thy handmaid."]},{"v":17,"lines":["Shew me a token for good:","that they who hate me may see, and be confounded, because thou, O Lord, hast helped me and hast comforted me."]}]},{"n":86,"incipit":"Fundamenta ejus","verses":[{"v":1,"lines":["The foundations thereof are in the holy mountains :"],"heading":"For the sons of Core, a psalm of a canticle."},{"v":2,"lines":["The Lord loveth the gates of Sion above all the tabernacles of Jacob."]},{"v":3,"lines":["Glorious things are said of thee, O city of God."]},{"v":4,"lines":["I will be mindful of Rahab and of Babylon knowing me. Behold the foreigners, and Tyre, and the people of the Ethiopians, these were there."]},{"v":5,"lines":["Shall not Sion say:","This man and that man is born in her? and the Highest himself hath founded her."]},{"v":6,"lines":["The Lord shall tell in his writings of peoples and of princes, of them that have been in her."]},{"v":7,"lines":["The dwelling in thee is as it were of all rejoicing."]}]},{"n":87,"incipit":"Domine, Deus","verses":[{"v":1,"lines":["A canticle of a psalm for the sons of Core: unto the end, for Maheleth, to answer understanding of Eman the Ezrahite."],"title":true},{"v":2,"lines":["O Lord, the God of my salvation:","I have cried in the day, and in the night before thee."]},{"v":3,"lines":["Let my prayer come in before thee:","incline thy ear to my petition."]},{"v":4,"lines":["For my soul is filled with evils:","and my life hath drawn nigh to hell."]},{"v":5,"lines":["I am counted among them that go down to the pit:","I am become as a man without help,"]},{"v":6,"lines":["Free among the dead. Like the slain sleeping in the sepulchres, whom thou rememberest no more:","and they are cast off from thy hand."]},{"v":7,"lines":["They have laid me in the lower pit:","in the dark places, and in the shadow of death."]},{"v":8,"lines":["Thy wrath is strong over me:","and all thy waves thou hast brought in upon me."]},{"v":9,"lines":["Thou hast put away my acquaintance far from me:","they have set me an abomination to themselves. I was delivered up, and came not forth:"]},{"v":10,"lines":["My eyes languished through poverty. All the day I cried to thee, O Lord:","I stretched out my hands to thee."]},{"v":11,"lines":["Wilt thou shew wonders to the dead? or shall physicians raise to life, and give praise to thee?"]},{"v":12,"lines":["Shall any one in the sepulchre declare thy mercy:","and thy truth in destruction?"]},{"v":13,"lines":["Shall thy wonders be known in the dark;","and thy justice in the land of forgetfulness?"]},{"v":14,"lines":["But I, O Lord, have cried to thee:","and in the morning my prayer shall prevent thee."]},{"v":15,"lines":["Lord, why castest thou off my prayer:","why turnest thou away thy face from me?"]},{"v":16,"lines":["I am poor, and in labours from my youth:","and being exalted have been humbled and troubled."]},{"v":17,"lines":["Thy wrath hath come upon me:","and thy terrors have troubled me."]},{"v":18,"lines":["They have come round about me like water all the day:","they have compassed me about together."]},{"v":19,"lines":["Friend and neighbour thou hast put far from me:","and my acquaintance, because of misery."]}]},{"n":88,"incipit":"Misericordias Domini","verses":[{"v":1,"lines":["Of understanding, for Ethan the Ezrahite."],"title":true},{"v":2,"lines":["The mercies of the Lord I will sing for ever. I will shew forth thy truth with my mouth to generation and generation."]},{"v":3,"lines":["For thou hast said:","Mercy shall be built up for ever in the heavens:","thy truth shall be prepared in them."]},{"v":4,"lines":["I have made a covenant with my elect:","I have sworn to David my servant:"]},{"v":5,"lines":["Thy seed will I settle for ever. And I will build up thy throne unto generation and generation."]},{"v":6,"lines":["The heavens shall confess thy wonders, O Lord:","and thy truth in the church of the saints."]},{"v":7,"lines":["For who in the clouds can be compared to the Lord:","or who among the sons of God shall be like to God?"]},{"v":8,"lines":["God, who is glorified in the assembly of the saints:","great and terrible above all them that are about him."]},{"v":9,"lines":["O Lord God of hosts, who is like to thee? thou art mighty, O Lord, and thy truth is round about thee."]},{"v":10,"lines":["Thou rulest the power of the sea:","and appeasest the motion of the waves thereof."]},{"v":11,"lines":["Thou hast humbled the proud one, as one that is slain:","with the arm of thy strength thou hast scattered thy enemies."]},{"v":12,"lines":["Thine are the heavens, and thine is the earth:","the world and the fulness thereof thou hast founded:"]},{"v":13,"lines":["The north and the sea thou hast created. Thabor and Hermon shall rejoice in thy name:"]},{"v":14,"lines":["Thy arm is with might. Let thy hand be strengthened, and thy right hand exalted:"]},{"v":15,"lines":["Justice and judgment are the preparation of thy throne. Mercy and truth shall go before thy face:"]},{"v":16,"lines":["Blessed is the people that knoweth jubilation. They shall walk, O Lord, in the light of thy countenance:"]},{"v":17,"lines":["And in thy name they shall rejoice all the day, and in thy justice they shall be exalted."]},{"v":18,"lines":["For thou art the glory of their strength:","and in thy good pleasure shall our horn be exalted."]},{"v":19,"lines":["For our protection is of the Lord, and of our king the holy one of Israel."]},{"v":20,"lines":["Then thou spokest in a vision to thy saints, and saidst:","I have laid help upon one that is mighty, and have exalted one chosen out of my people."]},{"v":21,"lines":["I have found David my servant:","with my holy oil I have anointed him."]},{"v":22,"lines":["For my hand shall help him:","and my arm shall strengthen him."]},{"v":23,"lines":["The enemy shall have no advantage over him:","nor the son of iniquity have power to hurt him."]},{"v":24,"lines":["And I will cut down his enemies before his face;","and them that hate him I will put to flight."]},{"v":25,"lines":["And my truth and my mercy shall be with him:","and in my name shall his horn be exalted."]},{"v":26,"lines":["And I will set his hand in the sea;","and his right hand in the rivers."]},{"v":27,"lines":["He shall cry out to me:","Thou art my father:","my God, and the support of my salvation."]},{"v":28,"lines":["And I will make him my firstborn, high above the kings of the earth."]},{"v":29,"lines":["I will keep my mercy for him for ever:","and my covenant faithful to him."]},{"v":30,"lines":["And I will make his seed to endure for evermore:","and his throne as the days of heaven."]},{"v":31,"lines":["And if his children forsake my law, and walk not in my judgments:"]},{"v":32,"lines":["If they profane my justices:","and keep not my commandments:"]},{"v":33,"lines":["I will visit their iniquities with a rod and their sins with stripes."]},{"v":34,"lines":["But my mercy I will not take away from him:","nor will I suffer my truth to fail."]},{"v":35,"lines":["Neither will I profane my covenant:","and the words that proceed from my mouth I will not make void."]},{"v":36,"lines":["Once have I sworn by my holiness:","I will not lie unto David:"]},{"v":37,"lines":["His seed shall endure for ever."]},{"v":38,"lines":["And his throne as the sun before me:","and as the moon perfect for ever, and a faithful witness in heaven."]},{"v":39,"lines":["But thou hast rejected and despised:","thou hast been angry with thy anointed."]},{"v":40,"lines":["Thou hast overthrown the covenant of thy servant:","thou hast profaned his sanctuary on the earth."]},{"v":41,"lines":["Thou hast broken down all his hedges:","thou hast made his strength fear."]},{"v":42,"lines":["All that pass by the way have robbed him:","he is become a reproach to his neighbours."]},{"v":43,"lines":["Thou hast set up the right hand of them that oppress him:","thou hast made all his enemies to rejoice."]},{"v":44,"lines":["Thou hast turned away the help of his sword;","and hast not assisted him in battle."]},{"v":45,"lines":["Thou hast made his purification to cease:","and thou hast cast his throne down to the ground."]},{"v":46,"lines":["Thou hast shortened the days of his time:","thou hast covered him with confusion."]},{"v":47,"lines":["How long, O Lord, turnest thou away unto the end? shall thy anger burn like fire?"]},{"v":48,"lines":["Remember what my substance is:","for hast thou made all the children of men in vain?"]},{"v":49,"lines":["Who is the man that shall live, and not see death:","that shall deliver his soul from the hand of hell?"]},{"v":50,"lines":["Lord, where are thy ancient mercies, according to what thou didst swear to David in thy truth?"]},{"v":51,"lines":["Be mindful, O Lord, of the reproach of thy servants (which I have held in my bosom) of many nations:"]},{"v":52,"lines":["Wherewith thy enemies have reproached, O Lord;","wherewith they have reproached the change of thy anointed."]},{"v":53,"lines":["Blessed be the Lord for evermore. So be it. So be it."]}]},{"n":89,"incipit":"Domine, refugium","verses":[{"v":1,"lines":["Lord, thou hast been our refuge from generation to generation."],"heading":"A prayer of Moses the man of God."},{"v":2,"lines":["Before the mountains were made, or the earth and the world was formed;","from eternity and to eternity thou art God."]},{"v":3,"lines":["Turn not man away to be brought low:","and thou hast said:","Be converted, O ye sons of men."]},{"v":4,"lines":["For a thousand years in thy sight are as yesterday, which is past. And as a watch in the night,"]},{"v":5,"lines":["Things that are counted nothing, shall their years be."]},{"v":6,"lines":["In the morning man shall grow up like grass;","in the morning he shall flourish and pass away:","in the evening he shall fall, grow dry, and wither."]},{"v":7,"lines":["For in thy wrath we have fainted away:","and are troubled in thy indignation."]},{"v":8,"lines":["Thou hast set our iniquities before thy eyes:","our life in the light of thy countenance."]},{"v":9,"lines":["For all our days are spent;","and in thy wrath we have fainted away. Our years shall be considered as a spider:"]},{"v":10,"lines":["The days of our years in them are threescore and ten years. But if in the strong they be fourscore years:","and what is more of them is labour and sorrow. For mildness is come upon us:","and we shall be corrected."]},{"v":11,"lines":["Who knoweth the power of thy anger, and for thy fear"]},{"v":12,"lines":["Can number thy wrath? So make thy right hand known:","and men learned in heart, in wisdom."]},{"v":13,"lines":["Return, O Lord, how long? and be entreated in favour of thy servants."]},{"v":14,"lines":["We are filled in the morning with thy mercy:","and we have rejoiced, and are delighted all our days."]},{"v":15,"lines":["We have rejoiced for the days in which thou hast humbled us:","for the years in which we have seen evils."]},{"v":16,"lines":["Look upon thy servants and upon their works:","and direct their children."]},{"v":17,"lines":["And let the brightness of the Lord our God be upon us:","and direct thou the works of our hands over us;","yea, the work of our hands do thou direct."]}]},{"n":90,"incipit":"Qui habitat","verses":[{"v":1,"lines":["He that dwelleth in the aid of the most High, shall abide under the protection of the God of Jacob."],"heading":"The praise of a canticle for David."},{"v":2,"lines":["He shall say to the Lord:","Thou art my protector, and my refuge:","my God, in him will I trust."]},{"v":3,"lines":["For he hath delivered me from the snare of the hunters:","and from the sharp word."]},{"v":4,"lines":["He will overshadow thee with his shoulders:","and under his wings thou shalt trust."]},{"v":5,"lines":["His truth shall compass thee with a shield:","thou shalt not be afraid of the terror of the night."]},{"v":6,"lines":["Of the arrow that flieth in the day, of the business that walketh about in the dark:","of invasion, or of the noonday devil."]},{"v":7,"lines":["A thousand shall fall at thy side, and ten thousand at thy right hand:","but it shall not come nigh thee."]},{"v":8,"lines":["But thou shalt consider with thy eyes:","and shalt see the reward of the wicked."]},{"v":9,"lines":["Because thou, O Lord, art my hope:","thou hast made the most High thy refuge."]},{"v":10,"lines":["There shall no evil come to thee:","nor shall the scourge come near thy dwelling."]},{"v":11,"lines":["For he hath given his angels charge over thee;","to keep thee in all thy ways."]},{"v":12,"lines":["In their hands they shall bear thee up:","lest thou dash thy foot against a stone."]},{"v":13,"lines":["Thou shalt walk upon the asp and the basilisk:","and thou shalt trample under foot the lion and the dragon."]},{"v":14,"lines":["Because he hoped in me I will deliver him:","I will protect him because he hath known my name."]},{"v":15,"lines":["He shall cry to me, and I will hear him:","I am with him in tribulation, I will deliver him, and I will glorify him."]},{"v":16,"lines":["I will fill him with length of days;","and I will shew him my salvation."]}]},{"n":91,"incipit":"Bonum est confiteri","verses":[{"v":1,"lines":["A psalm of a canticle on the sabbath day."],"title":true},{"v":2,"lines":["It is good to give praise to the Lord:","and to sing to thy name, O most High."]},{"v":3,"lines":["To shew forth thy mercy in the morning, and thy truth in the night:"]},{"v":4,"lines":["Upon an instrument of ten strings, upon the psaltery:","with a canticle upon the harp."]},{"v":5,"lines":["For thou hast given me, O Lord, a delight in thy doings:","and in the works of thy hands I shall rejoice."]},{"v":6,"lines":["O Lord, how great are thy works! thy thoughts are exceeding deep."]},{"v":7,"lines":["The senseless man shall not know:","nor will the fool understand these things."]},{"v":8,"lines":["When the wicked shall spring up as grass:","and all the workers of iniquity shall appear:","That they may perish for ever and ever:"]},{"v":9,"lines":["But thou, O Lord, art most high for evermore."]},{"v":10,"lines":["For behold thy enemies, O lord, for behold thy enemies shall perish:","and all the workers of iniquity shall be scattered."]},{"v":11,"lines":["But my horn shall be exalted like that of the unicorn:","and my old age in plentiful mercy."]},{"v":12,"lines":["My eye also hath looked down upon my enemies:","and my ear shall hear of the downfall of the malignant that rise up against me."]},{"v":13,"lines":["The just shall flourish like the palm tree:","he shall grow up like the cedar of Libanus."]},{"v":14,"lines":["They that are planted in the house of the Lord shall flourish in the courts of the house of our God."]},{"v":15,"lines":["They shall still increase in a fruitful old age:","and shall be well treated,"]},{"v":16,"lines":["That they may shew, That the Lord our God is righteous, and there is no iniquity in him."]}]},{"n":92,"incipit":"Dominus regnavit","verses":[{"v":1,"lines":["The Lord hath reigned, he is clothed with beauty:","the Lord is clothed with strength, and hath girded himself. For he hath established the world which shall not be moved."]},{"v":2,"lines":["Thy throne is prepared from of old:","thou art from everlasting."]},{"v":3,"lines":["The floods have lifted up, O Lord:","the floods have lifted up their voice. The floods have lifted up their waves,"]},{"v":4,"lines":["With the noise of many waters. Wonderful are the surges of the sea:","wonderful is the Lord on high."]},{"v":5,"lines":["Thy testimonies are become exceedingly credible:","holiness becometh thy house, O Lord, unto length of days."]}]},{"n":93,"incipit":"Deus ultionum","verses":[{"v":1,"lines":["The Lord is the God to whom revenge belongeth:","the God of revenge hath acted freely."]},{"v":2,"lines":["Lift up thyself, thou that judgest the earth:","render a reward to the proud."]},{"v":3,"lines":["How long shall sinners, O Lord:","how long shall sinners glory?"]},{"v":4,"lines":["Shall they utter, and speak iniquity:","shall all speak who work injustice?"]},{"v":5,"lines":["Thy people, O Lord, they have brought low:","and they have afflicted thy inheritance."]},{"v":6,"lines":["They have slain the widow and the stranger:","and they have murdered the fatherless."]},{"v":7,"lines":["And they have said:","The Lord shall not see:","neither shall the God of Jacob understand."]},{"v":8,"lines":["Understand, ye senseless among the people:","and, you fools, be wise at last."]},{"v":9,"lines":["He that planted the ear, shall he not hear? or he that formed the eye, doth he not consider?"]},{"v":10,"lines":["He that chastiseth nations, shall he not rebuke:","he that teacheth man knowledge?"]},{"v":11,"lines":["The Lord knoweth the thoughts of men, that they are vain."]},{"v":12,"lines":["Blessed is the man whom thou shalt instruct, O Lord:","and shalt teach him out of thy law."]},{"v":13,"lines":["That thou mayst give him rest from the evil days:","till a pit be dug for the wicked."]},{"v":14,"lines":["For the Lord will not cast off his people:","neither will he forsake his own inheritance."]},{"v":15,"lines":["Until justice be turned into judgment:","and they that are near it are all the upright in heart."]},{"v":16,"lines":["Who shall rise up for me against the evildoers? or who shall stand with me against the workers of iniquity?"]},{"v":17,"lines":["Unless the Lord had been my helper, my soul had almost dwelt in hell."]},{"v":18,"lines":["If I said:","My foot is moved:","thy mercy, O Lord, assisted me."]},{"v":19,"lines":["According to the multitude of my sorrows in my heart, thy comforts have given joy to my soul."]},{"v":20,"lines":["Doth the seat of iniquity stick to thee, who framest labour in commandment?"]},{"v":21,"lines":["They will hunt after the soul of the just, and will condemn innocent blood."]},{"v":22,"lines":["But the Lord is my refuge:","and my God the help of my hope."]},{"v":23,"lines":["And he will render them their iniquity:","and in their malice he will destroy them:","the Lord our God will destroy them."]}]},{"n":94,"incipit":"Venite, exultemus","verses":[{"v":1,"lines":["Come let us praise the Lord with joy:","let us joyfully sing to God our saviour."]},{"v":2,"lines":["Let us come before his presence with thanksgiving;","and make a joyful noise to him with psalms."]},{"v":3,"lines":["For the Lord is a great God, and a great King above all gods."]},{"v":4,"lines":["For in his hand are all the ends of the earth:","and the heights of the mountains are his."]},{"v":5,"lines":["For the sea is his, and he made it:","and his hands formed the dry land."]},{"v":6,"lines":["Come let us adore and fall down:","and weep before the Lord that made us."]},{"v":7,"lines":["For he is the Lord our God:","and we are the people of his pasture and the sheep of his hand."]},{"v":8,"lines":["Today if you shall hear his voice, harden not your hearts:"]},{"v":9,"lines":["As in the provocation, according to the day of temptation in the wilderness:","where your fathers tempted me, they proved me, and saw my works."]},{"v":10,"lines":["Forty years long was I offended with that generation, and I said:","These always err in heart."]},{"v":11,"lines":["And these men have not known my ways:","so I swore in my wrath that they shall not enter into my rest."]}]},{"n":95,"incipit":"Cantate Domino","verses":[{"v":1,"lines":["Sing ye to the Lord a new canticle:","sing to the Lord, all the earth."],"heading":"A canticle for David himself, when the house was built after the captivity."},{"v":2,"lines":["Sing ye to the Lord and bless his name:","shew forth his salvation from day to day."]},{"v":3,"lines":["Declare his glory among the Gentiles:","his wonders among all people."]},{"v":4,"lines":["For the Lord is great, and exceedingly to be praised:","he is to be feared above all gods."]},{"v":5,"lines":["For all the gods of the Gentiles are devils:","but the Lord made the heavens."]},{"v":6,"lines":["Praise and beauty are before him:","holiness and majesty in his sanctuary."]},{"v":7,"lines":["Bring ye to the Lord, O ye kindreds of the Gentiles, bring ye to the Lord glory and honour:"]},{"v":8,"lines":["Bring to the Lord glory unto his name. Bring up sacrifices, and come into his courts:"]},{"v":9,"lines":["Adore ye the Lord in his holy court. Let all the earth be moved at his presence."]},{"v":10,"lines":["Say ye among the Gentiles, the Lord hath reigned. For he hath corrected the world, which shall not be moved:","he will judge the people with justice."]},{"v":11,"lines":["Let the heavens rejoice, and let the earth be glad, let the sea be moved, and the fulness thereof:"]},{"v":12,"lines":["The fields and all things that are in them shall be joyful. Then shall all the trees of the woods rejoice"]},{"v":13,"lines":["Before the face of the Lord, because he cometh:","because he cometh to judge the earth. He shall judge the world with justice, and the people with his truth."]}]},{"n":96,"incipit":"Dominus regnavit","verses":[{"v":1,"lines":["The Lord hath reigned, let the earth rejoice:","let many islands be glad."],"heading":"For the same David, when his land was restored again to him."},{"v":2,"lines":["Clouds and darkness are round about him:","justice and judgment are the establishment of his throne."]},{"v":3,"lines":["A fire shall go before him, and shall burn his enemies round about."]},{"v":4,"lines":["His lightnings have shone forth to the world:","the earth saw and trembled."]},{"v":5,"lines":["The mountains melted like wax, at the presence of the Lord:","at the presence of the Lord of all the earth."]},{"v":6,"lines":["The heavens declared his justice:","and all people saw his glory."]},{"v":7,"lines":["Let them be all confounded that adore graven things, and that glory in their idols. Adore him, all you his angels:"]},{"v":8,"lines":["Sion heard, and was glad. And the daughters of Juda rejoiced, because of thy judgments, O Lord."]},{"v":9,"lines":["For thou art the most high Lord over all the earth:","thou art exalted exceedingly above all gods."]},{"v":10,"lines":["You that love the Lord, hate evil:","the Lord preserveth the souls of his saints, he will deliver them out of the hand of the sinner."]},{"v":11,"lines":["Light is risen to the just, and joy to the right of heart."]},{"v":12,"lines":["Rejoice, ye just, in the Lord:","and give praise to the remembrance of his holiness."]}]},{"n":97,"incipit":"Cantate Domino","verses":[{"v":1,"lines":["Sing ye to the Lord a new canticle:","because he hath done wonderful things. His right hand hath wrought for him salvation, and his arm is holy."],"heading":"A psalm for David himself."},{"v":2,"lines":["The Lord hath made known his salvation:","he hath revealed his justice in the sight of the Gentiles."]},{"v":3,"lines":["He hath remembered his mercy and his truth toward the house of Israel. All the ends of the earth have seen the salvation of our God."]},{"v":4,"lines":["Sing joyfully to God, all the earth;","make melody, rejoice and sing."]},{"v":5,"lines":["Sing praise to the Lord on the harp, on the harp, and with the voice of a psalm:"]},{"v":6,"lines":["With long trumpets, and sound of cornet. Make a joyful noise before the Lord our king:"]},{"v":7,"lines":["Let the sea be moved and the fulness thereof:","the world and they that dwell therein."]},{"v":8,"lines":["The rivers shall clap their hands, the mountains shall rejoice together"]},{"v":9,"lines":["At the presence of the Lord:","because he cometh to judge the earth. He shall judge the world with justice, and the people with equity."]}]},{"n":98,"incipit":"Dominus regnavit","verses":[{"v":1,"lines":["The Lord hath reigned, let the people be angry:","he that sitteth on the cherubims:","let the earth be moved."],"heading":"A psalm for David himself."},{"v":2,"lines":["The lord is great in Sion, and high above all people."]},{"v":3,"lines":["Let them give praise to thy great name:","for it is terrible and holy:"]},{"v":4,"lines":["And the king's honour loveth judgment. Thou hast prepared directions:","thou hast done judgment and justice in Jacob."]},{"v":5,"lines":["Exalt ye the Lord our God, and adore his footstool, for it is holy."]},{"v":6,"lines":["Moses and Aaron among his priests:","and Samuel among them that call upon his name. They called upon the Lord, and he heard them:"]},{"v":7,"lines":["He spoke to them in the pillar of the cloud. They kept his testimonies, and the commandment which he gave them."]},{"v":8,"lines":["Thou didst hear them, O Lord our God:","thou wast a merciful God to them, and taking vengeance on all their inventions."]},{"v":9,"lines":["Exalt ye the Lord our God, and adore at his holy mountain:","for the Lord our God is holy."]}]},{"n":99,"incipit":"Jubilate Deo","verses":[{"v":1,"lines":["A psalm of praise."],"title":true},{"v":2,"lines":["Sing joyfully to God, all the earth:","serve ye the Lord with gladness. Come in before his presence with exceeding great joy."]},{"v":3,"lines":["Know ye that the Lord he is God:","he made us, and not we ourselves. We are his people and the sheep of his pasture."]},{"v":4,"lines":["Go ye into his gates with praise, into his courts with hymns:","and give glory to him. Praise ye his name:"]},{"v":5,"lines":["For the Lord is sweet, his mercy endureth for ever, and his truth to generation and generation."]}]},{"n":100,"incipit":"Misericordiam et judicium","verses":[{"v":1,"lines":["Mercy and judgment I will sing to thee, O Lord:","I will sing,"],"heading":"A psalm for David himself."},{"v":2,"lines":["And I will understand in the unspotted way, when thou shalt come to me. I walked in the innocence of my heart, in the midst of my house."]},{"v":3,"lines":["I did not set before my eyes any unjust thing:","I hated the workers of iniquities."]},{"v":4,"lines":["The perverse heart did not cleave to me:","and the malignant, that turned aside from me, I would not know."]},{"v":5,"lines":["The man that in private detracted his neighbour, him did I persecute. With him that had a proud eye, and an unsatiable heart, I would not eat."]},{"v":6,"lines":["My eyes were upon the faithful of the earth, to sit with me:","the man that walked in the perfect way, he served me."]},{"v":7,"lines":["He that worketh pride shall not dwell in the midst of my house:","he that speaketh unjust things did not prosper before my eyes."]},{"v":8,"lines":["In the morning I put to death all the wicked of the land:","that I might cut off all the workers of iniquity from the city of the Lord."]}]},{"n":101,"incipit":"Domine, exaudi","verses":[{"v":1,"lines":["The prayer of the poor man, when he was anxious, and poured out his supplication before the Lord."],"title":true},{"v":2,"lines":["Hear, O Lord, my prayer:","and let my cry come to thee."]},{"v":3,"lines":["Turn not away thy face from me:","in the day when I am in trouble, incline thy ear to me. In what day soever I shall call upon thee, hear me speedily."]},{"v":4,"lines":["For my days are vanished like smoke, and my bones are grown dry like fuel for the fire."]},{"v":5,"lines":["I am smitten as grass, and my heart is withered:","because I forgot to eat my bread."]},{"v":6,"lines":["Through the voice of my groaning, my bone hath cleaved to my flesh."]},{"v":7,"lines":["I am become like to a pelican of the wilderness:","I am like a night raven in the house."]},{"v":8,"lines":["I have watched, and am become as a sparrow all alone on the housetop."]},{"v":9,"lines":["All the day long my enemies reproached me:","and they that praised me did swear against me."]},{"v":10,"lines":["For I did eat ashes like bread, and mingled my drink with weeping."]},{"v":11,"lines":["Because of thy anger and indignation:","for having lifted me up thou hast thrown me down."]},{"v":12,"lines":["My days have declined like a shadow, and I am withered like grass."]},{"v":13,"lines":["But thou, O Lord, endurest for ever:","and thy memorial to all generations."]},{"v":14,"lines":["Thou shalt arise and have mercy on Sion:","for it is time to have mercy on it, for the time is come."]},{"v":15,"lines":["For the stones thereof have pleased thy servants:","and they shall have pity on the earth thereof."]},{"v":16,"lines":["And the Gentiles shall fear thy name, O Lord, and all the kings of the earth thy glory."]},{"v":17,"lines":["For the Lord hath built up Sion:","and he shall be seen in his glory."]},{"v":18,"lines":["He hath had regard to the prayer of the humble:","and he hath not despised their petition."]},{"v":19,"lines":["Let these things be written unto another generation:","and the people that shall be created shall praise the Lord:"]},{"v":20,"lines":["Because he hath looked forth from his high sanctuary:","from heaven the Lord hath looked upon the earth."]},{"v":21,"lines":["That he might hear the groans of them that are in fetters:","that he might release the children of the slain:"]},{"v":22,"lines":["That they may declare the name of the Lord in Sion:","and his praise in Jerusalem;"]},{"v":23,"lines":["When the people assemble together, and kings, to serve the Lord."]},{"v":24,"lines":["He answered him in the way of his strength:","Declare unto me the fewness of my days."]},{"v":25,"lines":["Call me not away in the midst of my days:","thy years are unto generation and generation."]},{"v":26,"lines":["In the beginning, O Lord, thou foundedst the earth:","and the heavens are the works of thy hands."]},{"v":27,"lines":["They shall perish but thou remainest:","and all of them shall grow old like a garment:","And as a vesture thou shalt change them, and they shall be changed."]},{"v":28,"lines":["But thou art always the selfsame, and thy years shall not fail."]},{"v":29,"lines":["The children of thy servants shall continue and their seed shall be directed for ever."]}]},{"n":102,"incipit":"Benedic, anima mea","verses":[{"v":1,"lines":["Bless the Lord, O my soul:","and let all that is within me bless his holy name."],"heading":"For David himself."},{"v":2,"lines":["Bless the Lord, O my soul, and never forget all he hath done for thee."]},{"v":3,"lines":["Who forgiveth all thy iniquities:","who healeth all thy diseases."]},{"v":4,"lines":["Who redeemeth thy life from destruction:","who crowneth thee with mercy and compassion."]},{"v":5,"lines":["Who satisfieth thy desire with good things:","thy youth shall be renewed like the eagle's."]},{"v":6,"lines":["The Lord doth mercies, and judgment for all that suffer wrong."]},{"v":7,"lines":["He hath made his ways known to Moses:","his wills to the children of Israel."]},{"v":8,"lines":["The Lord is compassionate and merciful:","longsuffering and plenteous in mercy."]},{"v":9,"lines":["He will not always be angry:","nor will he threaten for ever."]},{"v":10,"lines":["He hath not dealt with us according to our sins:","nor rewarded us according to our iniquities."]},{"v":11,"lines":["For according to the height of the heaven above the earth:","he hath strengthened his mercy towards them that fear him."]},{"v":12,"lines":["As far as the east is from the west, so far hath he removed our iniquities from us."]},{"v":13,"lines":["As a father hath compassion on his children, so hath the Lord compassion on them that fear him:"]},{"v":14,"lines":["For he knoweth our frame. He remembereth that we are dust:"]},{"v":15,"lines":["Man's days are as grass, as the flower of the field so shall he flourish."]},{"v":16,"lines":["For the spirit shall pass in him, and he shall not be:","and he shall know his place no more."]},{"v":17,"lines":["But the mercy of the Lord is from eternity and unto eternity upon them that fear him:","And his justice unto children's children,"]},{"v":18,"lines":["To such as keep his covenant, And are mindful of his commandments to do them."]},{"v":19,"lines":["The lord hath prepared his throne in heaven:","and his kingdom shall rule over all."]},{"v":20,"lines":["Bless the Lord, all ye his angels:","you that are mighty in strength, and execute his word, hearkening to the voice of his orders."]},{"v":21,"lines":["Bless the Lord, all ye his hosts:","you ministers of his that do his will."]},{"v":22,"lines":["Bless the Lord, all his works:","in every place of his dominion, O my soul, bless thou the Lord."]}]},{"n":103,"incipit":"Benedic, anima mea","verses":[{"v":1,"lines":["Bless the Lord, O my soul:","O Lord my God, thou art exceedingly great. Thou hast put on praise and beauty:"],"heading":"For David himself."},{"v":2,"lines":["And art clothed with light as with a garment. Who stretchest out the heaven like a pavilion:"]},{"v":3,"lines":["Who coverest the higher rooms thereof with water. Who makest the clouds thy chariot:","who walkest upon the wings of the winds."]},{"v":4,"lines":["Who makest thy angels spirits:","and thy ministers a burning fire."]},{"v":5,"lines":["Who hast founded the earth upon its own bases:","it shall not be moved for ever and ever."]},{"v":6,"lines":["The deep like a garment is its clothing:","above the mountains shall the waters stand."]},{"v":7,"lines":["At thy rebuke they shall flee:","at the voice of thy thunder they shall fear."]},{"v":8,"lines":["The mountains ascend, and the plains descend into the place which thou hast founded for them."]},{"v":9,"lines":["Thou hast set a bound which they shall not pass over;","neither shall they return to cover the earth."]},{"v":10,"lines":["Thou sendest forth springs in the vales:","between the midst of the hills the waters shall pass."]},{"v":11,"lines":["All the beasts of the field shall drink:","the wild asses shall expect in their thirst."]},{"v":12,"lines":["Over them the birds of the air shall dwell:","from the midst of the rocks they shall give forth their voices."]},{"v":13,"lines":["Thou waterest the hills from thy upper rooms:","the earth shall be filled with the fruit of thy works:"]},{"v":14,"lines":["Bringing forth grass for cattle, and herb for the service of men. That thou mayst bring bread out of the earth:"]},{"v":15,"lines":["And that wine may cheer the heart of man. That he may make the face cheerful with oil:","and that bread may strengthen man's heart."]},{"v":16,"lines":["The trees of the field shall be filled, and the cedars of Libanus which he hath planted:"]},{"v":17,"lines":["There the sparrows shall make their nests. The highest of them is the house of the heron."]},{"v":18,"lines":["The high hills are a refuge for the harts, the rock for the irchins."]},{"v":19,"lines":["He hath made the moon for seasons:","the sun knoweth his going down."]},{"v":20,"lines":["Thou hast appointed darkness, and it is night:","in it shall all the beasts of the woods go about:"]},{"v":21,"lines":["The young lions roaring after their prey, and seeking their meat from God."]},{"v":22,"lines":["The sun ariseth, and they are gathered together:","and they shall lie down in their dens."]},{"v":23,"lines":["Man shall go forth to his work, and to his labour until the evening."]},{"v":24,"lines":["How great are thy works, O Lord? thou hast made all things in wisdom:","the earth is filled with thy riches."]},{"v":25,"lines":["So is this great sea, which stretcheth wide its arms:","there are creeping things without number:","Creatures little and great."]},{"v":26,"lines":["There the ships shall go. This sea dragon which thou hast formed to play therein."]},{"v":27,"lines":["All expect of thee that thou give them food in season."]},{"v":28,"lines":["What thou givest to them they shall gather up:","when thou openest thy hand, they shall all be filled with good."]},{"v":29,"lines":["But if thou turnest away thy face, they shall be troubled:","thou shalt take away their breath, and they shall fail, and shall return to their dust."]},{"v":30,"lines":["Thou shalt send forth thy spirit, and they shall be created:","and thou shalt renew the face of the earth."]},{"v":31,"lines":["May the glory of the Lord endure for ever:","the Lord shall rejoice in his works."]},{"v":32,"lines":["He looketh upon the earth, and maketh it tremble:","he toucheth the mountains, and they smoke."]},{"v":33,"lines":["I will sing to the Lord as long as I live:","I will sing praise to my God while I have my being."]},{"v":34,"lines":["Let my speech be acceptable to him:","but I will take delight in the Lord."]},{"v":35,"lines":["Let sinners be consumed out of the earth, and the unjust, so that they be no more:","O my soul, bless thou the Lord."]}]},{"n":104,"incipit":"Confitemini Domino","verses":[{"v":1,"lines":["Give glory to the Lord, and call upon his name:","declare his deeds among the Gentiles."]},{"v":2,"lines":["Sing to him, yea sing praises to him:","relate all his wondrous works."]},{"v":3,"lines":["Glory ye in his holy name:","let the heart of them rejoice that seek the Lord."]},{"v":4,"lines":["Seek ye the lord, and be strengthened:","seek his face evermore."]},{"v":5,"lines":["Remember his marvellous works which he hath done;","his wonders, and the judgments of his mouth."]},{"v":6,"lines":["O ye seed of Abraham his servant;","ye sons of Jacob his chosen."]},{"v":7,"lines":["He is the Lord our God:","his judgments are in all the earth."]},{"v":8,"lines":["He hath remembered his covenant for ever:","the word which he commanded to a thousand generations."]},{"v":9,"lines":["Which he made to Abraham;","and his oath to Isaac:"]},{"v":10,"lines":["And he appointed the same to Jacob for a law, and to Israel for an everlasting testament:"]},{"v":11,"lines":["Saying:","To thee will I give the land of Chanaan, the lot of your inheritance."]},{"v":12,"lines":["When they were but a small number:","yea very few, and sojourners therein:"]},{"v":13,"lines":["And they passed from nation to nation, and from one kingdom to another people."]},{"v":14,"lines":["He suffered no man to hurt them:","and he reproved kings for their sakes."]},{"v":15,"lines":["Touch ye not my anointed:","and do no evil to my prophets."]},{"v":16,"lines":["And he called a famine upon the land:","and he broke in pieces all the support of bread."]},{"v":17,"lines":["He sent a man before them:","Joseph, who was sold for a slave."]},{"v":18,"lines":["They humbled his feet in fetters:","the iron pierced his soul,"]},{"v":19,"lines":["Until his word came. The word of the Lord inflamed him."]},{"v":20,"lines":["The king sent, and he released him:","the ruler of the people, and he set him at liberty."]},{"v":21,"lines":["He made him master of his house, and ruler of all his possession."]},{"v":22,"lines":["That he might instruct his princes as himself, and teach his ancients wisdom."]},{"v":23,"lines":["And Israel went into Egypt:","and Jacob was a sojourner in the land of Cham."]},{"v":24,"lines":["And he increased his people exceedingly:","and strengthened them over their enemies."]},{"v":25,"lines":["He turned their heart to hate his people:","and to deal deceitfully with his servants."]},{"v":26,"lines":["He sent Moses his servant:","Aaron the man whom he had chosen."]},{"v":27,"lines":["He gave them power to shew his signs, and his wonders in the land of Cham."]},{"v":28,"lines":["He sent darkness, and made it obscure:","and grieved not his words."]},{"v":29,"lines":["He turned their waters into blood, and destroyed their fish."]},{"v":30,"lines":["Their land brought forth frogs, in the inner chambers of their kings."]},{"v":31,"lines":["He spoke, and there came divers sorts of flies and sciniphs in all their coasts."]},{"v":32,"lines":["He gave them hail for rain, a burning fire in the land."]},{"v":33,"lines":["And he destroyed their vineyards and their fig trees:","and he broke in pieces the trees of their coasts."]},{"v":34,"lines":["He spoke, and the locust came, and the bruchus, of which there was no number."]},{"v":35,"lines":["And they devoured all the grass in their land, and consumed all the fruit of their ground."]},{"v":36,"lines":["And he slew all the firstborn in their land:","the firstfruits of all their labour."]},{"v":37,"lines":["And he brought them out with silver and gold:","and there was not among their tribes one that was feeble."]},{"v":38,"lines":["Egypt was glad when they departed:","for the fear of them lay upon them."]},{"v":39,"lines":["He spread a cloud for their protection, and fire to give them light in the night."]},{"v":40,"lines":["They asked, and the quail came:","and he filled them with the bread of heaven."]},{"v":41,"lines":["He opened the rock, and waters flowed:","rivers ran down in the dry land."]},{"v":42,"lines":["Because he remembered his holy word, which he had spoken to his servant Abraham."]},{"v":43,"lines":["And he brought forth his people with joy, and his chosen with gladness."]},{"v":44,"lines":["And he gave them the lands of the Gentiles:","and they possessed the labours of the people:"]},{"v":45,"lines":["That they might observe his justifications, and seek after his law."]}]},{"n":105,"incipit":"Confitemini Domino","verses":[{"v":1,"lines":["Give glory to the Lord, for he is good:","for his mercy endureth for ever."]},{"v":2,"lines":["Who shall declare the powers of the Lord? who shall set forth all his praises?"]},{"v":3,"lines":["Blessed are they that keep judgment, and do justice at all times."]},{"v":4,"lines":["Remember us, O Lord, in the favour of thy people:","visit us with thy salvation."]},{"v":5,"lines":["That we may see the good of thy chosen, that we may rejoice in the joy of thy nation:","that thou mayst be praised with thy inheritance."]},{"v":6,"lines":["We have sinned with our fathers:","we have acted unjustly, we have wrought iniquity."]},{"v":7,"lines":["Our fathers understood not thy wonders in Egypt:","they remembered not the multitude of thy mercies:","And they provoked to wrath going up to the sea, even the Red Sea."]},{"v":8,"lines":["And he saved them for his own name's sake:","that he might make his power known."]},{"v":9,"lines":["And he rebuked the Red Sea and it was dried up:","and he led them through the depths, as in a wilderness."]},{"v":10,"lines":["And he saved them from the hand of them that hated them:","and he redeemed them from the hand of the enemy."]},{"v":11,"lines":["And the water covered them that afflicted them:","there was not one of them left."]},{"v":12,"lines":["And they believed his words:","and they sang his praises."]},{"v":13,"lines":["They had quickly done, they forgot his works:","and they waited not for his counsels."]},{"v":14,"lines":["And they coveted their desire in the desert:","and they tempted God in the place without water."]},{"v":15,"lines":["And he gave them their request:","and sent fulness into their souls."]},{"v":16,"lines":["And they provoked Moses in the camp, Aaron the holy one of the Lord."]},{"v":17,"lines":["The earth opened and swallowed up Dathan:","and covered the congregation of Abiron."]},{"v":18,"lines":["And a fire was kindled in their congregation:","the flame burned the wicked."]},{"v":19,"lines":["They made also a calf in Horeb:","and they adored the graven thing."]},{"v":20,"lines":["And they changed their glory into the likeness of a calf that eateth grass."]},{"v":21,"lines":["They forgot God, who saved them, who had done great things in Egypt,"]},{"v":22,"lines":["Wondrous works in the land of Cham:","terrible things in the Red Sea."]},{"v":23,"lines":["And he said that he would destroy them:","had not Moses his chosen stood before him in the breach:","To turn away his wrath, lest he should destroy them."]},{"v":24,"lines":["And they set at nought the desirable land. They believed not his word,"]},{"v":25,"lines":["And they murmured in their tents:","they hearkened not to the voice of the Lord."]},{"v":26,"lines":["And he lifted up his hand over them:","to overthrow them in the desert;"]},{"v":27,"lines":["And to cast down their seed among the nations, and to scatter them in the countries."]},{"v":28,"lines":["They also were initiated to Beelphegor:","and ate the sacrifices of the dead."]},{"v":29,"lines":["And they provoked him with their inventions:","and destruction was multiplied among them."]},{"v":30,"lines":["Then Phinees stood up, and pacified him:","and the slaughter ceased."]},{"v":31,"lines":["And it was reputed to him unto justice, to generation and generation for evermore."]},{"v":32,"lines":["They provoked him also at the waters of contradiction:","and Moses was afflicted for their sakes:"]},{"v":33,"lines":["Because they exasperated his spirit. And he distinguished with his lips."]},{"v":34,"lines":["They did not destroy the nations of which the Lord spoke unto them."]},{"v":35,"lines":["And they were mingled among the heathens, and learned their works:"]},{"v":36,"lines":["And served their idols, and it became a stumblingblock to them."]},{"v":37,"lines":["And they sacrificed their sons, and their daughters to devils."]},{"v":38,"lines":["And they shed innocent blood:","the blood of their sons and of their daughters which they sacrificed to the idols of Chanaan. And the land was polluted with blood,"]},{"v":39,"lines":["And was defiled with their works:","and they went aside after their own inventions."]},{"v":40,"lines":["And the Lord was exceedingly angry with his people:","and he abhorred his inheritance."]},{"v":41,"lines":["And he delivered them into the hands of the nations:","and they that hated them had dominion over them."]},{"v":42,"lines":["And their enemies afflicted them:","and they were humbled under their hands:"]},{"v":43,"lines":["Many times did he deliver them. But they provoked him with their counsel:","and they were brought low by their iniquities."]},{"v":44,"lines":["And he saw when they were in tribulation:","and he heard their prayer."]},{"v":45,"lines":["And he was mindful of his covenant:","and repented according to the multitude of his mercies."]},{"v":46,"lines":["And he gave them unto mercies, in the sight of all those that had made them captives."]},{"v":47,"lines":["Save us, O Lord, our God:","and gather us from among nations:","That we may give thanks to thy holy name, and may glory in thy praise."]},{"v":48,"lines":["Blessed be the Lord the God of Israel, from everlasting to everlasting:","and let all the people say:","So be it, so be it."]}]},{"n":106,"incipit":"Confitemini Domino","verses":[{"v":1,"lines":["Give glory to the Lord, for he is good:","for his mercy endureth for ever."]},{"v":2,"lines":["Let them say so that have been redeemed by the Lord, whom he hath redeemed from the hand of the enemy:","and gathered out of the countries."]},{"v":3,"lines":["From the rising and the setting of the sun, from the north and from the sea."]},{"v":4,"lines":["They wandered in a wilderness, in a place without water:","they found not the way of a city for their habitation."]},{"v":5,"lines":["They were hungry and thirsty:","their soul fainted in them."]},{"v":6,"lines":["And they cried to the Lord in their tribulation:","and he delivered them out of their distresses."]},{"v":7,"lines":["And he led them into the right way, that they might go to a city of habitation."]},{"v":8,"lines":["Let the mercies of the Lord give glory to him:","and his wonderful works to the children of men."]},{"v":9,"lines":["For he hath satisfied the empty soul, and hath filled the hungry soul with good things."]},{"v":10,"lines":["Such as sat in darkness and in the shadow of death:","bound in want and in iron."]},{"v":11,"lines":["Because they had exasperated the words of God:","and provoked the counsel of the most High:"]},{"v":12,"lines":["And their heart was humbled with labours:","they were weakened, and there was none to help them."]},{"v":13,"lines":["Then they cried to the Lord in their affliction:","and he delivered them out of their distresses."]},{"v":14,"lines":["And he brought them out of darkness, and the shadow of death;","and broke their bonds in sunder."]},{"v":15,"lines":["Let the mercies of the Lord give glory to him, and his wonderful works to the children of men."]},{"v":16,"lines":["Because he hath broken gates of brass, and burst the iron bars."]},{"v":17,"lines":["He took them out of the way of their iniquity:","for they were brought low for their injustices."]},{"v":18,"lines":["Their soul abhorred all manner of meat:","and they drew nigh even to the gates of death."]},{"v":19,"lines":["And they cried to the Lord in their affliction:","and he delivered them out of their distresses."]},{"v":20,"lines":["He sent his word, and healed them:","and delivered them from their destructions."]},{"v":21,"lines":["Let the mercies of the Lord give glory to him:","and his wonderful works to the children of men."]},{"v":22,"lines":["And let them sacrifice the sacrifice of praise:","and declare his works with joy."]},{"v":23,"lines":["They that go down to the sea in ships, doing business in the great waters:"]},{"v":24,"lines":["These have seen the works of the Lord, and his wonders in the deep."]},{"v":25,"lines":["He said the word, and there arose a storm of wind:","and the waves thereof were lifted up."]},{"v":26,"lines":["They mount up to the heavens, and they go down to the depths:","their soul pined away with evils."]},{"v":27,"lines":["They were troubled, and reeled like a drunken man;","and all their wisdom was swallowed up."]},{"v":28,"lines":["And they cried to the Lord in their affliction:","and he brought them out of their distresses."]},{"v":29,"lines":["And he turned the storm into a breeze:","and its waves were still."]},{"v":30,"lines":["And they rejoiced because they were still:","and he brought them to the haven which they wished for."]},{"v":31,"lines":["Let the mercies of the Lord give glory to him, and his wonderful works to the children of men."]},{"v":32,"lines":["And let them exalt him in the church of the people:","and praise him in the chair of the ancients."]},{"v":33,"lines":["He hath turned rivers into a wilderness:","and the sources of water into dry ground:"]},{"v":34,"lines":["A fruitful land into barrenness, for the wickedness of them that dwell therein."]},{"v":35,"lines":["He hath turned a wilderness into pools of water, and a dry land into water springs."]},{"v":36,"lines":["And hath placed there the hungry;","and they made a city for their habitation."]},{"v":37,"lines":["And they sowed fields, and planted vineyards:","and they yielded fruit of birth."]},{"v":38,"lines":["And he blessed them, and they were multiplied exceedingly:","and their cattle he suffered not to decrease."]},{"v":39,"lines":["Then they were brought to be few:","and they were afflicted through the trouble of evils and sorrow."]},{"v":40,"lines":["Contempt was poured forth upon their princes:","and he caused them to wander where there was no passing, and out of the way."]},{"v":41,"lines":["And he helped the poor out of poverty:","and made him families like a flock of sheep."]},{"v":42,"lines":["The just shall see, and shall rejoice, and all iniquity shall stop their mouth."]},{"v":43,"lines":["Who is wise, and will keep these things;","and will understand the mercies of the Lord?"]}]},{"n":107,"incipit":"Paratum cor meum","verses":[{"v":1,"lines":["A canticle of a psalm for David himself."],"title":true},{"v":2,"lines":["My heart is ready, O God, my heart is ready:","I will sing, and will give praise, with my glory."]},{"v":3,"lines":["Arise, my glory;","arise, psaltery and harp:","I will arise in the morning early."]},{"v":4,"lines":["I will praise thee, O Lord, among the people:","and I will sing unto thee among the populations."]},{"v":5,"lines":["For thy mercy is great above the heavens:","and thy truth even unto the clouds."]},{"v":6,"lines":["Be thou exalted, O God, above the heavens, and thy glory over all the earth:"]},{"v":7,"lines":["That thy beloved may be delivered. Save with thy right hand and hear me."]},{"v":8,"lines":["God hath spoken in his holiness. I will rejoice, and I will divide Sichem and I will mete out the vale of tabernacles."]},{"v":9,"lines":["Galaad is mine:","and Manasses is mine and Ephraim the protection of my head. Juda is my king:"]},{"v":10,"lines":["Moab the pot of my hope. Over Edom I will stretch out my shoe:","the aliens are become my friends."]},{"v":11,"lines":["Who will bring me into the strong city? who will lead me into Edom?"]},{"v":12,"lines":["Wilt not thou, O God, who hast cast us off? and wilt not thou, O God, go forth with our armies?"]},{"v":13,"lines":["O grant us help from trouble:","for vain is the help of man."]},{"v":14,"lines":["Through God we shall do mightily:","and he will bring our enemies to nothing."]}]},{"n":108,"incipit":"Deus, laudem","verses":[{"v":1,"lines":["Unto the end, a psalm for David."],"title":true},{"v":2,"lines":["O God, be not thou silent in my praise:","for the mouth of the wicked and the mouth of the deceitful man is opened against me."]},{"v":3,"lines":["They have spoken against me with deceitful tongues;","and they have compassed me about with words of hatred;","and have fought against me without cause."]},{"v":4,"lines":["Instead of making me a return of love, they detracted me:","but I gave myself to prayer."]},{"v":5,"lines":["And they repaid me evil for good:","and hatred for my love."]},{"v":6,"lines":["Set thou the sinner over him:","and may the devil stand at his right hand."]},{"v":7,"lines":["When he is judged, may he go out condemned;","and may his prayer be turned to sin."]},{"v":8,"lines":["May his days be few:","and his bishopric let another take."]},{"v":9,"lines":["May his children be fatherless, and his wife a widow."]},{"v":10,"lines":["Let his children be carried about vagabonds, and beg;","and let them be cast out of their dwellings."]},{"v":11,"lines":["May the usurer search all his substance:","and let strangers plunder his labours."]},{"v":12,"lines":["May there be none to help him:","nor none to pity his fatherless offspring."]},{"v":13,"lines":["May his posterity be cut off;","in one generation may his name be blotted out."]},{"v":14,"lines":["May the iniquity of his fathers be remembered in the sight of the Lord:","and let not the sin of his mother be blotted out."]},{"v":15,"lines":["May they be before the Lord continually, and let the memory of them perish from the earth:"]},{"v":16,"lines":["Because he remembered not to shew mercy,"]},{"v":17,"lines":["But persecuted the poor man and the beggar;","and the broken in heart, to put him to death."]},{"v":18,"lines":["And he loved cursing, and it shall come unto him:","and he would not have blessing, and it shall be far from him. And he put on cursing, like a garment:","and it went in like water into his entrails, and like oil in his bones."]},{"v":19,"lines":["May it be unto him like a garment which covereth him;","and like a girdle with which he is girded continually."]},{"v":20,"lines":["This is the work of them who detract me before the Lord;","and who speak evils against my soul."]},{"v":21,"lines":["But thou, O Lord, do with me for thy name's sake:","because thy mercy is sweet. Do thou deliver me,"]},{"v":22,"lines":["For I am poor and needy, and my heart is troubled within me."]},{"v":23,"lines":["I am taken away like the shadow when it declineth:","and I am shaken off as locusts."]},{"v":24,"lines":["My knees are weakened through fasting:","and my flesh is changed for oil."]},{"v":25,"lines":["And I am become a reproach to them:","they saw me and they shaked their heads."]},{"v":26,"lines":["Help me, O Lord my God;","save me;","according to thy mercy."]},{"v":27,"lines":["And let them know that this is thy hand:","and that thou, O Lord, hast done it."]},{"v":28,"lines":["They will curse and thou will bless:","let them that rise up against me be confounded:","but thy servant shall rejoice."]},{"v":29,"lines":["Let them that detract me be clothed with shame:","and let them be covered with their confusion as with a double cloak."]},{"v":30,"lines":["I will give great thanks to the Lord with my mouth:","and in the midst of many I will praise him."]},{"v":31,"lines":["Because he hath stood at the right hand of the poor, to save my soul from persecutors."]}]},{"n":109,"incipit":"Dixit Dominus","verses":[{"v":1,"lines":["The Lord said to my Lord:","Sit thou at my right hand:","Until I make thy enemies thy footstool."],"heading":"A psalm for David."},{"v":2,"lines":["The Lord will send forth the sceptre of thy power out of Sion:","rule thou in the midst of thy enemies."]},{"v":3,"lines":["With thee is the principality in the day of thy strength:","in the brightness of the saints:","from the womb before the day star I begot thee."]},{"v":4,"lines":["The Lord hath sworn, and he will not repent:","Thou art a priest for ever according to the order of Melchisedech."]},{"v":5,"lines":["The Lord at thy right hand hath broken kings in the day of his wrath."]},{"v":6,"lines":["He shall judge among nations, he shall fill ruins:","he shall crush the heads in the land of the many."]},{"v":7,"lines":["He shall drink of the torrent in the way:","therefore shall he lift up the head."]}]},{"n":110,"incipit":"Confitebor tibi","verses":[{"v":1,"lines":["I will praise thee, O Lord, with my whole heart;","in the council of the just, and in the congregation."]},{"v":2,"lines":["Great are the works of the Lord:","sought out according to all his wills."]},{"v":3,"lines":["His work is praise and magnificence:","and his justice continueth for ever and ever."]},{"v":4,"lines":["He hath made a remembrance of his wonderful works, being a merciful and gracious Lord:"]},{"v":5,"lines":["He hath given food to them that fear him. He will be mindful for ever of his covenant:"]},{"v":6,"lines":["He will shew forth to his people the power of his works."]},{"v":7,"lines":["That he may give them the inheritance of the Gentiles:","the works of his hands are truth and judgment."]},{"v":8,"lines":["All his commandments are faithful:","confirmed for ever and ever, made in truth and equity."]},{"v":9,"lines":["He hath sent redemption to his people:","he hath commanded his covenant for ever. Holy and terrible is his name:"]},{"v":10,"lines":["The fear of the Lord is the beginning of wisdom. A good understanding to all that do it:","his praise continueth for ever and ever."]}]},{"n":111,"incipit":"Beatus vir","verses":[{"v":1,"lines":["Blessed is the man that feareth the Lord:","he shall delight exceedingly in his commandments."]},{"v":2,"lines":["His seed shall be mighty upon earth:","the generation of the righteous shall be blessed."]},{"v":3,"lines":["Glory and wealth shall be in his house:","and his justice remaineth for ever and ever."]},{"v":4,"lines":["To the righteous a light is risen up in darkness:","he is merciful, and compassionate and just."]},{"v":5,"lines":["Acceptable is the man that sheweth mercy and lendeth:","he shall order his words with judgment:"]},{"v":6,"lines":["Because he shall not be moved for ever."]},{"v":7,"lines":["The just shall be in everlasting remembrance:","he shall not fear the evil hearing. His heart is ready to hope in the Lord:"]},{"v":8,"lines":["His heart is strengthened, he shall not be moved until he look over his enemies."]},{"v":9,"lines":["He hath distributed, he hath given to the poor:","his justice remaineth for ever and ever:","his horn shall be exalted in glory."]},{"v":10,"lines":["The wicked shall see, and shall be angry, he shall gnash with his teeth and pine away:","the desire of the wicked shall perish."]}]},{"n":112,"incipit":"Laudate, pueri","verses":[{"v":1,"lines":["Praise the Lord, ye children:","praise ye the name of the Lord."]},{"v":2,"lines":["Blessed be the name of the Lord, from henceforth now and for ever."]},{"v":3,"lines":["From the rising of the sun unto the going down of the same, the name of the Lord is worthy of praise."]},{"v":4,"lines":["The Lord is high above all nations;","and his glory above the heavens."]},{"v":5,"lines":["Who is as the Lord our God, who dwelleth on high:"]},{"v":6,"lines":["And looketh down on the low things in heaven and in earth?"]},{"v":7,"lines":["Raising up the needy from the earth, and lifting up the poor out of the dunghill:"]},{"v":8,"lines":["That he may place him with princes, with the princes of his people."]},{"v":9,"lines":["Who maketh a barren woman to dwell in a house, the joyful mother of children."]}]},{"n":113,"incipit":"In exitu Israel · Non nobis, Domine","verses":[{"v":1,"lines":["When Israel went out of Egypt, the house of Jacob from a barbarous people:"]},{"v":2,"lines":["Judea was made his sanctuary, Israel his dominion."]},{"v":3,"lines":["The sea saw and fled:","Jordan was turned back."]},{"v":4,"lines":["The mountains skipped like rams, and the hills like the lambs of the flock."]},{"v":5,"lines":["What ailed thee, O thou sea, that thou didst flee:","and thou, O Jordan, that thou wast turned back?"]},{"v":6,"lines":["Ye mountains, that ye skipped like rams, and ye hills, like lambs of the flock?"]},{"v":7,"lines":["At the presence of the Lord the earth was moved, at the presence of the God of Jacob:"]},{"v":8,"lines":["Who turned the rock into pools of water, and the stony hill into fountains of waters."]},{"v":9,"lines":["Not to us, O Lord, not to us;","but to thy name give glory."],"sectionStart":true},{"v":10,"lines":["For thy mercy, and for thy truth's sake:","lest the Gentiles should say:","Where is their God?"]},{"v":11,"lines":["But our God is in heaven:","he hath done all things whatsoever he would."]},{"v":12,"lines":["The idols of the Gentiles are silver and gold, the works of the hands of men."]},{"v":13,"lines":["They have mouths and speak not:","they have eyes and see not."]},{"v":14,"lines":["They have ears and hear not:","they have noses and smell not."]},{"v":15,"lines":["They have hands and feel not:","they have feet and walk not:","neither shall they cry out through their throat."]},{"v":16,"lines":["Let them that make them become like unto them:","and all such as trust in them."]},{"v":17,"lines":["The house of Israel hath hoped in the Lord:","he is their helper and their protector."]},{"v":18,"lines":["The house of Aaron hath hoped in the Lord:","he is their helper and their protector."]},{"v":19,"lines":["They that fear the Lord hath hoped in the Lord:","he is their helper and their protector."]},{"v":20,"lines":["The Lord hath been mindful of us, and hath blessed us. He hath blessed the house of Israel:","he hath blessed the house of Aaron."]},{"v":21,"lines":["He hath blessed all that fear the Lord, both little and great."]},{"v":22,"lines":["May the Lord add blessings upon you:","upon you, and upon your children."]},{"v":23,"lines":["Blessed be you of the Lord, who made heaven and earth."]},{"v":24,"lines":["The heaven of heaven is the Lord's:","but the earth he has given to the children of men."]},{"v":25,"lines":["The dead shall not praise thee, O Lord:","nor any of them that go down to hell."]},{"v":26,"lines":["But we that live bless the Lord:","from this time now and for ever."]}]},{"n":114,"incipit":"Dilexi, quoniam","verses":[{"v":1,"lines":["I have loved, because the Lord will hear the voice of my prayer."]},{"v":2,"lines":["Because he hath inclined his ear unto me:","and in my days I will call upon him."]},{"v":3,"lines":["The sorrows of death have encompassed me:","and the perils of hell have found me. I met with trouble and sorrow:"]},{"v":4,"lines":["And I called upon the name of the Lord. O Lord, deliver my soul."]},{"v":5,"lines":["The Lord is merciful and just, and our God sheweth mercy."]},{"v":6,"lines":["The Lord is the keeper of little ones:","I was little and he delivered me."]},{"v":7,"lines":["Turn, O my soul, into thy rest:","for the Lord hath been bountiful to thee."]},{"v":8,"lines":["For he hath delivered my soul from death:","my eyes from tears, my feet from falling."]},{"v":9,"lines":["I will please the Lord in the land of the living."]}]},{"n":115,"incipit":"Credidi, propter","verses":[{"v":1,"lines":["I have believed, therefore have I spoken;","but I have been humbled exceedingly."]},{"v":2,"lines":["I said in my excess:","Every man is a liar."]},{"v":3,"lines":["What shall I render to the Lord, for all the things he hath rendered unto me?"]},{"v":4,"lines":["I will take the chalice of salvation;","and I will call upon the name of the Lord."]},{"v":5,"lines":["I will pay my vows to the Lord before all his people:"]},{"v":6,"lines":["Precious in the sight of the Lord is the death of his saints."]},{"v":7,"lines":["O Lord, for I am thy servant:","I am thy servant, and the son of thy handmaid. Thou hast broken my bonds:"]},{"v":8,"lines":["I will sacrifice to thee the sacrifice of praise, and I will call upon the name of the Lord."]},{"v":9,"lines":["I will pay my vows to the Lord in the sight of all his people:"]},{"v":10,"lines":["In the courts of the house of the Lord, in the midst of thee, O Jerusalem."]}]},{"n":116,"incipit":"Laudate Dominum","verses":[{"v":1,"lines":["O Praise the Lord, all ye nations:","praise him, all ye people."]},{"v":2,"lines":["For his mercy is confirmed upon us:","and the truth of the Lord remaineth for ever."]}]},{"n":117,"incipit":"Confitemini Domino","verses":[{"v":1,"lines":["Give praise to the Lord, for he is good:","for his mercy endureth for ever."]},{"v":2,"lines":["Let Israel now say, that he is good:","that his mercy endureth for ever."]},{"v":3,"lines":["Let the house of Aaron now say, that his mercy endureth for ever."]},{"v":4,"lines":["Let them that fear the Lord now say, that his mercy endureth for ever."]},{"v":5,"lines":["In my trouble I called upon the Lord:","and the Lord heard me, and enlarged me."]},{"v":6,"lines":["The Lord is my helper:","I will not fear what man can do unto me."]},{"v":7,"lines":["The Lord is my helper:","and I will look over my enemies."]},{"v":8,"lines":["It is good to confide in the Lord, rather than to have confidence in man."]},{"v":9,"lines":["It is good to trust in the Lord, rather than to trust in princes."]},{"v":10,"lines":["All nations compassed me about;","and, in the name of the Lord I have been revenged on them."]},{"v":11,"lines":["Surrounding me they compassed me about:","and in the name of the Lord I have been revenged on them."]},{"v":12,"lines":["They surrounded me like bees, and they burned like fire among thorns:","and in the name of the Lord I was revenged on them."]},{"v":13,"lines":["Being pushed I was overturned that I might fall:","but the Lord supported me."]},{"v":14,"lines":["The Lord is my strength and my praise:","and he is become my salvation."]},{"v":15,"lines":["The voice of rejoicing and of salvation is in the tabernacles of the just."]},{"v":16,"lines":["The right hand of the Lord hath wrought strength:","the right hand of the Lord hath exulted me:","the right hand of the Lord hath wrought strength."]},{"v":17,"lines":["I shall not die, but live:","and shall declare the works of the Lord."]},{"v":18,"lines":["The Lord chastising hath chastised me:","but he hath not delivered me over to death."]},{"v":19,"lines":["Open ye to me the gates of justice:","I will go into them, and give praise to the Lord."]},{"v":20,"lines":["This is the gate of the Lord, the just shall enter into it."]},{"v":21,"lines":["I will give glory to thee because thou hast heard me:","and art become my salvation."]},{"v":22,"lines":["The stone which the builders rejected;","the same is become the head of the corner."]},{"v":23,"lines":["This is the Lord's doing, and it is wonderful in our eyes."]},{"v":24,"lines":["This is the day which the Lord hath made:","let us be glad and rejoice therein."]},{"v":25,"lines":["O Lord, save me:","O Lord, give good success."]},{"v":26,"lines":["Blessed be he that cometh in the name Lord. We have blessed you out of the house of the Lord."]},{"v":27,"lines":["The Lord is God, and he hath shone upon us. Appoint a solemn day, with shady boughs, even to the horn of the altar."]},{"v":28,"lines":["Thou art my God, and I will praise thee:","thou art my God, and I will exalt thee. I will praise thee, because thou hast heard me, and art become my salvation."]},{"v":29,"lines":["O praise ye the Lord, for he is good:","for his mercy endureth for ever."]}]},{"n":118,"incipit":"Beati immaculati","verses":[{"v":1,"lines":["Blessed are the undefiled in the way, who walk in the law of the Lord."],"heading":"Aleph"},{"v":2,"lines":["Blessed are they who search his testimonies :","that seek him with their whole heart."]},{"v":3,"lines":["For they that work iniquity, have not walked in his ways."]},{"v":4,"lines":["Thou hast commanded thy commandments to be kept most diligently."]},{"v":5,"lines":["O! that my ways may be directed to keep thy justifications."]},{"v":6,"lines":["Then shall I not be confounded, when I shall look into all thy commandments."]},{"v":7,"lines":["I will praise thee with uprightness of heart, when I shall have learned the judgments of thy justice."]},{"v":8,"lines":["I will keep thy justifications:","O! do not thou utterly forsake me."]},{"v":9,"lines":["By what doth a young man correct his way? by observing thy words."],"heading":"Beth"},{"v":10,"lines":["With my whole heart have I sought after thee:","let me not stray from thy commandments."]},{"v":11,"lines":["Thy words have I hidden in my heart, that I may not sin against thee."]},{"v":12,"lines":["Blessed art thou, O Lord:","teach me thy justifications."]},{"v":13,"lines":["With my lips I have pronounced all the judgments of thy mouth."]},{"v":14,"lines":["I have been delighted in the way of thy testimonies, as in all riches."]},{"v":15,"lines":["I will meditate on thy commandments:","and I will consider thy ways."]},{"v":16,"lines":["I will think of thy justifications:","I will not forget thy words."]},{"v":17,"lines":["Give bountifully to thy servant, enliven me:","and I shall keep thy words."],"heading":"Gimel"},{"v":18,"lines":["Open thou my eyes:","and I will consider the wondrous things of thy law."]},{"v":19,"lines":["I am a sojourner on the earth:","hide not thy commandments from me."]},{"v":20,"lines":["My soul hath coveted to long for thy justifications, at all times."]},{"v":21,"lines":["Thou hast rebuked the proud:","they are cursed who decline from thy commandments."]},{"v":22,"lines":["Remove from me reproach and contempt:","because I have sought after thy testimonies."]},{"v":23,"lines":["For princes sat, and spoke against me:","but thy servant was employed in thy justifications."]},{"v":24,"lines":["For thy testimonies are my meditation:","and thy justifications my counsel."]},{"v":25,"lines":["My soul hath cleaved to the pavement:","quicken thou me according to thy word."],"heading":"Daleth"},{"v":26,"lines":["I have declared my ways, and thou hast heard me:","teach me thy justifications."]},{"v":27,"lines":["Make me to understand the way of thy justifications:","and I shall be exercised in thy wondrous works."]},{"v":28,"lines":["My soul hath slumbered through heaviness:","strengthen thou me in thy words."]},{"v":29,"lines":["Remove from me the way of iniquity:","and out of thy law have mercy on me."]},{"v":30,"lines":["I have chosen the way of truth:","thy judgments I have not forgotten."]},{"v":31,"lines":["I have stuck to thy testimonies, O Lord:","put me not to shame."]},{"v":32,"lines":["I have run the way of thy commandments, when thou didst enlarge my heart."]},{"v":33,"lines":["Set before me for a law the way of thy justifications, O Lord:","and I will always seek after it."],"heading":"He"},{"v":34,"lines":["Give me understanding, and I will search thy law;","and I will keep it with my whole heart."]},{"v":35,"lines":["Lead me into the path of thy commandments;","for this same I have desired."]},{"v":36,"lines":["Incline my heart into thy testimonies and not to covetousness."]},{"v":37,"lines":["Turn away my eyes that they may not behold vanity:","quicken me in thy way."]},{"v":38,"lines":["Establish thy word to thy servant, in thy fear."]},{"v":39,"lines":["Turn away my reproach, which I have apprehended:","for thy judgments are delightful."]},{"v":40,"lines":["Behold I have longed after thy precepts:","quicken me in thy justice."]},{"v":41,"lines":["Let thy mercy also come upon me, O Lord:","thy salvation according to thy word."],"heading":"Vau"},{"v":42,"lines":["So shall I answer them that reproach me in any thing;","that I have trusted in thy words."]},{"v":43,"lines":["And take not thou the word of truth utterly out of my mouth:","for in thy words have I hoped exceedingly."]},{"v":44,"lines":["So shall I always keep thy law, for ever and ever."]},{"v":45,"lines":["And I walked at large:","because I have sought after thy commandments."]},{"v":46,"lines":["And I spoke of thy testimonies before kings:","and I was not ashamed."]},{"v":47,"lines":["I meditated also on thy commandments, which I loved."]},{"v":48,"lines":["And I lifted up my hands to thy commandments, which I loved:","and I was exercised in thy justifications."]},{"v":49,"lines":["Be thou mindful of thy word to thy servant, in which thou hast given me hope."],"heading":"Zain"},{"v":50,"lines":["This hath comforted me in my humiliation:","because thy word hath enlivened me."]},{"v":51,"lines":["The proud did iniquitously altogether:","but I declined not from thy law."]},{"v":52,"lines":["I remembered, O Lord, thy judgments of old:","and I was comforted."]},{"v":53,"lines":["A fainting hath taken hold of me, because of the wicked that forsake thy law."]},{"v":54,"lines":["Thy justifications were the subject of my song, in the place of my pilgrimage."]},{"v":55,"lines":["In the night I have remembered thy name, O Lord:","and have kept thy law."]},{"v":56,"lines":["This happened to me:","because I sought after thy justifications."]},{"v":57,"lines":["O Lord, my portion, I have said, I would keep thy law."],"heading":"Heth"},{"v":58,"lines":["I entreated thy face with all my heart:","have mercy on me according to thy word."]},{"v":59,"lines":["I have thought on my ways:","and turned my feet unto thy testimonies."]},{"v":60,"lines":["I am ready, and am not troubled:","that I may keep thy commandments."]},{"v":61,"lines":["The cords of the wicked have encompassed me:","but I have not forgotten thy law."]},{"v":62,"lines":["I rose at midnight to give praise to thee;","for the judgments of thy justification."]},{"v":63,"lines":["I am a partaker with all them that fear thee, and that keep thy commandments."]},{"v":64,"lines":["The earth, O Lord, is full of thy mercy:","teach me thy justifications."]},{"v":65,"lines":["Thou hast done well with thy servant, O Lord, according to thy word."],"heading":"Teth"},{"v":66,"lines":["Teach me goodness and discipline and knowledge;","for I have believed thy commandments."]},{"v":67,"lines":["Before I was humbled I offended;","therefore have I kept thy word."]},{"v":68,"lines":["Thou art good;","and in thy goodness teach me thy justifications."]},{"v":69,"lines":["The iniquity of the proud hath been multiplied over me:","but I will seek thy commandments with my whole heart."]},{"v":70,"lines":["Their heart is curdled like milk:","but I have meditated on thy law."]},{"v":71,"lines":["It is good for me that thou hast humbled me, that I may learn thy justifications."]},{"v":72,"lines":["The law of thy mouth is good to me, above thousands of gold and silver."]},{"v":73,"lines":["Thy hands have made me and formed me:","give me understanding, and I will learn thy commandments."],"heading":"Jod"},{"v":74,"lines":["They that fear thee shall see me, and shall be glad:","because I have greatly hoped in thy words."]},{"v":75,"lines":["I know, O Lord, that thy judgments are equity:","and in thy truth thou hast humbled me."]},{"v":76,"lines":["O! let thy mercy be for my comfort, according to thy word unto thy servant."]},{"v":77,"lines":["Let thy tender mercies come unto me, and I shall live:","for thy law is my meditation."]},{"v":78,"lines":["Let the proud be ashamed, because they have done unjustly towards me:","but I will be employed in thy commandments."]},{"v":79,"lines":["Let them that fear thee turn to me:","and they that know thy testimonies."]},{"v":80,"lines":["Let my heart be undefiled in thy justifications, that I may not be confounded."]},{"v":81,"lines":["My soul hath fainted after thy salvation:","and in thy word I have very much hoped."],"heading":"Caph"},{"v":82,"lines":["My eyes have failed for thy word, saying:","When wilt thou comfort me?"]},{"v":83,"lines":["For I am become like a bottle in the frost:","I have not forgotten thy justifications."]},{"v":84,"lines":["How many are the days of thy servant:","when wilt thou execute judgment on them that persecute me?"]},{"v":85,"lines":["The wicked have told me fables:","but not as thy law."]},{"v":86,"lines":["All thy statutes are truth:","they have persecuted me unjustly, do thou help me."]},{"v":87,"lines":["They had almost made an end of me upon earth:","but I have not forsaken thy commandments."]},{"v":88,"lines":["Quicken thou me according to thy mercy:","and I shall keep the testimonies of thy mouth."]},{"v":89,"lines":["For ever, O Lord, thy word standeth firm in heaven."],"heading":"Lamed"},{"v":90,"lines":["Thy truth unto all generations:","thou hast founded the earth, and it continueth."]},{"v":91,"lines":["By thy ordinance the day goeth on:","for all things serve thee."]},{"v":92,"lines":["Unless thy law had been my meditation, I had then perhaps perished in my abjection."]},{"v":93,"lines":["Thy justifications I will never forget:","for by them thou hast given me life."]},{"v":94,"lines":["I am thine, save thou me:","for I have sought thy justifications."]},{"v":95,"lines":["The wicked have waited for me to destroy me:","but I have understood thy testimonies."]},{"v":96,"lines":["I have seen an end to all persecution:","thy commandment is exceeding broad."]},{"v":97,"lines":["O how have I loved thy law, O Lord! it is my meditation all the day."],"heading":"Mem"},{"v":98,"lines":["Through thy commandment, thou hast made me wiser than my enemies:","for it is ever with me."]},{"v":99,"lines":["I have understood more than all my teachers:","because thy testimonies are my meditation."]},{"v":100,"lines":["I have had understanding above ancients:","because I have sought thy commandments."]},{"v":101,"lines":["I have restrained my feet from every evil way:","that I may keep thy words."]},{"v":102,"lines":["I have not declined from thy judgments, because thou hast set me a law."]},{"v":103,"lines":["How sweet are thy words to my palate! more than honey to my mouth."]},{"v":104,"lines":["By thy commandments I have had understanding:","therefore have I hated every way of iniquity."]},{"v":105,"lines":["Thy word is a lamp to my feet, and a light to my paths."],"heading":"Nun"},{"v":106,"lines":["I have sworn and am determined to keep the judgments of thy justice."]},{"v":107,"lines":["I have been humbled, O Lord, exceedingly:","quicken thou me according to thy word."]},{"v":108,"lines":["The free offerings of my mouth make acceptable, O Lord:","and teach me thy judgments."]},{"v":109,"lines":["My soul is continually in my hands:","and I have not forgotten thy law."]},{"v":110,"lines":["Sinners have laid a snare for me:","but I have not erred from thy precepts."]},{"v":111,"lines":["I have purchased thy testimonies for an inheritance for ever:","because they are a joy to my heart."]},{"v":112,"lines":["I have inclined my heart to do thy justifications for ever, for the reward."]},{"v":113,"lines":["I have hated the unjust:","and have loved thy law."],"heading":"Samech"},{"v":114,"lines":["Thou art my helper and my protector:","and in thy word I have greatly hoped."]},{"v":115,"lines":["Depart from me, ye malignant:","and I will search the commandments of my God."]},{"v":116,"lines":["Uphold me according to thy word, and I shall live:","and let me not be confounded in my expectation."]},{"v":117,"lines":["Help me, and I shall be saved:","and I will meditate always on thy justifications."]},{"v":118,"lines":["Thou hast despised all them that fall off from thy judgments;","for their thought is unjust."]},{"v":119,"lines":["I have accounted all the sinners of the earth prevaricators:","therefore have I loved thy testimonies."]},{"v":120,"lines":["Pierce thou my flesh with thy fear:","for I am afraid of thy judgments."]},{"v":121,"lines":["I have done judgment and justice:","give me not up to them that slander me."],"heading":"Ain"},{"v":122,"lines":["Uphold thy servant unto good:","let not the proud calumniate me."]},{"v":123,"lines":["My eyes have fainted after thy salvation:","and for the word of thy justice."]},{"v":124,"lines":["Deal with thy servant according to thy mercy:","and teach me thy justifications."]},{"v":125,"lines":["I am thy servant:","give me understanding that I may know thy testimonies."]},{"v":126,"lines":["It is time, O Lord, to do:","they have dissipated thy law."]},{"v":127,"lines":["Therefore have I loved thy commandments above gold and the topaz."]},{"v":128,"lines":["Therefore was I directed to all thy commandments:","I have hated all wicked ways."]},{"v":129,"lines":["Thy testimonies are wonderful:","therefore my soul hath sought them."],"heading":"Phe"},{"v":130,"lines":["The declaration of thy words giveth light:","and giveth understanding to little ones."]},{"v":131,"lines":["I opened my mouth, and panted:","because I longed for thy commandments."]},{"v":132,"lines":["Look thou upon me, and have mercy on me according to the judgment of them that love thy name."]},{"v":133,"lines":["Direct my steps according to thy word:","and let no iniquity have dominion over me."]},{"v":134,"lines":["Redeem me from the calumnies of men:","that I may keep thy commandments."]},{"v":135,"lines":["Make thy face to shine upon thy servant:","and teach me thy justifications."]},{"v":136,"lines":["My eyes have sent forth springs of water:","because they have not kept thy law."]},{"v":137,"lines":["Thou art just, O Lord:","and thy judgment is right."],"heading":"Sade"},{"v":138,"lines":["Thou hast commanded justice thy testimonies:","and thy truth exceedingly."]},{"v":139,"lines":["My zeal hath made me pine away:","because my enemies forgot thy words."]},{"v":140,"lines":["Thy word is exceedingly refined:","and thy servant hath loved it."]},{"v":141,"lines":["I am very young and despised;","but I forgot not thy justifications."]},{"v":142,"lines":["Thy justice is justice for ever:","and thy law is the truth."]},{"v":143,"lines":["Trouble and anguish have found me:","thy commandments are my meditation."]},{"v":144,"lines":["Thy testimonies are justice for ever:","give me understanding, and I shall live."]},{"v":145,"lines":["I cried with my whole heart, hear me, O Lord:","I will seek thy justifications."],"heading":"Coph"},{"v":146,"lines":["I cried unto thee, save me:","that I may keep thy commandments."]},{"v":147,"lines":["I prevented the dawning of the day, and cried:","because in thy words I very much hoped."]},{"v":148,"lines":["My eyes to thee have prevented the morning:","that I might meditate on thy words."]},{"v":149,"lines":["Hear thou my voice, O Lord, according to thy mercy:","and quicken me according to thy mercy."]},{"v":150,"lines":["They that persecute me have drawn nigh to iniquity;","but they are gone far off from thy law."]},{"v":151,"lines":["Thou art near, O Lord:","and all thy ways are truth."]},{"v":152,"lines":["I have known from the beginning concerning thy testimonies:","that thou hast founded them for ever."]},{"v":153,"lines":["See my humiliation and deliver me:","for I have not forgotten thy law."],"heading":"Res"},{"v":154,"lines":["Judge my judgment and redeem me:","quicken thou me for thy word's sake."]},{"v":155,"lines":["Salvation is far from sinners;","because they have not sought thy justifications."]},{"v":156,"lines":["Many, O Lord, are thy mercies:","quicken me according to thy judgment."]},{"v":157,"lines":["Many are they that persecute me and afflict me;","but I have not declined from thy testimonies."]},{"v":158,"lines":["I beheld the transgressors, and I pined away;","because they kept not thy word."]},{"v":159,"lines":["Behold I have loved thy commandments, O Lord;","quicken me thou in thy mercy."]},{"v":160,"lines":["The beginning of thy words is truth:","all the judgments of thy justice are for ever."]},{"v":161,"lines":["Princes have persecuted me without cause:","and my heart hath been in awe of thy words."],"heading":"Sin"},{"v":162,"lines":["I will rejoice at thy words, as one that hath found great spoil."]},{"v":163,"lines":["I have hated and abhorred iniquity;","but I have loved thy law."]},{"v":164,"lines":["Seven times a day I have given praise to thee, for the judgments of thy justice."]},{"v":165,"lines":["Much peace have they that love thy law, and to them there is no stumbling block."]},{"v":166,"lines":["I looked to thy salvation, O Lord:","and I loved thy commandments."]},{"v":167,"lines":["My soul hath kept thy testimonies and hath loved them exceedingly."]},{"v":168,"lines":["I have kept thy commandments and thy testimonies:","because all my ways are in thy sight."]},{"v":169,"lines":["Let my supplication, O Lord, come near in thy sight:","give me understanding according to thy word."],"heading":"Tau"},{"v":170,"lines":["Let my request come in before thee;","deliver thou me according to thy word."]},{"v":171,"lines":["My lips shall utter a hymn, when thou shalt teach me thy justifications."]},{"v":172,"lines":["My tongue shall pronounce thy word:","because all thy commandments are justice."]},{"v":173,"lines":["Let thy hand be with me to save me;","for I have chosen thy precepts."]},{"v":174,"lines":["I have longed for thy salvation, O Lord;","and thy law is my meditation."]},{"v":175,"lines":["My soul shall live and shall praise thee:","and thy judgments shall help me."]},{"v":176,"lines":["I have gone astray like a sheep that is lost:","seek thy servant, because I have not forgotten thy commandments."]}]},{"n":119,"incipit":"Ad Dominum","verses":[{"v":1,"lines":["In my trouble I cried to the Lord:","and he heard me."]},{"v":2,"lines":["O Lord, deliver my soul from wicked lips, and a deceitful tongue."]},{"v":3,"lines":["What shall be given to thee, or what shall be added to thee, to a deceitful tongue?"]},{"v":4,"lines":["The sharp arrows of the mighty, with coals that lay waste."]},{"v":5,"lines":["Woe is me, that my sojourning is prolonged! I have dwelt with the inhabitants of Cedar:"]},{"v":6,"lines":["My soul hath been long a sojourner."]},{"v":7,"lines":["With them that hated peace I was peaceable:","when I spoke to them they fought against me without cause."]}]},{"n":120,"incipit":"Levavi oculos","verses":[{"v":1,"lines":["I have lifted up my eyes to the mountains, from whence help shall come to me."]},{"v":2,"lines":["My help is from the Lord, who made heaven and earth."]},{"v":3,"lines":["May he not suffer thy foot to be moved:","neither let him slumber that keepeth thee."]},{"v":4,"lines":["Behold he shall neither slumber nor sleep, that keepeth Israel."]},{"v":5,"lines":["The Lord is thy keeper, the Lord is thy protection upon thy right hand."]},{"v":6,"lines":["The sun shall not burn thee by day:","nor the moon by night."]},{"v":7,"lines":["The Lord keepeth thee from all evil:","may the Lord keep thy soul."]},{"v":8,"lines":["May the Lord keep thy coming in and thy going out;","from henceforth now and for ever."]}]},{"n":121,"incipit":"Laetatus sum","verses":[{"v":1,"lines":["I rejoiced at the things that were said to me:","We shall go into the house of the Lord."],"heading":"A gradual canticle."},{"v":2,"lines":["Our feet were standing in thy courts, O Jerusalem."]},{"v":3,"lines":["Jerusalem, which is built as a city, which is compact together."]},{"v":4,"lines":["For thither did the tribes go up, the tribes of the Lord:","the testimony of Israel, to praise the name of the Lord."]},{"v":5,"lines":["Because their seats have sat in judgment, seats upon the house of David."]},{"v":6,"lines":["Pray ye for the things that are for the peace of Jerusalem:","and abundance for them that love thee."]},{"v":7,"lines":["Let peace be in thy strength:","and abundance in thy towers."]},{"v":8,"lines":["For the sake of my brethren, and of my neighbours, I spoke peace of thee."]},{"v":9,"lines":["Because of the house of the Lord our God, I have sought good things for thee."]}]},{"n":122,"incipit":"Ad te levavi oculos meos","verses":[{"v":1,"lines":["To thee have I lifted up my eyes, who dwellest in heaven."]},{"v":2,"lines":["Behold as the eyes of servants are on the hands of their masters, As the eyes of the handmaid are on the hands of her mistress:","so are our eyes unto the Lord our God, until he have mercy on us."]},{"v":3,"lines":["Have mercy on us, O Lord, have mercy on us:","for we are greatly filled with contempt."]},{"v":4,"lines":["For our soul is greatly filled:","we are a reproach to the rich, and contempt to the proud."]}]},{"n":123,"incipit":"Nisi quia Dominus","verses":[{"v":1,"lines":["If it had not been that the Lord was with us, let Israel now say:"],"heading":"A gradual canticle."},{"v":2,"lines":["If it had not been that the Lord was with us, When men rose up against us,"]},{"v":3,"lines":["Perhaps they had swallowed us up alive. When their fury was enkindled against us,"]},{"v":4,"lines":["Perhaps the waters had swallowed us up."]},{"v":5,"lines":["Our soul hath passed through a torrent:","perhaps our soul had passed through a water insupportable."]},{"v":6,"lines":["Blessed be the Lord, who hath not given us to be a prey to their teeth."]},{"v":7,"lines":["Our soul hath been delivered as a sparrow out of the snare of the fowlers. The snare is broken, and we are delivered."]},{"v":8,"lines":["Our help is in the name of the Lord, who made heaven and earth."]}]},{"n":124,"incipit":"Qui confidunt","verses":[{"v":1,"lines":["They that trust in the Lord shall be as mount Sion:","he shall not be moved for ever that dwelleth"],"heading":"A gradual canticle."},{"v":2,"lines":["In Jerusalem. Mountains are round about it:","so the Lord is round about his people from henceforth now and for ever."]},{"v":3,"lines":["For the Lord will not leave the rod of sinners upon the lot of the just:","that the just may not stretch forth their hands to iniquity."]},{"v":4,"lines":["Do good, O Lord, to those that are good, and to the upright of heart."]},{"v":5,"lines":["But such as turn aside into bonds, the Lord shall lead out with the workers of iniquity:","peace upon Israel."]}]},{"n":125,"incipit":"In convertendo","verses":[{"v":1,"lines":["When the Lord brought back the captivity of Sion, we became like men comforted."],"heading":"A gradual canticle."},{"v":2,"lines":["Then was our mouth filled with gladness;","and our tongue with joy. Then shall they say among the Gentiles:","The Lord hath done great things for them."]},{"v":3,"lines":["The Lord hath done great things for us:","we are become joyful."]},{"v":4,"lines":["Turn again our captivity, O Lord, as a stream in the south."]},{"v":5,"lines":["They that sow in tears shall reap in joy."]},{"v":6,"lines":["Going they went and wept, casting their seeds."]},{"v":7,"lines":["But coming they shall come with joyfulness, carrying their sheaves."]}]},{"n":126,"incipit":"Nisi Dominus","verses":[{"v":1,"lines":["Unless the Lord build the house, they labour in vain that build it. Unless the Lord keep the city, he watcheth in vain that keepeth it."],"heading":"A gradual canticle of Solomon."},{"v":2,"lines":["It is vain for you to rise before light, rise ye after you have sitten, you that eat the bread of sorrow. When he shall give sleep to his beloved,"]},{"v":3,"lines":["Behold the inheritance of the Lord are children:","the reward, the fruit of the womb."]},{"v":4,"lines":["As arrows in the hand of the mighty, so the children of them that have been shaken."]},{"v":5,"lines":["Blessed is the man that hath filled the desire with them;","he shall not be confounded when he shall speak to his enemies in the gate."]}]},{"n":127,"incipit":"Beati omnes","verses":[{"v":1,"lines":["Blessed are all they that fear the Lord:","that walk in his ways."],"heading":"A gradual canticle."},{"v":2,"lines":["For thou shalt eat the labours of thy hands:","blessed art thou, and it shall be well with thee."]},{"v":3,"lines":["Thy wife as a fruitful vine, on the sides of thy house. Thy children as olive plants, round about thy table."]},{"v":4,"lines":["Behold, thus shall the man be blessed that feareth the Lord."]},{"v":5,"lines":["May the Lord bless thee out of Sion:","and mayest thou see the good things of Jerusalem all the days of thy life."]},{"v":6,"lines":["And mayest thou see thy children's children, peace upon Israel."]}]},{"n":128,"incipit":"Saepe expugnaverunt","verses":[{"v":1,"lines":["Often have they fought against me from my youth, let Israel now say."],"heading":"A gradual canticle."},{"v":2,"lines":["Often have they fought against me from my youth:","but they could not prevail over me."]},{"v":3,"lines":["The wicked have wrought upon my back:","they have lengthened their iniquity."]},{"v":4,"lines":["The Lord who is just will cut the necks of sinners:"]},{"v":5,"lines":["Let them all be confounded and turned back that hate Sion."]},{"v":6,"lines":["Let them be as grass on the tops of houses:","which withered before it be plucked up:"]},{"v":7,"lines":["Wherewith the mower filleth not his hand:","nor he that gathereth sheaves his bosom."]},{"v":8,"lines":["And they that have passed by have not said:","The blessing of the Lord be upon you:","we have blessed you in the name of the Lord."]}]},{"n":129,"incipit":"De profundis","verses":[{"v":1,"lines":["Out of the depths I have cried to thee, O Lord:"],"heading":"A gradual canticle."},{"v":2,"lines":["Lord, hear my voice. Let thy ears be attentive to the voice of my supplication."]},{"v":3,"lines":["If thou, O Lord, wilt mark iniquities:","Lord, who shall stand it."]},{"v":4,"lines":["For with thee there is merciful forgiveness:","and by reason of thy law, I have waited for thee, O Lord. My soul hath relied on his word:"]},{"v":5,"lines":["My soul hath hoped in the Lord."]},{"v":6,"lines":["From the morning watch even until night, let Israel hope in the Lord."]},{"v":7,"lines":["Because with the Lord there is mercy:","and with him plentiful redemption."]},{"v":8,"lines":["And he shall redeem Israel from all his iniquities."]}]},{"n":130,"incipit":"Domine, non est","verses":[{"v":1,"lines":["Lord, my heart is not exalted:","nor are my eyes lofty. Neither have I walked in great matters, nor in wonderful things above me."],"heading":"A gradual canticle of David."},{"v":2,"lines":["If I was not humbly minded, but exalted my soul:","As a child that is weaned is towards his mother, so reward in my soul."]},{"v":3,"lines":["Let Israel hope in the Lord, from henceforth now and for ever."]}]},{"n":131,"incipit":"Memento, Domine","verses":[{"v":1,"lines":["O Lord, remember David, and all his meekness."],"heading":"A gradual canticle."},{"v":2,"lines":["How he swore to the Lord, he vowed a vow to the God of Jacob:"]},{"v":3,"lines":["If I shall enter into the tabernacle of my house:","if I shall go up into the bed wherein I lie:"]},{"v":4,"lines":["If I shall give sleep to my eyes, or slumber to my eyelids,"]},{"v":5,"lines":["Or rest to my temples:","until I find out a place for the Lord, a tabernacle for the God of Jacob."]},{"v":6,"lines":["Behold we have heard of it in Ephrata:","we have found it in the fields of the wood."]},{"v":7,"lines":["We will go into his tabernacle:","we will adore in the place where his feet stood."]},{"v":8,"lines":["Arise, O Lord, into thy resting place:","thou and the ark, which thou hast sanctified."]},{"v":9,"lines":["Let thy priests be clothed with justice:","and let thy saints rejoice."]},{"v":10,"lines":["For thy servant David's sake, turn not away the face of thy anointed."]},{"v":11,"lines":["The Lord hath sworn truth to David, and he will not make it void:","of the fruit of thy womb I will set upon thy throne."]},{"v":12,"lines":["If thy children will keep thy covenant, and these my testimonies which I shall teach them:","Their children also for evermore shall sit upon thy throne."]},{"v":13,"lines":["For the Lord hath chosen Sion:","he hath chosen it for his dwelling."]},{"v":14,"lines":["This is my rest for ever and ever:","here will I dwell, for I have chosen it."]},{"v":15,"lines":["Blessing I will bless her widow:","I will satisfy her poor with bread."]},{"v":16,"lines":["I will clothe her priests with salvation, and her saints shall rejoice with exceeding great joy."]},{"v":17,"lines":["There will I bring forth a horn to David:","I have prepared a lamp for my anointed."]},{"v":18,"lines":["His enemies I will clothe with confusion:","but upon him will my sanctification flourish."]}]},{"n":132,"incipit":"Ecce quam bonum!","verses":[{"v":1,"lines":["Behold how good and how pleasant it is for brethren to dwell in unity."],"heading":"A gradual canticle of David."},{"v":2,"lines":["Like the precious ointment on the head, that ran down upon the beard, the beard of Aaron, Which ran down to the skirt of his garment:"]},{"v":3,"lines":["As the dew of Hermon, which descendeth upon mount Sion. For there the Lord hath commandeth blessing, and life for evermore."]}]},{"n":133,"incipit":"Ecce nunc","verses":[{"v":1,"lines":["Behold now bless ye the Lord, all ye servants of the Lord:","Who stand in the house of the Lord, in the courts of the house of our God."],"heading":"A gradual canticle."},{"v":2,"lines":["In the nights lift up your hands to the holy places, and bless ye the Lord."]},{"v":3,"lines":["May the Lord out of Sion bless thee, he that made heaven and earth."]}]},{"n":134,"incipit":"Laudate nomen","verses":[{"v":1,"lines":["Praise ye the name of the Lord:","O you his servants, praise the Lord:"]},{"v":2,"lines":["You that stand in the house of the Lord, in the courts of the house of our God."]},{"v":3,"lines":["Praise ye the Lord, for the Lord is good:","sing ye to his name, for it is sweet."]},{"v":4,"lines":["For the Lord hath chosen Jacob unto himself:","Israel for his own possession."]},{"v":5,"lines":["For I have known that the Lord is great, and our God is above all gods."]},{"v":6,"lines":["Whatsoever the Lord hath pleased he hath done, in heaven, in earth, in the sea, and in all the deeps."]},{"v":7,"lines":["He bringeth up clouds from the end of the earth:","he hath made lightnings for the rain. He bringeth forth winds out of his stores:"]},{"v":8,"lines":["He slew the firstborn of Egypt from man even unto beast."]},{"v":9,"lines":["He sent forth signs and wonders in the midst of thee, O Egypt:","upon Pharao, and upon all his servants."]},{"v":10,"lines":["He smote many nations, and slew mighty kings:"]},{"v":11,"lines":["Sehon king of the Amorrhites, and Og king of Basan, and all the kingdoms of Chanaan."]},{"v":12,"lines":["And gave their land for an inheritance, for an inheritance to his people Israel."]},{"v":13,"lines":["Thy name, O Lord, is for ever:","thy memorial, O Lord, unto all generations."]},{"v":14,"lines":["For the Lord will judge his people, and will be entreated in favour of his servants."]},{"v":15,"lines":["The idols of the Gentiles are silver and gold, the works of men's hands."]},{"v":16,"lines":["They have a mouth, but they speak not:","they have eyes, but they see not."]},{"v":17,"lines":["They have ears, but they hear not:","neither is there any breath in their mouths."]},{"v":18,"lines":["Let them that make them be like to them:","and every one that trusteth in them."]},{"v":19,"lines":["Bless the Lord, O house of Israel:","bless the Lord, O house of Aaron."]},{"v":20,"lines":["Bless the Lord, O house of Levi:","you that fear the Lord, bless the Lord."]},{"v":21,"lines":["Blessed be the Lord out of Sion, who dwelleth in Jerusalem."]}]},{"n":135,"incipit":"Confitemini","verses":[{"v":1,"lines":["Praise the Lord , for he is good:","for his mercy endureth for ever."]},{"v":2,"lines":["Praise ye the God of gods:","for his mercy endureth for ever."]},{"v":3,"lines":["Praise ye the Lord of lords:","for his mercy endureth for ever."]},{"v":4,"lines":["Who alone doth great wonders:","for his mercy endureth for ever."]},{"v":5,"lines":["Who made the heavens in understanding:","for his mercy endureth for ever."]},{"v":6,"lines":["Who established the earth above the waters:","for his mercy endureth for ever."]},{"v":7,"lines":["Who made the great lights:","for his mercy endureth for ever."]},{"v":8,"lines":["The sun to rule over the day:","for his mercy endureth for ever."]},{"v":9,"lines":["The moon and the stars to rule the night:","for his mercy endureth for ever."]},{"v":10,"lines":["Who smote Egypt with their firstborn:","for his mercy endureth for ever."]},{"v":11,"lines":["Who brought out Israel from among them:","for his mercy endureth for ever."]},{"v":12,"lines":["With a mighty hand and a stretched out arm:","for his mercy endureth for ever."]},{"v":13,"lines":["Who divided the Red Sea into parts:","for his mercy endureth for ever."]},{"v":14,"lines":["And brought out Israel through the midst thereof:","for his mercy endureth for ever."]},{"v":15,"lines":["And overthrew Pharao and his host in the Red Sea:","for his mercy endureth for ever."]},{"v":16,"lines":["Who led his people through the desert:","for his mercy endureth for ever."]},{"v":17,"lines":["Who smote great kings:","for his mercy endureth for ever."]},{"v":18,"lines":["And slew strong kings:","for his mercy endureth for ever."]},{"v":19,"lines":["Sehon king of the Amorrhites:","for his mercy endureth for ever."]},{"v":20,"lines":["And Og king of Basan:","for his mercy endureth for ever."]},{"v":21,"lines":["And he gave their land for an inheritance:","for his mercy endureth for ever."]},{"v":22,"lines":["For an inheritance to his servant Israel:","for his mercy endureth for ever."]},{"v":23,"lines":["For he was mindful of us in our affliction:","for his mercy endureth for ever."]},{"v":24,"lines":["And he redeemed us from our enemies:","for his mercy endureth for ever."]},{"v":25,"lines":["Who giveth food to all flesh:","for his mercy endureth for ever."]},{"v":26,"lines":["Give glory to the God of heaven:","for his mercy endureth for ever."]},{"v":27,"lines":["Give glory to the Lord of lords:","for his mercy endureth for ever."]}]},{"n":136,"incipit":"Super flumina","verses":[{"v":1,"lines":["Upon the rivers of Babylon, there we sat and wept:","when we remembered Sion:"]},{"v":2,"lines":["On the willows in the midst thereof we hung up our instruments."]},{"v":3,"lines":["For there they that led us into captivity required of us the words of songs. And they that carried us away, said:","Sing ye to us a hymn of the songs of Sion."]},{"v":4,"lines":["How shall we sing the song of the Lord in a strange land?"]},{"v":5,"lines":["If I forget thee, O Jerusalem, let my right hand be forgotten."]},{"v":6,"lines":["Let my tongue cleave to my jaws, if I do not remember thee:","If I make not Jerusalem the beginning of my joy."]},{"v":7,"lines":["Remember, O Lord, the children of Edom, in the day of Jerusalem:","Who say:","Rase it, rase it, even to the foundation thereof."]},{"v":8,"lines":["O daughter of Babylon, miserable:","blessed shall he be who shall repay thee thy payment which thou hast paid us."]},{"v":9,"lines":["Blessed be he that shall take and dash thy little ones against the rock."]}]},{"n":137,"incipit":"Confitebor tibi","verses":[{"v":1,"lines":["I will praise thee, O Lord, with my whole heart:","for thou hast heard the words of my mouth. I will sing praise to thee in the sight of the angels:"],"heading":"For David himself."},{"v":2,"lines":["I will worship towards thy holy temple, and I will give glory to thy name. For thy mercy, and for thy truth:","for thou hast magnified thy holy name above all."]},{"v":3,"lines":["In what day soever I shall call upon thee, hear me:","thou shall multiply strength in my soul."]},{"v":4,"lines":["May all the kings of the earth give glory to thee:","for they have heard all the words of thy mouth."]},{"v":5,"lines":["And let them sing in the ways of the Lord:","for great is the glory of the Lord."]},{"v":6,"lines":["For the Lord is high, and looketh on the low:","and the high he knoweth afar off."]},{"v":7,"lines":["If I shall walk in the midst of tribulation, thou wilt quicken me:","and thou hast stretched forth thy hand against the wrath of my enemies:","and thy right hand hath saved me."]},{"v":8,"lines":["The Lord will repay for me:","thy mercy, O Lord, endureth for ever:","O despise not the work of thy hands."]}]},{"n":138,"incipit":"Domine, probasti","verses":[{"v":1,"lines":["Lord, thou hast proved me, and known me:"],"heading":"Unto the end, a psalm of David."},{"v":2,"lines":["Thou hast known my sitting down, and my rising up."]},{"v":3,"lines":["Thou hast understood my thoughts afar off:","my path and my line thou hast searched out."]},{"v":4,"lines":["And thou hast foreseen all my ways:","for there is no speech in my tongue."]},{"v":5,"lines":["Behold, O Lord, thou hast known all things, the last and those of old:","thou hast formed me, and hast laid thy hand upon me."]},{"v":6,"lines":["Thy knowledge is become wonderful to me:","it is high, and I cannot reach to it."]},{"v":7,"lines":["Whither shall I go from thy spirit? or whither shall I flee from thy face?"]},{"v":8,"lines":["If I ascend into heaven, thou art there:","if I descend into hell, thou art present."]},{"v":9,"lines":["If I take my wings early in the morning, and dwell in the uttermost parts of the sea:"]},{"v":10,"lines":["Even there also shall thy hand lead me:","and thy right hand shall hold me."]},{"v":11,"lines":["And I said:","Perhaps darkness shall cover me:","and night shall be my light in my pleasures."]},{"v":12,"lines":["But darkness shall not be dark to thee, and night shall be light as day:","the darkness thereof, and the light thereof are alike to thee."]},{"v":13,"lines":["For thou hast possessed my reins:","thou hast protected me from my mother's womb."]},{"v":14,"lines":["I will praise thee, for thou art fearfully magnified:","wonderful are thy works, and my soul knoweth right well."]},{"v":15,"lines":["My bone is not hidden from thee, which thou hast made in secret:","and my substance in the lower parts of the earth."]},{"v":16,"lines":["Thy eyes did see my imperfect being, and in thy book all shall be written:","days shall be formed, and no one in them."]},{"v":17,"lines":["But to me thy friends, O God, are made exceedingly honourable:","their principality is exceedingly strengthened."]},{"v":18,"lines":["I will number them, and they shall be multiplied above the sand, I rose up and am still with thee."]},{"v":19,"lines":["If thou wilt kill the wicked, O God:","ye men of blood, depart from me:"]},{"v":20,"lines":["Because you say in thought:","They shall receive thy cities in vain."]},{"v":21,"lines":["Have I not hated them, O Lord, that hated thee:","and pine away because of thy enemies?"]},{"v":22,"lines":["I have hated them with a perfect hatred:","and they are become enemies to me."]},{"v":23,"lines":["Prove me, O God, and know my heart:","examine me, and know my paths."]},{"v":24,"lines":["And see if there be in me the way of iniquity:","and lead me in the eternal way."]}]},{"n":139,"incipit":"Eripe me, Domine","verses":[{"v":1,"lines":["Unto the end, a psalm of David."],"title":true},{"v":2,"lines":["Deliver me, O Lord, from the evil man:","rescue me from the unjust man."]},{"v":3,"lines":["Who have devised iniquities in their hearts:","all the day long they designed battles."]},{"v":4,"lines":["They have sharpened their tongues like a serpent:","the venom of asps is under their lips."]},{"v":5,"lines":["Keep me, O Lord, from the hand of the wicked:","and from unjust men deliver me. Who have proposed to supplant my steps:"]},{"v":6,"lines":["The proud have hidden a net for me. And they have stretched out cords for a snare:","they have laid for me a stumblingblock by the wayside."]},{"v":7,"lines":["I said to the Lord:","Thou art my God:","hear, O Lord, the voice of my supplication."]},{"v":8,"lines":["O Lord, Lord, the strength of my salvation:","thou hast overshadowed my head in the day of battle."]},{"v":9,"lines":["Give me not up, O Lord, from my desire to the wicked:","they have plotted against me;","do not thou forsake me, lest they should triumph."]},{"v":10,"lines":["The head of them compassing me about:","the labour of their lips shall overwhelm them."]},{"v":11,"lines":["Burning coals shall fall upon them;","thou wilt cast them down into the fire:","in miseries they shall not be able to stand."]},{"v":12,"lines":["A man full of tongue shall not be established in the earth:","evil shall catch the unjust man unto destruction."]},{"v":13,"lines":["I know that the Lord will do justice to the needy, and will revenge the poor."]},{"v":14,"lines":["But as for the just, they shall give glory to thy name:","and the upright shall dwell with thy countenance."]}]},{"n":140,"incipit":"Domine, clamavi","verses":[{"v":1,"lines":["I have cried to thee, O Lord, hear me:","hearken to my voice, when I cry to thee."]},{"v":2,"lines":["Let my prayer be directed as incense in thy sight;","the lifting up of my hands, as evening sacrifice."]},{"v":3,"lines":["Set a watch, O Lord, before my mouth:","and a door round about my lips."]},{"v":4,"lines":["Incline not my heart to evil words;","to make excuses in sins. With men that work iniquity:","and I will not communicate with the choicest of them."]},{"v":5,"lines":["The just shall correct me in mercy, and shall reprove me:","but let not the oil of the sinner fatten my head. For my prayer also shall still be against the things with which they are well pleased:"]},{"v":6,"lines":["Their judges falling upon the rock have been swallowed up. They shall hear my words, for they have prevailed:"]},{"v":7,"lines":["As when the thickness of the earth is broken up upon the ground:","Our bones are scattered by the side of hell."]},{"v":8,"lines":["But o to thee, O Lord, Lord, are my eyes:","in thee have I put my trust, take not away my soul."]},{"v":9,"lines":["Keep me from the snare, which they have laid for me, and from the stumblingblocks of them that work iniquity."]},{"v":10,"lines":["The wicked shall fall in his net:","I am alone until I pass."]}]},{"n":141,"incipit":"Voce mea ad Dominum","verses":[{"v":1,"lines":["Of understanding for David, A prayer when he was in the cave."],"title":true},{"v":2,"lines":["I cried to the Lord with my voice:","with my voice I made supplication to the Lord."]},{"v":3,"lines":["In his sight I pour out my prayer, and before him I declare my trouble:"]},{"v":4,"lines":["When my spirit failed me, then thou knewest my paths. In this way wherein I walked, they have hidden a snare for me."]},{"v":5,"lines":["I looked on my right hand, and beheld, and there was no one that would know me. Flight hath failed me:","and there is no one that hath regard to my soul."]},{"v":6,"lines":["I cried to thee, O Lord:","I said:","Thou art my hope, my portion in the land of the living."]},{"v":7,"lines":["Attend to my supplication:","for I am brought very low. Deliver me from my persecutors;","for they are stronger than I."]},{"v":8,"lines":["Bring my soul out of prison, that I may praise thy name:","the just wait for me, until thou reward me."]}]},{"n":142,"incipit":"Domine, exaudi","verses":[{"v":1,"lines":["Hear, O Lord, my prayer:","give ear to my supplication in thy truth:","hear me in thy justice."],"heading":"A psalm of David, when his son Absalom pursued him."},{"v":2,"lines":["And enter not into judgment with thy servant:","for in thy sight no man living shall be justified."]},{"v":3,"lines":["For the enemy hath persecuted my soul:","he hath brought down my life to the earth. He hath made me to dwell in darkness as those that have been dead of old:"]},{"v":4,"lines":["And my spirit is in anguish within me:","my heart within me is troubled."]},{"v":5,"lines":["I remembered the days of old, I meditated on all thy works:","I meditated upon the works of thy hands."]},{"v":6,"lines":["I stretched forth my hands to thee:","my soul is as earth without water unto thee."]},{"v":7,"lines":["Hear me speedily, O Lord:","my spirit hath fainted away. Turn not away thy face from me, lest I be like unto them that go down into the pit."]},{"v":8,"lines":["Cause me to hear thy mercy in the morning;","for in thee have I hoped. Make the way known to me, wherein I should walk:","for I have lifted up my soul to thee."]},{"v":9,"lines":["Deliver me from my enemies, O Lord, to thee have I fled:"]},{"v":10,"lines":["Teach me to do thy will, for thou art my God. Thy good spirit shall lead me into the right land:"]},{"v":11,"lines":["For thy name's sake, O Lord, thou wilt quicken me in thy justice. Thou wilt bring my soul out of trouble:"]},{"v":12,"lines":["And in thy mercy thou wilt destroy my enemies. And thou wilt cut off all them that afflict my soul:","for I am thy servant."]}]},{"n":143,"incipit":"Benedictus Dominus","verses":[{"v":1,"lines":["Blessed be the Lord my God, who teacheth my hands to fight, and my fingers to war."]},{"v":2,"lines":["My mercy, and my refuge:","my support, and my deliverer:","My protector, and I have hoped in him:","who subdueth my people under me."]},{"v":3,"lines":["Lord, what is man, that thou art made known to him? or the son of man, that thou makest account of him?"]},{"v":4,"lines":["Man is like to vanity:","his days pass away like a shadow."]},{"v":5,"lines":["Lord, bow down thy heavens and descend:","touch the mountains, and they shall smoke."]},{"v":6,"lines":["Send forth lightning, and thou shalt scatter them:","shoot out thy arrows, and thou shalt trouble them."]},{"v":7,"lines":["Put forth thy hand from on high, take me out, and deliver me from many waters:","from the hand of strange children:"]},{"v":8,"lines":["Whose mouth hath spoken vanity:","and their right hand is the right hand of iniquity."]},{"v":9,"lines":["To thee, O God, I will sing a new canticle:","on the psaltery and an instrument of ten strings I will sing praises to thee."]},{"v":10,"lines":["Who givest salvation to kings:","who hast redeemed thy servant David from the malicious sword:"]},{"v":11,"lines":["Deliver me, And rescue me out of the hand of strange children;","whose mouth hath spoken vanity:","and their right hand is the right hand of iniquity:"]},{"v":12,"lines":["Whose sons are as new plants in their youth:","Their daughters decked out, adorned round about after the similitude of a temple:"]},{"v":13,"lines":["Their storehouses full, flowing out of this into that. Their sheep fruitful in young, abounding in their goings forth:"]},{"v":14,"lines":["Their oxen fat. There is no breach of wall, nor passage, nor crying out in their streets."]},{"v":15,"lines":["They have called the people happy, that hath these things:","but happy is that people whose God is the Lord."]}]},{"n":144,"incipit":"Exaltabo te, Deus","verses":[{"v":1,"lines":["I will extol thee, O God my king:","and I will bless thy name for ever;","yea, for ever and ever."],"heading":"Praise, for David himself."},{"v":2,"lines":["Every day I will bless thee:","and I will praise thy name for ever;","yea, for ever and ever."]},{"v":3,"lines":["Great is the Lord, and greatly to be praised:","and of his greatness there is no end."]},{"v":4,"lines":["Generation and generation shall praise thy works:","and they shall declare thy power."]},{"v":5,"lines":["They shall speak of the magnificence of the glory of thy holiness:","and shall tell thy wondrous works."]},{"v":6,"lines":["And they shall speak of the might of thy terrible acts:","and shall declare thy greatness."]},{"v":7,"lines":["They shall publish the memory of the abundance of thy sweetness:","and shall rejoice in thy justice."]},{"v":8,"lines":["The Lord is gracious and merciful:","patient and plenteous in mercy."]},{"v":9,"lines":["The Lord is sweet to all:","and his tender mercies are over all his works."]},{"v":10,"lines":["Let all thy works, O lord, praise thee:","and let thy saints bless thee."]},{"v":11,"lines":["They shall speak of the glory of thy kingdom:","and shall tell of thy power:"]},{"v":12,"lines":["To make thy might known to the sons of men:","and the glory of the magnificence of thy kingdom."]},{"v":13,"lines":["Thy kingdom is a kingdom of all ages:","and thy dominion endureth throughout all generations. The Lord is faithful in all his words:","and holy in all his works."]},{"v":14,"lines":["The Lord lifteth up all that fall:","and setteth up all that are cast down."]},{"v":15,"lines":["The eyes of all hope in thee, O Lord:","and thou givest them meat in due season."]},{"v":16,"lines":["Thou openest thy hand, and fillest with blessing every living creature."]},{"v":17,"lines":["The Lord is just in all his ways:","and holy in all his works."]},{"v":18,"lines":["The Lord is nigh unto all them that call upon him:","to all that call upon him in truth."]},{"v":19,"lines":["He will do the will of them that fear him:","and he will hear their prayer, and save them."]},{"v":20,"lines":["The Lord keepeth all them that love him;","but all the wicked he will destroy."]},{"v":21,"lines":["My mouth shall speak the praise of the Lord:","and let all flesh bless thy holy name for ever;","yea, for ever and ever."]}]},{"n":145,"incipit":"Lauda, anima mea","verses":[{"v":1,"lines":["Alleluia, of Aggeus and Zacharias."],"title":true},{"v":2,"lines":["Praise the Lord, O my soul, in my life I will praise the Lord:","I will sing to my God as long as I shall be. Put not your trust in princes:"]},{"v":3,"lines":["In the children of men, in whom there is no salvation."]},{"v":4,"lines":["His spirit shall go forth, and he shall return into his earth:","in that day all their thoughts shall perish."]},{"v":5,"lines":["Blessed is he who hath the God of Jacob for his helper, whose hope is in the Lord his God:"]},{"v":6,"lines":["Who made heaven and earth, the sea, and all things that are in them."]},{"v":7,"lines":["Who keepeth truth for ever:","who executeth judgment for them that suffer wrong:","who giveth food to the hungry. The Lord looseth them that are fettered:"]},{"v":8,"lines":["The Lord enlighteneth the blind. The Lord lifteth up them that are cast down:","the Lord loveth the just."]},{"v":9,"lines":["The Lord keepeth the strangers, he will support the fatherless and the widow:","and the ways of sinners he will destroy."]},{"v":10,"lines":["The Lord shall reign for ever:","thy God, O Sion, unto generation and generation."]}]},{"n":146,"incipit":"Laudate Dominum, quoniam bonus","verses":[{"v":1,"lines":["Praise ye the Lord, because psalm is good:","to our God be joyful and comely praise."]},{"v":2,"lines":["The Lord buildeth up Jerusalem:","he will gather together the dispersed of Israel."]},{"v":3,"lines":["Who healeth the broken of heart, and bindeth up their bruises."]},{"v":4,"lines":["Who telleth the number of the stars:","and calleth them all by their names."]},{"v":5,"lines":["Great is our Lord, and great is his power:","and of his wisdom there is no number."]},{"v":6,"lines":["The Lord lifteth up the meek, and bringeth the wicked down even to the ground."]},{"v":7,"lines":["Sing ye to the Lord with praise:","sing to our God upon the harp."]},{"v":8,"lines":["Who covereth the heaven with clouds, and prepareth rain for the earth. Who maketh grass to grow on the mountains, and herbs for the service of men."]},{"v":9,"lines":["Who giveth to beasts their food:","and to the young ravens that call upon him."]},{"v":10,"lines":["He shall not delight in the strength of the horse:","nor take pleasure in the legs of a man."]},{"v":11,"lines":["The Lord taketh pleasure in them that fear him:","and in them that hope in his mercy."]}]},{"n":147,"incipit":"Lauda, Jerusalem","verses":[{"v":1,"lines":["Praise the Lord, O Jerusalem:","praise thy God, O Sion."]},{"v":2,"lines":["Because he hath strengthened the bolts of thy gates, he hath blessed thy children within thee."]},{"v":3,"lines":["Who hath placed peace in thy borders:","and filleth thee with the fat of corn."]},{"v":4,"lines":["Who sendeth forth his speech to the earth:","his word runneth swiftly."]},{"v":5,"lines":["Who giveth snow like wool:","scattereth mists like ashes."]},{"v":6,"lines":["He sendeth his crystal like morsels:","who shall stand before the face of his cold?"]},{"v":7,"lines":["He shall send out his word, and shall melt them:","his wind shall blow, and the waters shall run."]},{"v":8,"lines":["Who declareth his word to Jacob:","his justices and his judgments to Israel."]},{"v":9,"lines":["He hath not done in like manner to every nation:","and his judgments he hath not made manifest to them. Alleluia."]}]},{"n":148,"incipit":"Laudate Dominum","verses":[{"v":1,"lines":["Praise ye the Lord from the heavens:","praise ye him in the high places."]},{"v":2,"lines":["Praise ye him, all his angels, praise ye him, all his hosts."]},{"v":3,"lines":["Praise ye him, O sun and moon:","praise him, all ye stars and light."]},{"v":4,"lines":["Praise him, ye heavens of heavens:","and let all the waters that are above the heavens"]},{"v":5,"lines":["Praise the name of the Lord. For he spoke, and they were made:","he commanded, and they were created."]},{"v":6,"lines":["He hath established them for ever, and for ages of ages:","he hath made a decree, and it shall not pass away."]},{"v":7,"lines":["Praise the Lord from the earth, ye dragons, and all ye deeps:"]},{"v":8,"lines":["Fire, hail, snow, ice, stormy winds which fulfill his word:"]},{"v":9,"lines":["Mountains and all hills, fruitful trees and all cedars:"]},{"v":10,"lines":["Beasts and all cattle:","serpents and feathered fowls:"]},{"v":11,"lines":["Kings of the earth and all people:","princes and all judges of the earth:"]},{"v":12,"lines":["Young men and maidens:","let the old with the younger, praise the name of the Lord:"]},{"v":13,"lines":["For his name alone is exalted."]},{"v":14,"lines":["The praise of him is above heaven and earth:","and he hath exalted the horn of his people. A hymn to all his saints to the children of Israel, a people approaching to him. Alleluia."]}]},{"n":149,"incipit":"Cantate Domino","verses":[{"v":1,"lines":["Sing ye to the Lord a new canticle:","let his praise be in the church of the saints."]},{"v":2,"lines":["Let Israel rejoice in him that made him:","and let the children of Sion be joyful in their king."]},{"v":3,"lines":["Let them praise his name in choir:","let them sing to him with the timbrel and the psaltery."]},{"v":4,"lines":["For the Lord is well pleased with his people:","and he will exalt the meek unto salvation."]},{"v":5,"lines":["The saints shall rejoice in glory:","they shall be joyful in their beds."]},{"v":6,"lines":["The high praise of God shall be in their mouth:","and two-edged swords in their hands:"]},{"v":7,"lines":["To execute vengeance upon the nations, chastisements among the people:"]},{"v":8,"lines":["To bind their kings with fetters, and their nobles with manacles of iron."]},{"v":9,"lines":["To execute upon them the judgment that is written:","this glory is to all his saints. Alleluia."]}]},{"n":150,"incipit":"Laudate Dominum","verses":[{"v":1,"lines":["Praise ye the Lord in his holy places:","praise ye him in the firmament of his power."]},{"v":2,"lines":["Praise ye him for his mighty acts:","praise ye him according to the multitude of his greatness."]},{"v":3,"lines":["Praise him with sound of trumpet:","praise him with psaltery and harp."]},{"v":4,"lines":["Praise him with timbrel and choir:","praise him with strings and organs."]},{"v":5,"lines":["Praise him on high sounding cymbals:","praise him on cymbals of joy:","let every spirit praise the Lord. Alleluia."]}]}]};
